":["secure place"]},{"groupKey":"g1","groupName":"Nhóm 1 - Nền tảng Band 3.5-5.0","topicName":"Crime & Safety","word":"unsafe area","meaning":"a location where there is a significant risk of crime or harm","translation":"khu vực không an toàn","example":"Poor lighting can make a street feel like an unsafe area.","synonyms":["dangerous area"]},{"groupKey":"g1","groupName":"Nhóm 1 - Nền tảng Band 3.5-5.0","topicName":"Crime & Safety","word":"security camera","meaning":"a camera used to monitor an area for safety or crime prevention","translation":"camera an ninh","example":"A security camera may discourage theft.","synonyms":["surveillance camera"]},{"groupKey":"g1","groupName":"Nhóm 1 - Nền tảng Band 3.5-5.0","topicName":"Crime & Safety","word":"lock a door","meaning":"to secure a door so it cannot be opened freely","translation":"khóa cửa","example":"Residents should lock the door when leaving home.","synonyms":["secure a door"]},{"groupKey":"g1","groupName":"Nhóm 1 - Nền tảng Band 3.5-5.0","topicName":"Crime & Safety","word":"call the police","meaning":"to contact police for help","translation":"gọi cảnh sát","example":"Witnesses should call the police after a serious accident.","synonyms":["contact law enforcement"]},{"groupKey":"g1","groupName":"Nhóm 1 - Nền tảng Band 3.5-5.0","topicName":"Crime & Safety","word":"report a crime","meaning":"to tell the police or another authority about an offence","translation":"báo cáo tội phạm","example":"Victims sometimes hesitate to report a crime.","synonyms":["inform police"]},{"groupKey":"g1","groupName":"Nhóm 1 - Nền tảng Band 3.5-5.0","topicName":"Crime & Safety","word":"road crime","meaning":"an illegal act involving vehicles or roads","translation":"tội phạm giao thông","example":"Dangerous driving is a common type of road crime.","synonyms":["traffic offence"]},{"groupKey":"g1","groupName":"Nhóm 1 - Nền tảng Band 3.5-5.0","topicName":"Crime & Safety","word":"steal a car","meaning":"to take a vehicle illegally","translation":"ăn cắp xe","example":"Modern security systems can make it harder to steal a car.","synonyms":["take a car illegally"]},{"groupKey":"g1","groupName":"Nhóm 1 - Nền tảng Band 3.5-5.0","topicName":"Crime & Safety","word":"personal safety","meaning":"protection of an individual from injury or crime","translation":"an toàn cá nhân","example":"Good street lighting can improve personal safety.","synonyms":["individual security"]},{"groupKey":"g1","groupName":"Nhóm 1 - Nền tảng Band 3.5-5.0","topicName":"Crime & Safety","word":"emergency number","meaning":"a telephone number used to request urgent public help","translation":"số điện thoại khẩn cấp","example":"Children should know the local emergency number.","synonyms":["emergency hotline"]},{"groupKey":"g1","groupName":"Nhóm 1 - Nền tảng Band 3.5-5.0","topicName":"Crime & Safety","word":"warning sign","meaning":"a sign that tells people about possible danger","translation":"biển cảnh báo","example":"A warning sign should be placed near a dangerous road.","synonyms":["safety sign"]},{"groupKey":"g1","groupName":"Nhóm 1 - Nền tảng Band 3.5-5.0","topicName":"Crime & Safety","word":"crime rate","meaning":"the amount of crime in a particular area or period","translation":"tỷ lệ tội phạm","example":"Residents are concerned about the local crime rate.","synonyms":["level of crime"]},{"groupKey":"g1","groupName":"Nhóm 1 - Nền tảng Band 3.5-5.0","topicName":"Government & Public Services","word":"public hospital","meaning":"a hospital mainly funded and managed by government","translation":"bệnh viện công","example":"A public hospital should provide affordable care.","synonyms":["state hospital"]},{"groupKey":"g1","groupName":"Nhóm 1 - Nền tảng Band 3.5-5.0","topicName":"Government & Public Services","word":"public school","meaning":"a school funded by government","translation":"trường công","example":"Many children attend a public school near their home.","synonyms":["state school"]},{"groupKey":"g1","groupName":"Nhóm 1 - Nền 