:"transport provided for general public use","translation":"dịch vụ giao thông công cộng","example":"A frequent public transport service reduces car use.","synonyms":["transit service"]},{"groupKey":"g1","groupName":"Nhóm 1 - Nền tảng Band 3.5-5.0","topicName":"Government & Public Services","word":"community centre","meaning":"a public building used for local activities and services","translation":"trung tâm cộng đồng","example":"The community centre offers free classes for older residents.","synonyms":["civic centre"]},{"groupKey":"g1","groupName":"Nhóm 1 - Nền tảng Band 3.5-5.0","topicName":"Government & Public Services","word":"public library","meaning":"a library open to everyone in a community","translation":"thư viện công cộng","example":"A public library gives people free access to books.","synonyms":["community library"]},{"groupKey":"g1","groupName":"Nhóm 1 - Nền tảng Band 3.5-5.0","topicName":"Government & Public Services","word":"public park service","meaning":"the management and maintenance of parks for residents","translation":"dịch vụ quản lý công viên","example":"A good public park service keeps green areas clean and safe.","synonyms":["parks service"]},{"groupKey":"g1","groupName":"Nhóm 1 - Nền tảng Band 3.5-5.0","topicName":"Government & Public Services","word":"pay tax","meaning":"to give required money to government","translation":"nộp thuế","example":"Most workers must pay tax on their income.","synonyms":["pay taxes"]},{"groupKey":"g1","groupName":"Nhóm 1 - Nền tảng Band 3.5-5.0","topicName":"Government & Public Services","word":"vote","meaning":"to choose a person or option in an election","translation":"bỏ phiếu","example":"Citizens can vote for local representatives.","synonyms":["cast a vote"]},{"groupKey":"g1","groupName":"Nhóm 1 - Nền tảng Band 3.5-5.0","topicName":"Government & Public Services","word":"public decision","meaning":"a choice made by government or local authorities","translation":"quyết định công","example":"Major public decisions should consider community needs.","synonyms":["government decision"]},{"groupKey":"g1","groupName":"Nhóm 1 - Nền tảng Band 3.5-5.0","topicName":"Government & Public Services","word":"community project","meaning":"an organised activity intended to improve a local area","translation":"dự án cộng đồng","example":"The council funded a community project for young people.","synonyms":["local project"]},{"groupKey":"g1","groupName":"Nhóm 1 - Nền tảng Band 3.5-5.0","topicName":"Government & Public Services","word":"public problem","meaning":"an issue affecting many people in society","translation":"vấn đề công cộng","example":"Traffic congestion is a public problem in large cities.","synonyms":["social problem"]},{"groupKey":"g1","groupName":"Nhóm 1 - Nền tảng Band 3.5-5.0","topicName":"Government & Public Services","word":"basic service","meaning":"an essential service such as water, health or education","translation":"dịch vụ cơ bản","example":"Every community needs access to basic services.","synonyms":["essential service"]},{"groupKey":"g1","groupName":"Nhóm 1 - Nền tảng Band 3.5-5.0","topicName":"Travel & Tourism","word":"passport","meaning":"an official document used for international travel","translation":"hộ chiếu","example":"Travellers should check that their passport is valid.","synonyms":["travel document"]},{"groupKey":"g1","groupName":"Nhóm 1 - Nền tảng Band 3.5-5.0","topicName":"Travel & Tourism","word":"visa","meaning":"official permission to enter or stay in another country","translation":"thị thực","example":"Some visitors need a visa before travelling abroad.","synonyms":["entry permit"]},{"groupKey":"g1","groupName":"Nhóm 1 - Nền tảng Band 3.5-5.0","topicName":"Travel & Tourism","word":"luggage","meaning":"bags and cases taken on a journey","translation":"hành lý","example":"Airlines may charge extra for heavy luggage.","synonyms":["baggage"]},{"groupKey":"g1","groupName":"Nhóm 1 - Nền tảng Band 3.5-5.0","topicName":"Travel & Tourism","word":"suitcase","meaning":"a case used for carrying clothes while travelling","translation":"va li","example":"She packed a small suitcase for the weekend trip.","synonyms":["travel case"]},{"groupKey":"g1","groupName":"Nhóm 1 - Nền tảng Band 3.5-5.0","topicName":"Travel & Tourism","word":"booking","meaning":"an arrangement made in advance for travel or accommodation","translation":"đặt chỗ","example":"Online booking makes it easy to compare hotel prices.","synonyms":["reservation"]},{"groupKey":"g1","groupName":"Nhóm 1 - Nền tảng Band 3.5-5.0","topicName":"Travel & Tourism","word":"book a hotel","meaning":"to reserve accommodation in advance","translation":"đặt khách sạn","example":"Travellers can book a hotel several months before a holiday.","synonyms":["reserve a hotel"]},{"groupKey":"g1","groupName":"Nhóm 1 - Nền tảng Band 3.5-5.0","topicName":"Travel & Tourism","word":"book a flight","meaning":"to reserve a place on an aircraft","translation":"đặt vé máy bay","example":"Prices are often lower when people book a flight early.","synonyms":["reserve a flight"]},{"groupKey":"g1","groupName":"Nhóm 1 - Nền tảng Band 3.5-5.0","topicName":"Travel & Tourism","word":"travel abroad","meaning":"to visit or stay in another country","translation":"đi nước ngoài","example":"Many students hope to travel abroad after graduation.","synonyms":["go overseas"]},{"groupKey":"g1","groupName":"Nhóm 1 - Nền tảng Band 3.5-5.0","topicName":"Travel & Tourism","word":"travel alone","meaning":"to make a journey without companions","translation":"đi du lịch một mình","example":"Some young adults enjoy the freedom of travelling alone.","synonyms":["travel independently"]},{"groupKey":"g1","groupName":"Nhóm 1 - Nền tảng Band 3.5-5.0","topicName":"Travel & Tourism","word":"travel with friends","meaning":"to take a trip together with friends","translation":"du lịch cùng bạn bè","example":"Students often travel with friends during holidays.","synonyms":["take a trip with friends"]},{"groupKey":"g1","groupNa