","topicName":"Science & Innovation","word":"research question","meaning":"a specific question that a study is designed to answer","translation":"câu hỏi nghiên cứu","example":"A clear research question helps determine suitable methods.","synonyms":["study question"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Science & Innovation","word":"data collection","meaning":"the process of gathering information for research","translation":"thu thập dữ liệu","example":"Reliable data collection is essential for scientific studies.","synonyms":["gathering data"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Science & Innovation","word":"research data","meaning":"information gathered and analysed during a study","translation":"dữ liệu nghiên cứu","example":"Researchers should store research data securely.","synonyms":["study data"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Science & Innovation","word":"scientific theory","meaning":"a well-supported explanation based on evidence and testing","translation":"lý thuyết khoa học","example":"A scientific theory can change when new evidence appears.","synonyms":["scientific explanation"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Science & Innovation","word":"scientific knowledge","meaning":"understanding produced through systematic research","translation":"kiến thức khoa học","example":"Public policy often depends on scientific knowledge.","synonyms":["research knowledge"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Science & Innovation","word":"research institution","meaning":"an organisation that conducts scientific or academic research","translation":"viện nghiên cứu","example":"The research institution works with several universities.","synonyms":["research centre"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Science & Innovation","word":"research team","meaning":"a group of people working together on a study","translation":"nhóm nghiên cứu","example":"The research team published its findings in a journal.","synonyms":["study team"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Science & Innovation","word":"scientific journal","meaning":"a publication containing peer-reviewed research","translation":"tạp chí khoa học","example":"Important results are often reported in a scientific journal.","synonyms":["academic journal"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Science & Innovation","word":"research result","meaning":"an outcome produced by a study or investigation","translation":"kết quả nghiên cứu","example":"The research results suggest a link between sleep and memory.","synonyms":["study result"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Science & Innovation","word":"scientific development","meaning":"progress in scientific knowledge or technology","translation":"phát triển khoa học","example":"Scientific development has improved medical diagnosis.","synonyms":["scientific progress"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Science & Innovation","word":"new technology","meaning":"technology that has been recently developed or introduced","translation":"công nghệ mới","example":"New technology can create both opportunities and risks.","synonyms":["emerging technology"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Science & Innovation","word":"new invention","meaning":"a recently created device, process or idea","translation":"phát minh mới","example":"A new invention may take years to reach the market.","synonyms":["innovation"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Science & Innovation","word":"research process","meaning":"the sequence of activities involved in conducting a study","translation":"quy trình nghiên cứu","example":"Transparency is important throughout the research process.","synonyms":["study process"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Science & Innovation","word":"laboratory test","meaning":"a test carried out under controlled laboratory conditions","translation":"thử nghiệm trong phòng thí nghiệm","example":"The material performed well in laboratory tests.","synonyms":["lab test"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Science & Innovation","word":"research discovery","meaning":"a new finding produced through systematic scientific investigation","translation":"khám phá từ nghiên cứu","example":"A major research discovery can open new areas of scientific study.","synonyms":["new finding"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Science & Innovation","word":"research evidence","meaning":"information from studies used to support or challenge a claim","translation":"bằng chứng nghiên cứu","example":"Health advice should be based on strong research evidence.","synonyms":["scientific evidence"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Science & Innovation","word":"scientific community","meaning":"the international group of scientists and researchers","translation":"cộng đồng khoa học","example":"The findings attracted attention across the scientific community.","synonyms":["research community"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Science & Innovation","word":"research investment","meaning":"money devoted to scientific or academic research","translation":"đầu tư nghiên cứu","example":"Public research investment can support long-term innovation.","synonyms":["research funding"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Science & Innovation","word":"innovation policy","meaning":"government policy designed to encourage new technologies and ideas","translation":"chính sách đổi mới","example":"Innovation policy may include grants for small technology firms.","synonyms":["technology policy"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Science & Innovation","word":"technology transfer","meaning":"the movement of knowledge or technology from research into practical use","translation":"chuyển giao công nghệ","example":"Universities can support technology transfer to local industry.","synonyms":["knowledge transfer"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Science & Innovation","word":"practical application","meaning":"a real-world use of an idea, discovery or technology","translation":"ứng dụng thực tế","example":"The discovery has several practical applications in medicine.","synonyms":["real-world use"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Science & Innovation","word":"research collaboration","meaning":"cooperation between researchers, institutions or countries","translation":"hợp tác nghiên cứu","example":"International research collaboration can combine specialist expertise.","synonyms":["scientific cooperation"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Science & Innovation","word":"innovation process","meaning":"the stages through which a new idea becomes a useful product or method","translation":"quá trình đổi mới","example":"Funding is only one part of the innovation process.","synonyms":["development process"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Science & Innovation","word":"technological innovation","meaning":"the creation or adoption of new technology","translation":"đổi mới công nghệ","example":"Technological innovation can raise productivity.","synonyms":["technical innovation"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Family & Demographics","word":"household size","meaning":"the number of people living in one household","translation":"quy mô hộ gia đình","example":"Average household size has fallen in many countries.","synonyms":["family size"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Family & Demographics","word":"marriage rate","meaning":"the number or proportion of marriages in a population","translation":"tỷ lệ kết hôn","example":"The marriage rate has declined among younger adults.","synonyms":["rate of marriage"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Family & Demographics","word":"divorce rate","meaning":"the number or proportion of divorces in a population","translation":"tỷ lệ ly hôn","example":"Economic stress can affect the divorce rate.","synonyms":["rate of divorce"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Family & Demographics","word":"average age","meaning":"the mean age of people in a population or group","translation":"độ tuổi trung bình","example":"The average age of first-time parents has increased.","synonyms":["mean age"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Family & Demographics","word":"population structure","meaning":"the composition of a population by age, sex or other characteristics","translation":"cơ cấu dân số","example":"Migration can change a country's population structure.","synonyms":["demographic structure"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Family & Demographics","word":"demographic change","meaning":"a change in the size or composition of a population","translation":"thay đổi nhân khẩu học","example":"Demographic change creates new demands for public services.","synonyms":["population change"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Family & Demographics","word":"young population","meaning":"a population with a relatively high proportion of young people","translation":"dân số trẻ","example":"A young population can expand the future labour force.","synonyms":["youthful population"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Family & Demographics","word":"working-age population","meaning":"people within the ages commonly associated with employment","translation":"dân số trong độ tuổi lao động","example":"A shrinking working-age population can affect tax revenue.","synonyms":["labour-age population"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Family & Demographics","word":"older generation","meaning":"people belonging to an older age group","translation":"thế hệ lớn tuổi","example":"The older generation may have different attitudes towards technology.","synonyms":["senior generation"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Family & Demographics","word":"younger generation","meaning":"people belonging to a younger age group","translation":"thế hệ trẻ","example":"The younger generation tends to use digital services more frequently.","synonyms":["young people"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Family & Demographics","word":"child-rearing","meaning":"the activity of caring for and raising children","translation":"nuôi dạy con","example":"The cost of child-rearing can influence family size.","synonyms":["raising children"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Family & Demographics","word":"childcare cost","meaning":"the money families pay for care of young children","translation":"chi phí chăm sóc trẻ","example":"High childcare costs may discourage parents from working full-time.","synonyms":["cost of childcare"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Family & Demographics","word":"family responsibility","meaning":"a duty connected with caring for relatives or managing family life","translation":"trách nhiệm gia đình","example":"Family responsibilities can affect career choices.","synonyms":["domestic responsibility"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Family & Demographics","word":"household responsibility","meaning":"a duty such as cleaning, cooking or caring within a home","translation":"trách nhiệm trong gia đình","example":"Couples increasingly share household responsibilities.","synonyms":["domestic duty"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Family & Demographics","word":"care responsibility","meaning":"a duty to provide care for a child, elderly relative or dependent person","translation":"trách nhiệm chăm sóc","example":"Care responsibilities often fall unevenly between family members.","synonyms":["caregiving duty"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Family & Demographics","word":"family relationship","meaning":"the social and emotional connection between relatives","translation":"mối quan hệ gia đình","example":"Regular communication can strengthen family relationships.","synonyms":["family bond"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Family & Demographics","word":"family structure","meaning":"the way a household or family is organised","translation":"cấu trúc gia đình","example":"Family structures have become more diverse.","synonyms":["household structure"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Family & Demographics","word":"single household","meaning":"a home occupied by one person","translation":"hộ gia đình một người","example":"Single households are becoming more common in large cities.","synonyms":["one-person household"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Family & Demographics","word":"multi-generational household","meaning":"a home where several generations live together","translation":"hộ gia đình đa thế hệ","example":"Housing costs may encourage multi-generational households.","synonyms":["extended household"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Family & Demographics","word":"population trend","meaning":"a long-term pattern of population change","translation":"xu hướng dân số","example":"Falling fertility is an important population trend.","synonyms":["demographic trend"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Family & Demographics","word":"fertility rate","meaning":"the average number of children born to women in a population","translation":"tỷ suất sinh","example":"The fertility rate has fallen below replacement level in some countries.","synonyms":["birth rate measure"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Family & Demographics","word":"population decline","meaning":"a decrease in the number of people living in a place","translation":"suy giảm dân số","example":"Rural areas may experience population decline as young adults leave.","synonyms":["demographic decline"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Family & Demographics","word":"generation difference","meaning":"a difference in attitudes or behaviour between age groups","translation":"khác biệt thế hệ","example":"Technology use is a common generation difference.","synonyms":["generational difference"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Family & Demographics","word":"family policy","meaning":"government measures affecting families, childcare or parental support","translation":"chính sách gia đình","example":"Affordable childcare is an important part of family policy.","synonyms":["social family policy"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Family & Demographics","word":"population-related pressure","meaning":"strain on services or resources caused by population size or composition","translation":"áp lực liên quan đến dân số","example":"Population-related pressure can increase demand for schools and healthcare.","synonyms":["population pressure"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Tourism Management","word":"tourism development","meaning":"the growth and planning of tourism activities and facilities","translation":"phát triển du lịch","example":"Tourism development should protect local communities and ecosystems.","synonyms":["development of tourism"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Tourism Management","word":"tourism impact","meaning":"an effect of tourism on a place, economy or community","translation":"tác động du lịch","example":"Authorities should monitor the environmental impact of tourism.","synonyms":["effect of tourism"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Tourism Management","word":"visitor management","meaning":"the planning and control of visitors at a destination","translation":"quản lý du khách","example":"Visitor management can reduce overcrowding at historic sites.","synonyms":["tourist management"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Tourism Management","word":"tourism planning","meaning":"the process of designing tourism growth and services","translation":"quy hoạch du lịch","example":"Good tourism planning balances revenue with conservation.","synonyms":["destination planning"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Tourism Management","word":"local employment","meaning":"jobs available to people living in a particular area","translation":"việc làm địa phương","example":"Tourism can create local employment in hotels and restaurants.","synonyms":["community jobs"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Tourism Management","word":"visitor spending","meaning":"money spent by tourists during a trip","translation":"chi tiêu của du khách","example":"Visitor spending supports many small businesses.","synonyms":["tourist expenditure"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Tourism Management","word":"tourism infrastructure","meaning":"facilities and systems that support visitors","translation":"hạ tầng du lịch","example":"Remote regions may need better tourism infrastructure.","synonyms":["visitor infrastructure"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Tourism Management","word":"destination marketing","meaning":"promotion used to attract visitors to a place","translation":"tiếp thị điểm đến","example":"Social media is increasingly important in destination marketing.","synonyms":["tourism marketing"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Tourism Management","word":"tourist season","meaning":"the period when a destination receives many visitors","translation":"mùa du lịch","example":"Accommodation prices rise during the main tourist season.","synonyms":["peak season"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Tourism Management","word":"low season","meaning":"the period when a destination has relatively few visitors","translation":"mùa thấp điểm","example":"Some hotels close during the low season.","synonyms":["off-season"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Tourism Management","word":"visitor experience","meaning":"the overall experience a tourist has at a destination","translation":"trải nghiệm du khách","example":"Clean public spaces improve the visitor experience.","synonyms":["tourist experience"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Tourism Management","word":"local community benefit","meaning":"a positive outcome of tourism for local residents","translation":"lợi ích cho cộng đồng địa phương","example":"Policies should ensure local community benefits from tourism.","synonyms":["community gain"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Tourism Management","word":"cultural tourism product","meaning":"a tourism service or attraction based on culture or heritage","translation":"sản phẩm du lịch văn hóa","example":"Traditional craft workshops can become cultural tourism products.","synonyms":["heritage tourism offer"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Tourism Management","word":"ecotourism","meaning":"responsible travel focused on natural areas and conservation","translation":"du lịch sinh thái","example":"Ecotourism can fund conservation when visitor numbers are controlled.","synonyms":["nature tourism"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Tourism Management","word":"tourism pressure","meaning":"strain on local resources and services caused by visitors","translation":"áp lực du lịch","example":"Popular islands face tourism pressure on water supplies.","synonyms":["visitor pressure"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Tourism Management","word":"over-tourism","meaning":"excessive visitor numbers that harm local life or environments","translation":"du lịch quá tải","example":"Over-tourism has led some cities to limit short-term rentals.","synonyms":["excessive tourism"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Tourism Management","word":"tourist tax","meaning":"a tax or fee charged to visitors","translation":"thuế du lịch","example":"A tourist tax can help fund local infrastructure.","synonyms":["visitor levy"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Tourism Management","word":"visitor capacity","meaning":"the number of visitors a place can handle sustainably","translation":"sức chứa du khách","example":"Parks may set visitor capacity during sensitive seasons.","synonyms":["tourism capacity"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Tourism Management","word":"responsible tourism","meaning":"travel that minimises harm and benefits local communities","translation":"du lịch có trách nhiệm","example":"Responsible tourism encourages visitors to respect local customs.","synonyms":["ethical tourism"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Tourism Management","word":"community-based tourism","meaning":"tourism owned or managed with strong local community involvement","translation":"du lịch cộng đồng","example":"Community-based tourism can keep more income in rural areas.","synonyms":["local tourism"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Tourism Management","word":"seasonal demand","meaning":"demand that rises or falls at particular times of year","translation":"nhu cầu theo mùa","example":"Seasonal demand makes employment less stable in resort towns.","synonyms":["seasonal tourism demand"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Tourism Management","word":"visitor behaviour","meaning":"the actions and choices of tourists at destinations","translation":"hành vi du khách","example":"Clear rules can improve visitor behaviour in protected areas.","synonyms":["tourist behaviour"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Tourism Management","word":"tourism carrying capacity","meaning":"the level of tourism a destination can support without unacceptable harm","translation":"sức tải du lịch","example":"Managers should consider tourism carrying capacity before expanding facilities.","synonyms":["visitor limit"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Tourism Management","word":"tourism workforce","meaning":"people employed in tourism-related industries","translation":"lực lượng lao động du lịch","example":"The tourism workforce needs strong language and service skills.","synonyms":["tourism staff"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Tourism Management","word":"destination management","meaning":"coordinated planning and operation of a tourism destination","translation":"quản lý điểm đến","example":"Destination management involves transport, marketing and conservation.","synonyms":["tourism management"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Agriculture & Food Systems","word":"food chain","meaning":"the sequence through which food moves from production to consumers","translation":"chuỗi thực phẩm","example":"Disruption in the food chain can raise prices.","synonyms":["food supply chain"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Agriculture & Food Systems","word":"food system","meaning":"the network of activities involved in producing, processing and consuming food","translation":"hệ thống thực phẩm","example":"Climate change affects the entire food system.","synonyms":["agri-food system"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Agriculture & Food Systems","word":"crop production","meaning":"the cultivation and harvesting of plants for food or other uses","translation":"sản xuất cây trồng","example":"Water shortages can reduce crop production.","synonyms":["crop farming"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Agriculture & Food Systems","word":"livestock farming","meaning":"the raising of animals for food or agricultural products","translation":"chăn nuôi gia súc","example":"Livestock farming uses significant land and water.","synonyms":["animal farming"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Agriculture & Food Systems","word":"farm productivity","meaning":"the amount of agricultural output produced from resources","translation":"năng suất nông nghiệp","example":"Better irrigation can improve farm productivity.","synonyms":["agricultural productivity"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Agriculture & Food Systems","word":"agricultural land","meaning":"land used for crops or livestock","translation":"đất nông nghiệp","example":"Urban expansion can reduce available agricultural land.","synonyms":["farmland"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Agriculture & Food Systems","word":"irrigation","meaning":"the artificial supply of water to crops","translation":"tưới tiêu","example":"Efficient irrigation is essential in dry regions.","synonyms":["watering system"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Agriculture & Food Systems","word":"soil quality","meaning":"the condition of soil and its ability to support plant growth","translation":"chất lượng đất","example":"Overuse of chemicals can damage soil quality.","synonyms":["soil health"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Agriculture & Food Systems","word":"crop yield","meaning":"the amount of crop produced from a given area","translation":"năng suất cây trồng","example":"New seed varieties can increase crop yield.","synonyms":["agricultural yield"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Agriculture & Food Systems","word":"food processing","meaning":"the transformation of raw agricultural products into food products","translation":"chế biến thực phẩm","example":"Food processing can extend shelf life but may add salt or sugar.","synonyms":["food manufacture"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Agriculture & Food Systems","word":"food packaging","meaning":"materials used to contain and protect food","translation":"bao bì thực phẩm","example":"Reducing food packaging can lower plastic waste.","synonyms":["product packaging"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Agriculture & Food Systems","word":"food distribution","meaning":"the transport and delivery of food from producers to consumers","translation":"phân phối thực phẩm","example":"Efficient food distribution reduces shortages.","synonyms":["food delivery network"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Agriculture & Food Systems","word":"local produce","meaning":"food grown or made in a nearby region","translation":"nông sản địa phương","example":"Buying local produce can support farmers.","synonyms":["regional food"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Agriculture & Food Systems","word":"seasonal food","meaning":"food naturally available during particular times of year","translation":"thực phẩm theo mùa","example":"Seasonal food often requires less long-distance transport.","synonyms":["seasonal produce"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Agriculture & Food Systems","word":"food shortage","meaning":"a situation in which insufficient food is available","translation":"thiếu lương thực","example":"Drought can cause a serious food shortage.","synonyms":["food scarcity"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Agriculture & Food Systems","word":"food demand","meaning":"the amount and type of food consumers want","translation":"nhu cầu thực phẩm","example":"Rising incomes can change food demand.","synonyms":["demand for food"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Agriculture & Food Systems","word":"food price","meaning":"the cost paid for food products","translation":"giá thực phẩm","example":"Higher fuel costs can increase food prices.","synonyms":["cost of food"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Agriculture & Food Systems","word":"farming practice","meaning":"a method used to grow crops or raise animals","translation":"phương pháp canh tác","example":"Sustainable farming practices can protect soil.","synonyms":["agricultural practice"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Agriculture & Food Systems","word":"chemical fertiliser","meaning":"a manufactured substance added to soil to improve plant growth","translation":"phân bón hóa học","example":"Excessive chemical fertiliser can pollute waterways.","synonyms":["synthetic fertiliser"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Agriculture & Food Systems","word":"pesticide use","meaning":"the application of chemicals to control pests","translation":"việc sử dụng thuốc trừ sâu","example":"Pesticide use must be managed carefully.","synonyms":["use of pesticides"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Agriculture & Food Systems","word":"organic farming","meaning":"agriculture that avoids many synthetic chemicals","translation":"nông nghiệp hữu cơ","example":"Organic farming can reduce some forms of pollution.","synonyms":["organic agriculture"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Agriculture & Food Systems","word":"farm income","meaning":"money earned by agricultural households or businesses","translation":"thu nhập nông nghiệp","example":"Unstable prices make farm income unpredictable.","synonyms":["agricultural earnings"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Agriculture & Food Systems","word":"rural livelihood","meaning":"the way people in rural areas earn a living","translation":"sinh kế nông thôn","example":"Agriculture remains central to many rural livelihoods.","synonyms":["countryside livelihood"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Agriculture & Food Systems","word":"food standard","meaning":"a rule defining acceptable food safety or quality","translation":"tiêu chuẩn thực phẩm","example":"Strong food standards protect consumers.","synonyms":["food regulation"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Agriculture & Food Systems","word":"agricultural policy","meaning":"government policy affecting farming and food production","translation":"chính sách nông nghiệp","example":"Agricultural policy can influence prices and land use.","synonyms":["farm policy"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Gender Equality","word":"gender gap","meaning":"a measurable difference between men and women in outcomes or opportunities","translation":"khoảng cách giới","example":"The gender gap in senior management remains significant.","synonyms":["gender disparity"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Gender Equality","word":"pay gap","meaning":"the difference in average earnings between groups","translation":"chênh lệch lương","example":"Transparent salary systems may help reduce the pay gap.","synonyms":["wage gap"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Gender Equality","word":"equal access","meaning":"the condition of having the same opportunity to use services or resources","translation":"tiếp cận bình đẳng","example":"All children should have equal access to quality education.","synonyms":["equal opportunity"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Gender Equality","word":"workplace discrimination","meaning":"unfair treatment at work based on personal characteristics","translation":"phân biệt đối xử nơi làm việc","example":"Clear procedures are needed to address workplace discrimination.","synonyms":["employment discrimination"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Gender Equality","word":"gender stereotype","meaning":"a fixed and oversimplified belief about men or women","translation":"định kiến giới","example":"Gender stereotypes can influence children's career choices.","synonyms":["sex stereotype"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Gender Equality","word":"gender bias","meaning":"unfair preference or prejudice based on gender","translation":"thiên kiến giới","example":"Recruitment training can reduce unconscious gender bias.","synonyms":["gender prejudice"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Gender Equality","word":"leadership role","meaning":"a position involving responsibility for guiding others","translation":"vai trò lãnh đạo","example":"More women are entering leadership roles in public institutions.","synonyms":["management role"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Gender Equality","word":"women's participation","meaning":"the involvement of women in work, politics or other activities","translation":"sự tham gia của phụ nữ","example":"Affordable childcare can increase women's participation in employment.","synonyms":["female participation"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Gender Equality","word":"female employment","meaning":"paid work carried out by women as a share of the workforce","translation":"việc làm của phụ nữ","example":"Female employment has risen as educational access has expanded.","synonyms":["women's employment"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Gender Equality","word":"career opportunity","meaning":"a chance to enter or advance in a profession","translation":"cơ hội nghề nghiệp","example":"Equal career opportunities should depend on skill rather than gender.","synonyms":["professional opportunity"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Gender Equality","word":"shared childcare","meaning":"childcare responsibilities divided between caregivers","translation":"chia sẻ việc chăm con","example":"Shared childcare can support both parents' careers.","synonyms":["equal childcare"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Gender Equality","word":"shared housework","meaning":"household tasks divided between members of a family","translation":"chia sẻ việc nhà","example":"Shared housework can reduce time pressure on working parents.","synonyms":["equal domestic work"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Gender Equality","word":"work-family balance","meaning":"the ability to manage employment and family responsibilities","translation":"cân bằng công việc và gia đình","example":"Flexible schedules can improve work-family balance.","synonyms":["work-life balance for families"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Gender Equality","word":"parental responsibility","meaning":"a parent's duty to care for and support a child","translation":"trách nhiệm làm cha mẹ","example":"Parental responsibility should not fall on one parent alone.","synonyms":["parenting duty"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Gender Equality","word":"male participation","meaning":"the involvement of men in a particular activity or responsibility","translation":"sự tham gia của nam giới","example":"Greater male participation in childcare can challenge traditional roles.","synonyms":["men's participation"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Gender Equality","word":"social norm","meaning":"an informal rule or expectation about acceptable behaviour","translation":"chuẩn mực xã hội","example":"Social norms influence attitudes towards gender and work.","synonyms":["social expectation"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Gender Equality","word":"equal treatment","meaning":"the practice of treating people by the same fair standards","translation":"đối xử bình đẳng","example":"Employment law should guarantee equal treatment.","synonyms":["fair treatment"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Gender Equality","word":"women in leadership","meaning":"women holding senior decision-making positions","translation":"phụ nữ trong vai trò lãnh đạo","example":"Visible women in leadership can provide role models.","synonyms":["female leaders"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Gender Equality","word":"gender representation","meaning":"the presence of different genders in institutions or roles","translation":"đại diện giới","example":"Boards are under pressure to improve gender representation.","synonyms":["gender balance"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Gender Equality","word":"education for girls","meaning":"access to schooling and learning opportunities for female children","translation":"giáo dục cho trẻ em gái","example":"Education for girls is associated with many social benefits.","synonyms":["girls' education"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Gender Equality","word":"gender-based barrier","meaning":"an obstacle that affects people because of gender","translation":"rào cản dựa trên giới","example":"Lack of childcare can become a gender-based barrier to promotion.","synonyms":["gender obstacle"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Gender Equality","word":"equality policy","meaning":"a formal policy designed to promote fair treatment and opportunity","translation":"chính sách bình đẳng","example":"The company introduced an equality policy for recruitment.","synonyms":["equal-opportunity policy"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Gender Equality","word":"inclusive workplace","meaning":"a workplace where people from different backgrounds can participate fully","translation":"nơi làm việc hòa nhập","example":"An inclusive workplace values different experiences.","synonyms":["equitable workplace"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Gender Equality","word":"social equality","meaning":"a condition in which groups have comparable rights and opportunities","translation":"bình đẳng xã hội","example":"Education can contribute to wider social equality.","synonyms":["equal society"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Gender Equality","word":"family-friendly policy","meaning":"a workplace or government measure supporting people with family duties","translation":"chính sách thân thiện với gia đình","example":"Family-friendly policies can reduce career penalties for parents.","synonyms":["parent-support policy"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Sport & Society","word":"community sport","meaning":"organised sport played within a local community","translation":"thể thao cộng đồng","example":"Community sport can improve health and social connections.","synonyms":["local sport"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Sport & Society","word":"sports participation","meaning":"the involvement of people in organised or informal sport","translation":"sự tham gia thể thao","example":"Lower fees may increase sports participation among children.","synonyms":["participation in sport"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Sport & Society","word":"sporting participation rate","meaning":"the proportion of people who regularly take part in sport","translation":"tỷ lệ tham gia thể thao","example":"The sporting participation rate is lower among older adults.","synonyms":["sport participation rate"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Sport & Society","word":"public sports facility","meaning":"a sports venue funded or provided for general community use","translation":"cơ sở thể thao công cộng","example":"Public sports facilities can make exercise more accessible.","synonyms":["community sports facility"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Sport & Society","word":"youth sport","meaning":"organised physical activity for children and teenagers","translation":"thể thao thanh thiếu niên","example":"Youth sport can teach discipline and cooperation.","synonyms":["children's sport"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Sport & Society","word":"school sport","meaning":"physical and competitive activities organised through schools","translation":"thể thao học đường","example":"School sport gives students a chance to be active.","synonyms":["school athletics"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Sport & Society","word":"sports coach","meaning":"a person who trains athletes or teams","translation":"huấn luyện viên thể thao","example":"A qualified sports coach can reduce injury risk.","synonyms":["coach"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Sport & Society","word":"sports injury","meaning":"physical harm caused during sport or exercise","translation":"chấn thương thể thao","example":"Proper warm-ups can reduce some sports injuries.","synonyms":["athletic injury"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Sport & Society","word":"exercise participation","meaning":"the regular involvement of people in physical exercise","translation":"sự tham gia tập luyện","example":"Public campaigns may increase exercise participation.","synonyms":["physical-activity participation"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Sport & Society","word":"competitive pressure","meaning":"stress caused by the need to perform well in competition","translation":"áp lực cạnh tranh","example":"Young athletes can experience intense competitive pressure.","synonyms":["performance pressure"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Sport & Society","word":"sporting success","meaning":"achievement in sport, especially at a high level","translation":"thành công thể thao","example":"Governments sometimes invest heavily in elite sporting success.","synonyms":["athletic success"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Sport & Society","word":"national team","meaning":"a team representing a country in sport","translation":"đội tuyển quốc gia","example":"Success by the national team can increase interest in sport.","synonyms":["country team"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Sport & Society","word":"sports event hosting","meaning":"the organisation of a major sporting event in a location","translation":"đăng cai sự kiện thể thao","example":"Sports-event hosting can require large public investment.","synonyms":["hosting a tournament"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Sport & Society","word":"sports venue","meaning":"a place designed for sporting activities or competitions","translation":"địa điểm thể thao","example":"The city built a new sports venue for international competitions.","synonyms":["stadium facility"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Sport & Society","word":"sports industry","meaning":"businesses and organisations connected with sport","translation":"ngành thể thao","example":"The sports industry includes media, equipment and tourism.","synonyms":["sport sector"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Sport & Society","word":"physical activity level","meaning":"the amount of movement or exercise a person regularly does","translation":"mức độ hoạt động thể chất","example":"Children's physical activity levels often fall during adolescence.","synonyms":["activity level"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Sport & Society","word":"inactive population","meaning":"people who do little regular physical activity","translation":"dân số ít vận động","example":"Health services are concerned about the growing inactive population.","synonyms":["sedentary population"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Sport & Society","word":"sporting opportunity","meaning":"a chance to participate in sport or develop athletic ability","translation":"cơ hội thể thao","example":"Schools should provide equal sporting opportunities.","synonyms":["sports access"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Sport & Society","word":"sports sponsorship","meaning":"financial support for sport provided by companies or organisations","translation":"tài trợ thể thao","example":"Sports sponsorship provides revenue but can influence branding.","synonyms":["commercial sponsorship"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Sport & Society","word":"commercial sport","meaning":"sport strongly connected with business, media and profit","translation":"thể thao thương mại","example":"Commercial sport attracts large broadcasting deals.","synonyms":["professional sport business"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Sport & Society","word":"sporting role model","meaning":"an athlete admired and copied by others","translation":"hình mẫu thể thao","example":"A sporting role model can influence children's behaviour.","synonyms":["athlete role model"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Sport & Society","word":"fair play","meaning":"respect for rules, opponents and honest competition","translation":"tinh thần fair play","example":"Coaches should teach fair play from an early age.","synonyms":["sportsmanship"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Sport & Society","word":"mass participation event","meaning":"a sporting event open to large numbers of ordinary people","translation":"sự kiện thể thao đại chúng","example":"City marathons are popular mass-participation events.","synonyms":["community sports event"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Sport & Society","word":"sport accessibility","meaning":"the ease with which people can participate in sporting activities","translation":"khả năng tiếp cận thể thao","example":"Affordable facilities improve sport accessibility.","synonyms":["access to sport"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Sport & Society","word":"sport policy","meaning":"government or organisational policy relating to physical activity and sport","translation":"chính sách thể thao","example":"Sport policy should balance elite success with public health.","synonyms":["sports strategy"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Arts & Public Funding","word":"art gallery","meaning":"a place where works of visual art are displayed","translation":"phòng trưng bày nghệ thuật","example":"Free entry can increase attendance at an art gallery.","synonyms":["gallery"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Arts & Public Funding","word":"public art","meaning":"art placed in spaces accessible to the general public","translation":"nghệ thuật công cộng","example":"Public art can make urban spaces more distinctive.","synonyms":["community art"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Arts & Public Funding","word":"arts organisation","meaning":"a group that produces, supports or presents artistic activity","translation":"tổ chức nghệ thuật","example":"Small arts organisations often depend on grants.","synonyms":["cultural organisation"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Arts & Public Funding","word":"arts education","meaning":"teaching in subjects such as music, drama and visual art","translation":"giáo dục nghệ thuật","example":"Arts education can support creativity and confidence.","synonyms":["creative education"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Arts & Public Funding","word":"music education","meaning":"formal or informal teaching of music","translation":"giáo dục âm nhạc","example":"Music education can improve children's listening skills.","synonyms":["musical training"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Arts & Public Funding","word":"theatre production","meaning":"a play or performance prepared for an audience","translation":"sản phẩm sân khấu","example":"The theatre production employed local actors and technicians.","synonyms":["stage production"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Arts & Public Funding","word":"cultural venue","meaning":"a place used for arts, heritage or cultural events","translation":"địa điểm văn hóa","example":"The new cultural venue hosts concerts and exhibitions.","synonyms":["arts venue"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Arts & Public Funding","word":"creative career","meaning":"a profession involving artistic or imaginative work","translation":"nghề sáng tạo","example":"Creative careers can be rewarding but financially uncertain.","synonyms":["arts career"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Arts & Public Funding","word":"creative skill","meaning":"an ability involving imagination, design or artistic expression","translation":"kỹ năng sáng tạo","example":"Schools can develop creative skills through music and art.","synonyms":["artistic skill"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Arts & Public Funding","word":"artistic work","meaning":"a product created through artistic activity","translation":"tác phẩm nghệ thuật","example":"Digital tools have changed how artistic work is produced.","synonyms":["creative work"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Arts & Public Funding","word":"cultural funding","meaning":"money provided to support arts and heritage activities","translation":"tài trợ văn hóa","example":"Cultural funding is often debated during periods of budget pressure.","synonyms":["arts funding"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Arts & Public Funding","word":"government grant","meaning":"money given by government for a specific project or purpose","translation":"trợ cấp chính phủ","example":"The theatre received a government grant for youth programmes.","synonyms":["public grant"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Arts & Public Funding","word":"arts subsidy","meaning":"public money used to support artistic production or access","translation":"trợ cấp nghệ thuật","example":"An arts subsidy can make performances more affordable.","synonyms":["cultural subsidy"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Arts & Public Funding","word":"public access to art","meaning":"the ability of ordinary people to experience artistic works","translation":"tiếp cận nghệ thuật công cộng","example":"Museums improve public access to art through free exhibitions.","synonyms":["art access"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Arts & Public Funding","word":"cultural participation rate","meaning":"the proportion of people taking part in arts or cultural activities","translation":"tỷ lệ tham gia văn hóa","example":"Lower ticket prices may raise the cultural participation rate.","synonyms":["arts participation rate"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Arts & Public Funding","word":"local artist","meaning":"an artist living or working in a particular area","translation":"nghệ sĩ địa phương","example":"Festivals can provide opportunities for local artists.","synonyms":["regional artist"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Arts & Public Funding","word":"creative economy","meaning":"economic activity based on culture, design and creative industries","translation":"kinh tế sáng tạo","example":"The creative economy contributes to tourism and employment.","synonyms":["creative sector"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Arts & Public Funding","word":"cultural employment","meaning":"jobs in arts, heritage and creative industries","translation":"việc làm văn hóa","example":"Public festivals generate temporary cultural employment.","synonyms":["arts jobs"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Arts & Public Funding","word":"museum admission","meaning":"the price or process of entering a museum","translation":"phí vào bảo tàng","example":"Free museum admission can attract a broader audience.","synonyms":["museum entry"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Arts & Public Funding","word":"arts audience","meaning":"people who attend or consume artistic performances and works","translation":"khán giả nghệ thuật","example":"Online streaming has expanded the arts audience.","synonyms":["cultural audience"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Arts & Public Funding","word":"artistic freedom","meaning":"the ability of artists to create without inappropriate restriction","translation":"tự do nghệ thuật","example":"Public funding should not unnecessarily limit artistic freedom.","synonyms":["creative freedom"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Arts & Public Funding","word":"cultural investment","meaning":"spending intended to develop arts, heritage or cultural institutions","translation":"đầu tư văn hóa","example":"Cultural investment can contribute to urban regeneration.","synonyms":["arts investment"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Arts & Public Funding","word":"creative programme","meaning":"an organised series of artistic or cultural activities","translation":"chương trình sáng tạo","example":"The library runs a creative programme for teenagers.","synonyms":["arts programme"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Arts & Public Funding","word":"artistic value","meaning":"the creative or aesthetic importance of a work","translation":"giá trị nghệ thuật","example":"Artistic value is difficult to measure in financial terms.","synonyms":["aesthetic value"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Arts & Public Funding","word":"public benefit of art","meaning":"the social or cultural advantages created by artistic activity","translation":"lợi ích công cộng của nghệ thuật","example":"Supporters argue that the public benefit of art justifies some state funding.","synonyms":["social value of art"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Ageing Population","word":"older adult","meaning":"an adult in a later stage of life","translation":"người lớn tuổi","example":"Older adults benefit from accessible public transport.","synonyms":["senior adult"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Ageing Population","word":"retired person","meaning":"someone who has stopped regular employment because of age","translation":"người đã nghỉ hưu","example":"Many retired people remain active in their communities.","synonyms":["retiree"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Ageing Population","word":"retirement income","meaning":"money received after a person stops working","translation":"thu nhập hưu trí","example":"Rising living costs can reduce the value of retirement income.","synonyms":["pension income"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Ageing Population","word":"pension system","meaning":"a system providing income to people after retirement","translation":"hệ thống lương hưu","example":"An ageing society places pressure on the pension system.","synonyms":["retirement system"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Ageing Population","word":"state pension","meaning":"regular government payments to eligible retired people","translation":"lương hưu nhà nước","example":"The state pension is the main income source for some older people.","synonyms":["public pension"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Ageing Population","word":"retirement planning","meaning":"financial and practical preparation for life after work","translation":"kế hoạch nghỉ hưu","example":"Retirement planning should begin well before old age.","synonyms":["pension planning"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Ageing Population","word":"long-term care","meaning":"ongoing assistance for people who cannot fully care for themselves","translation":"chăm sóc dài hạn","example":"Demand for long-term care rises as populations age.","synonyms":["continuing care"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Ageing Population","word":"home care","meaning":"support provided to people in their own homes","translation":"chăm sóc tại nhà","example":"Home care can allow older adults to remain independent.","synonyms":["domiciliary care"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Ageing Population","word":"elderly support","meaning":"practical, financial or medical help for older people","translation":"hỗ trợ người cao tuổi","example":"Community groups can provide elderly support for isolated residents.","synonyms":["senior support"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Ageing Population","word":"age-related illness","meaning":"a disease or condition more common among older people","translation":"bệnh liên quan đến tuổi tác","example":"Health systems must prepare for more age-related illnesses.","synonyms":["age-associated disease"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Ageing Population","word":"ageing workforce","meaning":"a workforce with a rising proportion of older employees","translation":"lực lượng lao động già hóa","example":"An ageing workforce may increase demand for retraining.","synonyms":["older workforce"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Ageing Population","word":"later retirement","meaning":"the practice of retiring at an older age","translation":"nghỉ hưu muộn","example":"Later retirement can reduce pressure on pension funds.","synonyms":["delayed retirement"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Ageing Population","word":"retirement decision","meaning":"a choice about when and how to stop paid work","translation":"quyết định nghỉ hưu","example":"Health strongly influences the retirement decision.","synonyms":["decision to retire"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Ageing Population","word":"healthy retirement","meaning":"a period after work in which a person maintains good health and activity","translation":"nghỉ hưu khỏe mạnh","example":"Exercise and social contact support healthy retirement.","synonyms":["active retirement"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Ageing Population","word":"social care","meaning":"support services helping people with daily living and independence","translation":"chăm sóc xã hội","example":"Local governments often fund social care for vulnerable adults.","synonyms":["care services"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Ageing Population","word":"care worker","meaning":"a person paid to provide practical personal support","translation":"nhân viên chăm sóc","example":"The shortage of care workers is a growing concern.","synonyms":["support worker"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Ageing Population","word":"age-friendly city","meaning":"a city designed to meet the needs of older residents","translation":"thành phố thân thiện với người cao tuổi","example":"Safe pavements are part of an age-friendly city.","synonyms":["senior-friendly city"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Ageing Population","word":"older consumer","meaning":"an older person considered as a customer or market group","translation":"người tiêu dùng lớn tuổi","example":"Businesses increasingly design services for older consumers.","synonyms":["senior consumer"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Ageing Population","word":"intergenerational support","meaning":"help exchanged between younger and older generations","translation":"hỗ trợ liên thế hệ","example":"Intergenerational support can reduce social isolation.","synonyms":["support across generations"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Ageing Population","word":"retirement community","meaning":"a residential community designed mainly for older adults","translation":"cộng đồng hưu trí","example":"Some retirees prefer a retirement community with shared services.","synonyms":["senior community"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Ageing Population","word":"elderly independence","meaning":"the ability of older people to manage daily life themselves","translation":"tính độc lập của người cao tuổi","example":"Accessible housing can protect elderly independence.","synonyms":["senior independence"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Ageing Population","word":"ageing-related cost","meaning":"public or private expense associated with an older population","translation":"chi phí liên quan đến già hóa","example":"Healthcare is a major ageing-related cost.","synonyms":["cost of population ageing"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Ageing Population","word":"older people's needs","meaning":"the health, social and practical requirements of older adults","translation":"nhu cầu của người cao tuổi","example":"Transport policy should consider older people's needs.","synonyms":["senior needs"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Ageing Population","word":"age-inclusive workplace","meaning":"a workplace that supports employees of different ages","translation":"nơi làm việc bao trùm độ tuổi","example":"An age-inclusive workplace can retain experienced staff.","synonyms":["age-friendly workplace"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Ageing Population","word":"ageing challenge","meaning":"a social or economic difficulty associated with population ageing","translation":"thách thức già hóa","example":"Pension sustainability is a major ageing challenge.","synonyms":["demographic ageing challenge"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Language Learning","word":"language learner","meaning":"a person studying a language","translation":"người học ngôn ngữ","example":"A successful language learner needs regular exposure and practice.","synonyms":["learner"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Language Learning","word":"language practice","meaning":"activity done to improve language ability","translation":"luyện tập ngôn ngữ","example":"Daily language practice is more effective than occasional long sessions.","synonyms":["language training"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Language Learning","word":"speaking practice","meaning":"activity focused on improving spoken communication","translation":"luyện nói","example":"Conversation clubs provide useful speaking practice.","synonyms":["oral practice"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Language Learning","word":"listening practice","meaning":"activity focused on understanding spoken language","translation":"luyện nghe","example":"Podcasts can provide flexible listening practice.","synonyms":["aural practice"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Language Learning","word":"reading practice","meaning":"activity focused on understanding written texts","translation":"luyện đọc","example":"News articles are useful for intermediate reading practice.","synonyms":["reading training"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Language Learning","word":"writing practice","meaning":"activity focused on producing accurate and effective written language","translation":"luyện viết","example":"Regular writing practice helps learners notice grammar weaknesses.","synonyms":["written practice"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Language Learning","word":"language exposure","meaning":"contact with a language through listening, reading or interaction","translation":"tiếp xúc ngôn ngữ","example":"Frequent language exposure improves familiarity with natural patterns.","synonyms":["exposure to English"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Language Learning","word":"language input","meaning":"spoken or written language that a learner receives","translation":"đầu vào ngôn ngữ","example":"Comprehensible language input helps learners acquire new expressions.","synonyms":["linguistic input"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Language Learning","word":"language output","meaning":"spoken or written language produced by a learner","translation":"đầu ra ngôn ngữ","example":"Learners need language output as well as passive study.","synonyms":["linguistic production"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Language Learning","word":"language accuracy","meaning":"the degree to which language is grammatically and lexically correct","translation":"độ chính xác ngôn ngữ","example":"Editing exercises can improve language accuracy.","synonyms":["linguistic accuracy"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Language Learning","word":"language confidence","meaning":"a learner's belief in their ability to communicate","translation":"sự tự tin ngôn ngữ","example":"Regular conversation can build language confidence.","synonyms":["communication confidence"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Language Learning","word":"language proficiency","meaning":"overall ability to understand and use a language","translation":"trình độ ngôn ngữ","example":"Language proficiency develops through sustained practice.","synonyms":["language ability"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Language Learning","word":"learning strategy","meaning":"a method used deliberately to improve learning","translation":"chiến lược học tập","example":"Keeping a vocabulary notebook is a simple learning strategy.","synonyms":["study strategy"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Language Learning","word":"memory technique","meaning":"a method used to remember information more effectively","translation":"kỹ thuật ghi nhớ","example":"Spaced repetition is a useful memory technique.","synonyms":["memorisation strategy"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Language Learning","word":"context clue","meaning":"information in surrounding language that helps explain an unfamiliar word","translation":"gợi ý ngữ cảnh","example":"Readers can use context clues to infer meaning.","synonyms":["contextual clue"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Language Learning","word":"guess meaning from context","meaning":"to infer a word's meaning using surrounding information","translation":"đoán nghĩa từ ngữ cảnh","example":"Strong readers often guess meaning from context before checking a dictionary.","synonyms":["infer meaning"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Language Learning","word":"paraphrase a sentence","meaning":"to express the same idea using different words or structures","translation":"diễn đạt lại câu","example":"IELTS learners should practise paraphrasing sentences accurately.","synonyms":["rephrase a sentence"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Language Learning","word":"self-correction","meaning":"the act of noticing and fixing one's own language error","translation":"tự sửa lỗi","example":"Self-correction is useful during speaking practice.","synonyms":["self-editing"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Language Learning","word":"language feedback","meaning":"information about strengths and errors in a learner's language","translation":"phản hồi ngôn ngữ","example":"Specific language feedback helps students improve faster.","synonyms":["linguistic feedback"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Language Learning","word":"pronunciation practice","meaning":"activity focused on producing speech sounds more clearly","translation":"luyện phát âm","example":"Shadowing can be useful pronunciation practice.","synonyms":["speech practice"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Language Learning","word":"word stress","meaning":"the stronger emphasis placed on one syllable in a word","translation":"trọng âm từ","example":"Incorrect word stress can make speech harder to understand.","synonyms":["lexical stress"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Language Learning","word":"sentence stress","meaning":"the pattern of stronger emphasis on important words in a sentence","translation":"trọng âm câu","example":"Sentence stress helps listeners identify key information.","synonyms":["speech stress"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Language Learning","word":"natural expression","meaning":"a word or phrase used in a way that sounds normal to fluent speakers","translation":"cách diễn đạt tự nhiên","example":"Learners should record natural expressions rather than isolated difficult words.","synonyms":["idiomatic expression"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Language Learning","word":"active vocabulary","meaning":"words and phrases a person can use when speaking or writing","translation":"từ vựng chủ động","example":"Speaking regularly helps move words into active vocabulary.","synonyms":["productive vocabulary"]},{"groupKey":"g2","groupName":"Nhóm 2 - Phát triển Band 5.0-6.5","topicName":"Language Learning","word":"passive vocabulary","meaning":"words and phrases a person recognises but rarely produces","translation":"từ vựng thụ động","example":"Reading widely can rapidly expand passive vocabulary.","synonyms":["receptive vocabulary"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"AI & Automation","word":"large language model","meaning":"an AI system trained on large amounts of text to understand and generate language","translation":"mô hình ngôn ngữ lớn","example":"Large language models are increasingly used in education and customer service.","synonyms":["LLM"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"AI & Automation","word":"generative model","meaning":"an AI model capable of creating new text, images or other content","translation":"mô hình sinh","example":"Generative models can accelerate creative work but also produce inaccurate information.","synonyms":["content-generating model"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"AI & Automation","word":"foundation model","meaning":"a large general-purpose AI model that can be adapted to many tasks","translation":"mô hình nền tảng","example":"Foundation models may support multiple applications from translation to coding.","synonyms":["general-purpose AI model"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"AI & Automation","word":"computer vision","meaning":"AI methods that allow computers to interpret visual information","translation":"thị giác máy tính","example":"Computer vision is widely used in medical imaging and autonomous vehicles.","synonyms":["machine vision"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"AI & Automation","word":"natural language processing","meaning":"computational methods for analysing and generating human language","translation":"xử lý ngôn ngữ tự nhiên","example":"Natural language processing powers many translation and chatbot systems.","synonyms":["NLP"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"AI & Automation","word":"predictive analytics","meaning":"the use of data and models to estimate future outcomes","translation":"phân tích dự đoán","example":"Employers use predictive analytics to forecast demand and staffing needs.","synonyms":["predictive modelling"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"AI & Automation","word":"algorithmic transparency","meaning":"the degree to which people can understand how an algorithm reaches decisions","translation":"minh bạch thuật toán","example":"Algorithmic transparency is important when AI affects access to public services.","synonyms":["explainability"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"AI & Automation","word":"explainable AI","meaning":"AI designed so that its decisions or outputs can be understood by humans","translation":"AI có thể giải thích","example":"Explainable AI may improve trust in high-stakes medical systems.","synonyms":["interpretable AI"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"AI & Automation","word":"automated decision system","meaning":"a system that makes or supports decisions with little human intervention","translation":"hệ thống ra quyết định tự động","example":"Automated decision systems require safeguards against unfair outcomes.","synonyms":["algorithmic decision system"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"AI & Automation","word":"human-in-the-loop","meaning":"a system design in which people review or influence automated decisions","translation":"con người tham gia vòng quyết định","example":"Human-in-the-loop processes are useful when errors could cause serious harm.","synonyms":["human review"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"AI & Automation","word":"AI governance","meaning":"rules, institutions and processes used to control the development and use of AI","translation":"quản trị AI","example":"AI governance must balance innovation with accountability.","synonyms":["governance of artificial intelligence"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"AI & Automation","word":"AI regulation","meaning":"laws and formal rules governing artificial intelligence systems","translation":"quy định về AI","example":"AI regulation is becoming a major policy issue worldwide.","synonyms":["AI rules"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"AI & Automation","word":"model accountability","meaning":"responsibility for the effects and performance of an AI model","translation":"trách nhiệm giải trình mô hình","example":"Model accountability is difficult when systems involve many organisations.","synonyms":["AI accountability"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"AI & Automation","word":"automation bias","meaning":"the tendency to trust automated recommendations too readily","translation":"thiên kiến tự động hóa","example":"Automation bias can cause professionals to overlook obvious system errors.","synonyms":["over-reliance on automation"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"AI & Automation","word":"data-driven decision-making","meaning":"making choices primarily on the basis of collected and analysed data","translation":"ra quyết định dựa trên dữ liệu","example":"Data-driven decision-making can improve efficiency when the data are reliable.","synonyms":["evidence-led decisions"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"AI & Automation","word":"digital transformation","meaning":"the broad adoption of digital technologies across an organisation or sector","translation":"chuyển đổi số","example":"Digital transformation is reshaping banking, retail and public administration.","synonyms":["technology transformation"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"AI & Automation","word":"process automation","meaning":"the use of technology to perform routine processes automatically","translation":"tự động hóa quy trình","example":"Process automation can reduce repetitive administrative work.","synonyms":["workflow automation"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"AI & Automation","word":"robotic process automation","meaning":"software automation used to perform repetitive digital tasks","translation":"tự động hóa quy trình bằng robot phần mềm","example":"Robotic process automation is common in finance and customer support.","synonyms":["RPA"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"AI & Automation","word":"intelligent automation","meaning":"automation that combines conventional workflows with AI capabilities","translation":"tự động hóa thông minh","example":"Intelligent automation can handle more complex tasks than simple scripts.","synonyms":["AI-enabled automation"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"AI & Automation","word":"autonomous decision-making","meaning":"decision-making carried out by a system without direct human approval","translation":"ra quyết định tự chủ","example":"Autonomous decision-making raises difficult questions about legal responsibility.","synonyms":["machine autonomy"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"AI & Automation","word":"AI-assisted work","meaning":"work completed with support from artificial intelligence tools","translation":"công việc có AI hỗ trợ","example":"AI-assisted work may allow professionals to focus on higher-value tasks.","synonyms":["AI-supported work"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"AI & Automation","word":"human-AI interaction","meaning":"the way people communicate and work with artificial intelligence systems","translation":"tương tác người-AI","example":"Good human-AI interaction depends on clear interfaces and appropriate trust.","synonyms":["human-machine interaction"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"AI & Automation","word":"technological displacement","meaning":"the replacement or reduction of human labour because of new technology","translation":"sự thay thế lao động bởi công nghệ","example":"Technological displacement may affect routine clerical occupations first.","synonyms":["technology-driven job loss"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"AI & Automation","word":"occupational restructuring","meaning":"changes in the types and organisation of jobs within an economy","translation":"tái cấu trúc nghề nghiệp","example":"AI is likely to accelerate occupational restructuring rather than eliminate all work.","synonyms":["job restructuring"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"AI & Automation","word":"automation exposure","meaning":"the degree to which a job or task can potentially be automated","translation":"mức độ tiếp xúc với tự động hóa","example":"Jobs with predictable tasks tend to have higher automation exposure.","synonyms":["automation risk"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"AI & Automation","word":"skills transition","meaning":"the process of workers moving from declining skills towards newly demanded ones","translation":"chuyển đổi kỹ năng","example":"A rapid skills transition will require cooperation between employers and educators.","synonyms":["skill shift"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"AI & Automation","word":"AI literacy","meaning":"the ability to understand, evaluate and use AI tools responsibly","translation":"năng lực hiểu biết AI","example":"AI literacy should include awareness of limitations and bias.","synonyms":["artificial-intelligence literacy"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"AI & Automation","word":"synthetic content","meaning":"text, images, audio or video created partly or wholly by AI","translation":"nội dung tổng hợp","example":"Synthetic content makes source verification more important.","synonyms":["AI-generated content"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"AI & Automation","word":"model hallucination","meaning":"an AI output that presents false or unsupported information as if it were reliable","translation":"ảo giác mô hình","example":"Model hallucination is a serious problem in legal and medical applications.","synonyms":["fabricated output"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"AI & Automation","word":"responsible AI","meaning":"the design and use of AI according to principles such as fairness, safety and accountability","translation":"AI có trách nhiệm","example":"Responsible AI requires both technical controls and institutional oversight.","synonyms":["ethical AI"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Climate Policy & Biodiversity","word":"carbon neutrality","meaning":"a state in which net carbon emissions are balanced by reductions or removals","translation":"trung hòa carbon","example":"Many companies have announced carbon-neutrality targets for future decades.","synonyms":["net-zero carbon"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Climate Policy & Biodiversity","word":"emissions reduction target","meaning":"a formal goal for lowering greenhouse-gas emissions","translation":"mục tiêu giảm phát thải","example":"Governments need credible plans to meet emissions-reduction targets.","synonyms":["climate target"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Climate Policy & Biodiversity","word":"national climate plan","meaning":"a government strategy setting out actions on emissions and adaptation","translation":"kế hoạch khí hậu quốc gia","example":"A national climate plan should include transport, energy and land use.","synonyms":["climate strategy"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Climate Policy & Biodiversity","word":"climate finance","meaning":"funding used for climate mitigation and adaptation activities","translation":"tài chính khí hậu","example":"Developing countries argue that climate finance remains insufficient.","synonyms":["green finance for climate"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Climate Policy & Biodiversity","word":"loss and damage","meaning":"climate-related harm that cannot be fully prevented through mitigation or adaptation","translation":"tổn thất và thiệt hại do khí hậu","example":"Small island states face severe loss and damage from rising seas.","synonyms":["climate harm"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Climate Policy & Biodiversity","word":"climate vulnerability","meaning":"the degree to which a community or ecosystem is likely to be harmed by climate change","translation":"tính dễ tổn thương khí hậu","example":"Poverty often increases climate vulnerability.","synonyms":["climate risk exposure"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Climate Policy & Biodiversity","word":"climate justice","meaning":"the principle that climate burdens and responsibilities should be distributed fairly","translation":"công bằng khí hậu","example":"Climate justice highlights the unequal impact of warming on poorer communities.","synonyms":["environmental justice"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Climate Policy & Biodiversity","word":"just transition","meaning":"a shift to a low-carbon economy that protects workers and vulnerable communities","translation":"chuyển đổi công bằng","example":"A just transition requires support for regions dependent on fossil-fuel jobs.","synonyms":["fair energy transition"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Climate Policy & Biodiversity","word":"nature-based solution","meaning":"an action that protects or restores ecosystems while addressing social or environmental problems","translation":"giải pháp dựa vào thiên nhiên","example":"Wetland restoration is a nature-based solution to flooding.","synonyms":["ecosystem-based solution"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Climate Policy & Biodiversity","word":"ecosystem restoration","meaning":"the process of helping damaged ecosystems recover","translation":"phục hồi hệ sinh thái","example":"Ecosystem restoration can improve biodiversity and water quality.","synonyms":["ecological restoration"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Climate Policy & Biodiversity","word":"habitat fragmentation","meaning":"the division of natural habitats into smaller isolated areas","translation":"phân mảnh sinh cảnh","example":"Road construction can accelerate habitat fragmentation.","synonyms":["fragmented habitat"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Climate Policy & Biodiversity","word":"ecological corridor","meaning":"a connected area that allows wildlife to move between habitats","translation":"hành lang sinh thái","example":"Ecological corridors help maintain genetic diversity.","synonyms":["wildlife corridor"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Climate Policy & Biodiversity","word":"species diversity","meaning":"the variety of different species within an ecosystem","translation":"đa dạng loài","example":"Healthy forests usually support high species diversity.","synonyms":["biological variety"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Climate Policy & Biodiversity","word":"conservation status","meaning":"an assessment of how threatened a species is","translation":"tình trạng bảo tồn","example":"The species' conservation status has worsened because of habitat loss.","synonyms":["threat status"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Climate Policy & Biodiversity","word":"protected species","meaning":"a species legally safeguarded from hunting, trade or disturbance","translation":"loài được bảo vệ","example":"Stronger enforcement is needed to protect threatened species.","synonyms":["legally protected wildlife"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Climate Policy & Biodiversity","word":"rewilding","meaning":"the restoration of natural ecological processes, often by reducing human control","translation":"tái hoang dã","example":"Rewilding projects can restore habitats but sometimes face local opposition.","synonyms":["ecological rewilding"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Climate Policy & Biodiversity","word":"habitat restoration","meaning":"the repair or recreation of habitats damaged by human activity","translation":"phục hồi sinh cảnh","example":"Habitat restoration is essential for many declining bird populations.","synonyms":["ecosystem restoration"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Climate Policy & Biodiversity","word":"biodiversity hotspot","meaning":"a region containing unusually high biodiversity under serious threat","translation":"điểm nóng đa dạng sinh học","example":"Protecting biodiversity hotspots can conserve many species at once.","synonyms":["high-diversity region"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Climate Policy & Biodiversity","word":"ecosystem service","meaning":"a benefit humans receive from ecosystems, such as pollination or flood control","translation":"dịch vụ hệ sinh thái","example":"Forests provide ecosystem services including water regulation and carbon storage.","synonyms":["ecological service"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Climate Policy & Biodiversity","word":"natural carbon sink","meaning":"a natural system that absorbs more carbon than it releases","translation":"bể hấp thụ carbon tự nhiên","example":"Peatlands are important natural carbon sinks.","synonyms":["carbon-absorbing ecosystem"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Climate Policy & Biodiversity","word":"land-use change","meaning":"a shift in how land is used, such as from forest to agriculture","translation":"thay đổi sử dụng đất","example":"Land-use change is a major driver of biodiversity loss.","synonyms":["change in land use"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Climate Policy & Biodiversity","word":"deforestation rate","meaning":"the speed at which forest area is being lost","translation":"tốc độ phá rừng","example":"Satellite monitoring can track changes in the deforestation rate.","synonyms":["rate of forest loss"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Climate Policy & Biodiversity","word":"forest conservation","meaning":"the protection and sustainable management of forests","translation":"bảo tồn rừng","example":"Forest conservation can support both biodiversity and local livelihoods.","synonyms":["forest protection"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Climate Policy & Biodiversity","word":"wildlife conservation","meaning":"the protection of wild species and their habitats","translation":"bảo tồn động vật hoang dã","example":"Wildlife conservation often requires cooperation across borders.","synonyms":["species conservation"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Climate Policy & Biodiversity","word":"environmental treaty","meaning":"an international legal agreement addressing environmental issues","translation":"hiệp ước môi trường","example":"Environmental treaties can coordinate action on shared ecosystems.","synonyms":["green treaty"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Climate Policy & Biodiversity","word":"climate commitment","meaning":"a formal promise to undertake climate-related action","translation":"cam kết khí hậu","example":"Countries face pressure to strengthen their climate commitments.","synonyms":["climate pledge"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Climate Policy & Biodiversity","word":"adaptation measure","meaning":"an action that reduces harm from present or future climate impacts","translation":"biện pháp thích ứng","example":"Improved drainage is a practical urban adaptation measure.","synonyms":["adaptation action"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Climate Policy & Biodiversity","word":"resilience planning","meaning":"planning designed to help communities or systems withstand shocks","translation":"quy hoạch khả năng chống chịu","example":"Coastal cities are investing in climate-resilience planning.","synonyms":["resilience strategy"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Climate Policy & Biodiversity","word":"climate-risk assessment","meaning":"a systematic evaluation of potential climate threats and impacts","translation":"đánh giá rủi ro khí hậu","example":"Infrastructure projects increasingly require a climate-risk assessment.","synonyms":["climate risk analysis"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Climate Policy & Biodiversity","word":"biodiversity governance","meaning":"institutions and rules used to protect and manage biological diversity","translation":"quản trị đa dạng sinh học","example":"Effective biodiversity governance must include local communities.","synonyms":["conservation governance"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Energy Transition","word":"renewable deployment","meaning":"the expansion and installation of renewable-energy technologies","translation":"triển khai năng lượng tái tạo","example":"Faster renewable deployment requires grid investment.","synonyms":["clean-energy deployment"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Energy Transition","word":"energy decarbonisation","meaning":"the reduction of carbon emissions from energy production and use","translation":"khử carbon trong năng lượng","example":"Energy decarbonisation is central to most net-zero strategies.","synonyms":["low-carbon transition"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Energy Transition","word":"grid modernisation","meaning":"upgrading electricity networks to handle new technologies and demand","translation":"hiện đại hóa lưới điện","example":"Grid modernisation is needed to integrate variable renewable power.","synonyms":["electricity-grid upgrade"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Energy Transition","word":"smart grid","meaning":"an electricity network using digital technology to balance supply and demand","translation":"lưới điện thông minh","example":"A smart grid can help households shift consumption away from peak periods.","synonyms":["intelligent grid"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Energy Transition","word":"battery storage","meaning":"systems that store electrical energy in batteries for later use","translation":"lưu trữ pin","example":"Battery storage can smooth fluctuations in solar and wind output.","synonyms":["energy storage"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Energy Transition","word":"renewable intermittency","meaning":"variation in renewable output because sunlight and wind are not constant","translation":"tính gián đoạn của năng lượng tái tạo","example":"Storage can reduce problems caused by renewable intermittency.","synonyms":["variable generation"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Energy Transition","word":"baseload power","meaning":"a steady level of electricity generation available continuously","translation":"nguồn điện nền","example":"Debates continue over which technologies should provide baseload power.","synonyms":["continuous power"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Energy Transition","word":"peak demand","meaning":"the highest level of electricity demand during a period","translation":"nhu cầu điện cao điểm","example":"Utilities must maintain enough capacity to meet peak demand.","synonyms":["maximum demand"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Energy Transition","word":"demand response","meaning":"changes in electricity use in reaction to prices or grid conditions","translation":"điều chỉnh nhu cầu điện","example":"Demand-response programmes can reduce pressure on the grid.","synonyms":["demand-side response"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Energy Transition","word":"energy efficiency standard","meaning":"a rule setting minimum efficiency levels for buildings or products","translation":"tiêu chuẩn hiệu quả năng lượng","example":"Stricter energy-efficiency standards can lower household bills.","synonyms":["efficiency regulation"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Energy Transition","word":"building retrofit","meaning":"upgrading an existing building to improve energy or environmental performance","translation":"cải tạo công trình","example":"Insulation is a common part of a building retrofit.","synonyms":["energy renovation"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Energy Transition","word":"heat pump","meaning":"a device that transfers heat efficiently for building heating or cooling","translation":"máy bơm nhiệt","example":"Heat pumps can replace fossil-fuel heating in many homes.","synonyms":["electric heating system"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Energy Transition","word":"electric mobility","meaning":"the use of electric vehicles and transport systems","translation":"giao thông điện","example":"Electric mobility can reduce urban air pollution when electricity is clean.","synonyms":["e-mobility"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Energy Transition","word":"charging infrastructure","meaning":"the network of facilities used to charge electric vehicles","translation":"hạ tầng sạc","example":"Electric-car adoption depends partly on charging infrastructure.","synonyms":["charging network"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Energy Transition","word":"green hydrogen","meaning":"hydrogen produced using renewable electricity","translation":"hydro xanh","example":"Green hydrogen may help decarbonise some heavy industries.","synonyms":["renewable hydrogen"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Energy Transition","word":"energy-intensive industry","meaning":"an industry that requires very large amounts of energy","translation":"ngành tiêu thụ nhiều năng lượng","example":"Steel and cement are major energy-intensive industries.","synonyms":["high-energy industry"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Energy Transition","word":"industrial decarbonisation","meaning":"the reduction of emissions from manufacturing and heavy industry","translation":"khử carbon công nghiệp","example":"Industrial decarbonisation may require new fuels and processes.","synonyms":["low-carbon industry"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Energy Transition","word":"fossil-fuel phase-out","meaning":"the gradual ending of coal, oil or gas use","translation":"loại bỏ dần nhiên liệu hóa thạch","example":"A fossil-fuel phase-out must consider energy security and employment.","synonyms":["ending fossil-fuel use"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Energy Transition","word":"coal phase-out","meaning":"the planned reduction and ending of coal use","translation":"loại bỏ dần than đá","example":"Several countries have set dates for a coal phase-out.","synonyms":["ending coal use"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Energy Transition","word":"stranded asset","meaning":"an asset that loses value unexpectedly because of economic or policy change","translation":"tài sản mắc kẹt","example":"Climate policy may turn some fossil-fuel infrastructure into stranded assets.","synonyms":["devalued asset"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Energy Transition","word":"energy poverty","meaning":"a situation in which households cannot afford adequate energy services","translation":"nghèo năng lượng","example":"Rapid price increases can worsen energy poverty.","synonyms":["fuel poverty"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Energy Transition","word":"affordability of energy","meaning":"the degree to which households and firms can pay for energy","translation":"khả năng chi trả năng lượng","example":"Policy must balance decarbonisation with energy affordability.","synonyms":["energy affordability"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Energy Transition","word":"energy subsidy reform","meaning":"changes to government support that lowers energy prices or production costs","translation":"cải cách trợ cấp năng lượng","example":"Energy-subsidy reform can free public money but may raise household bills.","synonyms":["subsidy restructuring"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Energy Transition","word":"renewable investment","meaning":"capital spent on clean-energy generation and related systems","translation":"đầu tư năng lượng tái tạo","example":"Stable policy can attract long-term renewable investment.","synonyms":["clean-energy investment"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Energy Transition","word":"green electricity","meaning":"electricity generated from low-carbon renewable sources","translation":"điện xanh","example":"Companies increasingly purchase green electricity to reduce emissions.","synonyms":["renewable electricity"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Energy Transition","word":"power-sector emissions","meaning":"greenhouse-gas emissions produced by electricity generation","translation":"phát thải ngành điện","example":"Coal replacement has reduced power-sector emissions in several economies.","synonyms":["electricity emissions"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Energy Transition","word":"energy-market reform","meaning":"changes to market rules governing energy supply, pricing or competition","translation":"cải cách thị trường năng lượng","example":"Energy-market reform can encourage flexible low-carbon generation.","synonyms":["power-market reform"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Energy Transition","word":"transmission capacity","meaning":"the amount of electricity a high-voltage network can transport","translation":"năng lực truyền tải","example":"Insufficient transmission capacity can delay renewable projects.","synonyms":["grid transmission capacity"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Energy Transition","word":"distributed generation","meaning":"electricity produced by many small sources close to users","translation":"phát điện phân tán","example":"Rooftop solar is a common form of distributed generation.","synonyms":["decentralised generation"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Energy Transition","word":"energy-system resilience","meaning":"the ability of an energy system to withstand and recover from disruption","translation":"khả năng chống chịu hệ thống năng lượng","example":"Diversified supply can strengthen energy-system resilience.","synonyms":["energy resilience"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Governance & Civic Responsibility","word":"public-sector integrity","meaning":"honest and ethical conduct within government institutions","translation":"liêm chính khu vực công","example":"Public-sector integrity is essential for institutional trust.","synonyms":["government integrity"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Governance & Civic Responsibility","word":"anti-corruption measure","meaning":"an action designed to prevent or punish corruption","translation":"biện pháp chống tham nhũng","example":"Transparent procurement is an important anti-corruption measure.","synonyms":["corruption control"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Governance & Civic Responsibility","word":"conflict of interest","meaning":"a situation in which personal interests may improperly influence official duties","translation":"xung đột lợi ích","example":"Officials should disclose any conflict of interest.","synonyms":["competing interest"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Governance & Civic Responsibility","word":"public procurement","meaning":"the process by which government buys goods and services","translation":"mua sắm công","example":"Digital public procurement can improve transparency.","synonyms":["government purchasing"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Governance & Civic Responsibility","word":"institutional capacity","meaning":"the ability of an institution to perform its functions effectively","translation":"năng lực thể chế","example":"Policy success depends on adequate institutional capacity.","synonyms":["organisational capacity"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Governance & Civic Responsibility","word":"government effectiveness","meaning":"the quality and reliability of public institutions and services","translation":"hiệu quả chính phủ","example":"Government effectiveness influences public confidence.","synonyms":["state effectiveness"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Governance & Civic Responsibility","word":"administrative transparency","meaning":"openness about government procedures, decisions and information","translation":"minh bạch hành chính","example":"Administrative transparency can reduce opportunities for corruption.","synonyms":["government openness"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Governance & Civic Responsibility","word":"public oversight","meaning":"monitoring of government or organisations by citizens and institutions","translation":"giám sát công","example":"Independent audits strengthen public oversight.","synonyms":["external oversight"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Governance & Civic Responsibility","word":"independent regulator","meaning":"a body that controls a sector without direct political or commercial influence","translation":"cơ quan quản lý độc lập","example":"An independent regulator can improve confidence in utility pricing.","synonyms":["autonomous regulator"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Governance & Civic Responsibility","word":"institutional independence","meaning":"the ability of an institution to act without improper outside pressure","translation":"tính độc lập thể chế","example":"Judicial credibility depends partly on institutional independence.","synonyms":["organisational autonomy"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Governance & Civic Responsibility","word":"policy coherence","meaning":"the degree to which different policies support rather than contradict one another","translation":"tính nhất quán chính sách","example":"Climate goals require greater policy coherence across transport and energy.","synonyms":["policy consistency"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Governance & Civic Responsibility","word":"policy coordination","meaning":"the alignment of actions across ministries, agencies or levels of government","translation":"phối hợp chính sách","example":"Complex social problems require strong policy coordination.","synonyms":["government coordination"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Governance & Civic Responsibility","word":"citizen involvement","meaning":"active involvement of citizens in public decisions or community affairs","translation":"sự tham gia của công dân","example":"Citizen involvement can improve the legitimacy of local decisions.","synonyms":["civic involvement"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Governance & Civic Responsibility","word":"participatory governance","meaning":"governance that directly involves citizens and stakeholders in decision-making","translation":"quản trị có sự tham gia","example":"Participatory governance may improve local development projects.","synonyms":["inclusive governance"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Governance & Civic Responsibility","word":"civic literacy","meaning":"knowledge of political institutions, rights and public responsibilities","translation":"hiểu biết công dân","example":"Schools can strengthen civic literacy through practical education.","synonyms":["civic knowledge"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Governance & Civic Responsibility","word":"civic institution","meaning":"an organisation that supports public, community or democratic life","translation":"thể chế dân sự","example":"Healthy democracies depend on strong civic institutions.","synonyms":["public institution"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Governance & Civic Responsibility","word":"political accountability","meaning":"the obligation of political leaders to explain actions and face consequences","translation":"trách nhiệm giải trình chính trị","example":"Free elections are one mechanism of political accountability.","synonyms":["democratic accountability"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Governance & Civic Responsibility","word":"public legitimacy","meaning":"the degree to which people accept an institution's authority as justified","translation":"tính chính danh công","example":"Transparent decision-making can strengthen public legitimacy.","synonyms":["institutional legitimacy"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Governance & Civic Responsibility","word":"institutional credibility","meaning":"the level of trust placed in an institution's competence and honesty","translation":"uy tín thể chế","example":"Inconsistent enforcement can damage institutional credibility.","synonyms":["institutional trustworthiness"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Governance & Civic Responsibility","word":"citizen trust","meaning":"confidence citizens have in public institutions and leaders","translation":"niềm tin của công dân","example":"Citizen trust falls when corruption is widespread.","synonyms":["public trust"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Governance & Civic Responsibility","word":"regulatory enforcement","meaning":"the practical application of rules and penalties","translation":"thực thi quy định","example":"Strong laws have little impact without regulatory enforcement.","synonyms":["rule enforcement"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Governance & Civic Responsibility","word":"regulatory compliance","meaning":"the act of following laws, standards and formal rules","translation":"tuân thủ quy định","example":"Clear guidance can improve regulatory compliance among small firms.","synonyms":["legal compliance"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Governance & Civic Responsibility","word":"public grievance","meaning":"a complaint or perceived injustice raised by citizens","translation":"khiếu nại công","example":"Effective channels are needed to resolve public grievances.","synonyms":["citizen complaint"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Governance & Civic Responsibility","word":"ombudsman","meaning":"an independent official who investigates complaints against organisations or government","translation":"thanh tra viên độc lập","example":"An ombudsman can help citizens challenge administrative unfairness.","synonyms":["public complaints officer"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Governance & Civic Responsibility","word":"civic responsibility","meaning":"the duties individuals have towards their community and society","translation":"trách nhiệm công dân","example":"Voting and respecting public spaces are forms of civic responsibility.","synonyms":["civic duty"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Governance & Civic Responsibility","word":"community participation","meaning":"involvement in local organisations, decisions or volunteer activities","translation":"tham gia cộng đồng","example":"Community participation can improve local project design.","synonyms":["local engagement"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Governance & Civic Responsibility","word":"social contract","meaning":"the implicit agreement between citizens and the state about rights and obligations","translation":"khế ước xã hội","example":"Tax compliance depends partly on confidence in the social contract.","synonyms":["state-citizen agreement"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Governance & Civic Responsibility","word":"administrative reform","meaning":"changes intended to improve public-sector institutions and procedures","translation":"cải cách hành chính","example":"Digital services are a major component of administrative reform.","synonyms":["government reform"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Governance & Civic Responsibility","word":"institutional reform","meaning":"changes to rules, structures or organisations intended to improve governance","translation":"cải cách thể chế","example":"Institutional reform can take years to produce stable results.","synonyms":["structural reform"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Governance & Civic Responsibility","word":"governance quality","meaning":"the overall effectiveness, fairness and accountability of public institutions","translation":"chất lượng quản trị","example":"Governance quality strongly affects development outcomes.","synonyms":["quality of government"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Inequality & Economic Policy","word":"income distribution","meaning":"the way total income is shared across people or households","translation":"phân phối thu nhập","example":"Tax and welfare policy can alter the distribution of income.","synonyms":["distribution of earnings"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Inequality & Economic Policy","word":"wealth concentration","meaning":"the accumulation of a large share of wealth among a small group","translation":"tập trung tài sản","example":"Rapid asset-price growth can increase wealth concentration.","synonyms":["concentration of wealth"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Inequality & Economic Policy","word":"intergenerational inequality","meaning":"unequal opportunities or resources between age groups or generations","translation":"bất bình đẳng giữa các thế hệ","example":"Housing costs have intensified intergenerational inequality in some cities.","synonyms":["generational inequality"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Inequality & Economic Policy","word":"regional inequality","meaning":"unequal economic outcomes between different geographic areas","translation":"bất bình đẳng vùng miền","example":"Infrastructure investment can help reduce regional inequality.","synonyms":["spatial inequality"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Inequality & Economic Policy","word":"income redistribution","meaning":"the transfer of income through taxes, benefits or public services","translation":"tái phân phối thu nhập","example":"Progressive taxation is one mechanism of income redistribution.","synonyms":["redistribution"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Inequality & Economic Policy","word":"wealth tax","meaning":"a tax charged on a person's accumulated assets or net wealth","translation":"thuế tài sản","example":"Supporters argue that a wealth tax can fund public services.","synonyms":["net-wealth tax"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Inequality & Economic Policy","word":"capital gains tax","meaning":"a tax on profits made when assets increase in value and are sold","translation":"thuế lãi vốn","example":"Capital gains tax affects returns from property and investments.","synonyms":["tax on investment gains"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Inequality & Economic Policy","word":"inheritance tax","meaning":"a tax on wealth transferred after a person's death","translation":"thuế thừa kế","example":"Inheritance tax is often debated as a tool for limiting dynastic wealth.","synonyms":["estate tax"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Inequality & Economic Policy","word":"tax progressivity","meaning":"the degree to which tax rates rise as income or wealth increases","translation":"tính lũy tiến của thuế","example":"Greater tax progressivity can increase redistribution.","synonyms":["progressive tax structure"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Inequality & Economic Policy","word":"fiscal redistribution","meaning":"redistribution achieved through government taxation and spending","translation":"tái phân phối tài khóa","example":"Fiscal redistribution significantly reduces poverty in some countries.","synonyms":["tax-and-transfer redistribution"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Inequality & Economic Policy","word":"social transfer","meaning":"a payment or benefit provided by government to households","translation":"chuyển giao xã hội","example":"Social transfers protect vulnerable families during recessions.","synonyms":["welfare transfer"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Inequality & Economic Policy","word":"targeted benefit","meaning":"public financial support restricted to eligible groups","translation":"trợ cấp có mục tiêu","example":"Targeted benefits can direct resources towards the poorest households.","synonyms":["means-tested benefit"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Inequality & Economic Policy","word":"universal benefit","meaning":"a public benefit available broadly without strict income testing","translation":"trợ cấp phổ quát","example":"Universal benefits are simpler to administer but can be costly.","synonyms":["universal payment"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Inequality & Economic Policy","word":"minimum-income guarantee","meaning":"a policy ensuring households receive at least a basic level of income","translation":"bảo đảm thu nhập tối thiểu","example":"A minimum-income guarantee may reduce extreme poverty.","synonyms":["income floor"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Inequality & Economic Policy","word":"living wage","meaning":"a wage intended to cover the basic cost of living in a particular place","translation":"mức lương đủ sống","example":"Campaigners argue that the statutory minimum is below a living wage.","synonyms":["adequate wage"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Inequality & Economic Policy","word":"wage stagnation","meaning":"a prolonged period in which wages grow very little","translation":"trì trệ tiền lương","example":"Wage stagnation can weaken household purchasing power.","synonyms":["flat wage growth"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Inequality & Economic Policy","word":"real wage","meaning":"a wage adjusted for changes in prices and inflation","translation":"tiền lương thực tế","example":"Real wages fall when prices rise faster than pay.","synonyms":["inflation-adjusted wage"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Inequality & Economic Policy","word":"income decile","meaning":"one of ten groups formed by ranking a population by income","translation":"nhóm thập phân vị thu nhập","example":"The tax burden varies substantially across income deciles.","synonyms":["income tenth"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Inequality & Economic Policy","word":"poverty trap","meaning":"a situation in which low income and weak opportunities make escape from poverty difficult","translation":"bẫy nghèo","example":"Poor access to education can reinforce a poverty trap.","synonyms":["cycle of poverty"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Inequality & Economic Policy","word":"relative poverty","meaning":"poverty measured in relation to typical living standards in a society","translation":"nghèo tương đối","example":"Relative poverty can persist even when average income rises.","synonyms":["income poverty"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Inequality & Economic Policy","word":"absolute poverty","meaning":"a condition in which basic needs cannot be met","translation":"nghèo tuyệt đối","example":"Economic growth has reduced absolute poverty in many regions.","synonyms":["extreme material deprivation"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Inequality & Economic Policy","word":"economic exclusion","meaning":"limited access to jobs, finance or economic opportunities","translation":"loại trừ kinh tế","example":"Discrimination can contribute to economic exclusion.","synonyms":["financial exclusion"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Inequality & Economic Policy","word":"inclusive growth","meaning":"economic growth whose benefits are broadly shared across society","translation":"tăng trưởng bao trùm","example":"Inclusive growth requires access to education and productive employment.","synonyms":["shared growth"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Inequality & Economic Policy","word":"redistributive policy","meaning":"government policy intended to reduce economic inequality by transferring resources","translation":"chính sách tái phân phối","example":"Redistributive policies often combine taxation with social spending.","synonyms":["equality-oriented policy"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Inequality & Economic Policy","word":"macroeconomic stability","meaning":"a condition of relatively stable prices, employment and economic growth","translation":"ổn định kinh tế vĩ mô","example":"Macroeconomic stability helps households and firms plan for the future.","synonyms":["economic stability"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Inequality & Economic Policy","word":"fiscal sustainability","meaning":"the ability of government finances to remain manageable over the long term","translation":"bền vững tài khóa","example":"Population ageing poses challenges for fiscal sustainability.","synonyms":["sustainable public finances"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Inequality & Economic Policy","word":"public debt burden","meaning":"the financial pressure created by accumulated government borrowing","translation":"gánh nặng nợ công","example":"High interest rates can increase the public-debt burden.","synonyms":["government debt pressure"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Inequality & Economic Policy","word":"cost-of-living crisis","meaning":"a period when essential household costs rise sharply relative to income","translation":"khủng hoảng chi phí sinh hoạt","example":"A cost-of-living crisis can push middle-income households into hardship.","synonyms":["living-cost crisis"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Inequality & Economic Policy","word":"economic vulnerability","meaning":"exposure to financial shocks because of low income, debt or insecure work","translation":"tính dễ tổn thương kinh tế","example":"Single-income households may face greater economic vulnerability.","synonyms":["financial vulnerability"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Inequality & Economic Policy","word":"equality of opportunity","meaning":"the principle that people should have fair chances regardless of background","translation":"bình đẳng cơ hội","example":"Education policy is often justified in terms of equality of opportunity.","synonyms":["equal opportunity"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Labour Market & Future of Work","word":"labour-force participation","meaning":"the proportion of working-age people employed or actively seeking work","translation":"tỷ lệ tham gia lực lượng lao động","example":"Affordable childcare can raise labour-force participation.","synonyms":["workforce participation rate"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Labour Market & Future of Work","word":"employment rate","meaning":"the proportion of working-age people who are employed","translation":"tỷ lệ có việc làm","example":"The employment rate recovered after the recession.","synonyms":["rate of employment"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Labour Market & Future of Work","word":"underemployment","meaning":"a situation in which people work fewer hours or below their skill level than desired","translation":"thiếu việc làm","example":"Underemployment is common among some recent graduates.","synonyms":["insufficient employment"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Labour Market & Future of Work","word":"job polarisation","meaning":"growth in high- and low-skill jobs alongside decline in middle-skill work","translation":"phân cực việc làm","example":"Automation has contributed to job polarisation in several economies.","synonyms":["occupational polarisation"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Labour Market & Future of Work","word":"occupational upgrading","meaning":"a shift in employment towards more skilled or higher-value occupations","translation":"nâng cấp cơ cấu nghề nghiệp","example":"Digitalisation can produce occupational upgrading in some sectors.","synonyms":["skill upgrading"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Labour Market & Future of Work","word":"skills obsolescence","meaning":"the loss of value of skills because technology or work practices change","translation":"lỗi thời kỹ năng","example":"Rapid automation increases the risk of skills obsolescence.","synonyms":["outdated skills"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Labour Market & Future of Work","word":"reskilling programme","meaning":"organised training that prepares workers for different occupations","translation":"chương trình đào tạo lại kỹ năng","example":"Governments fund reskilling programmes for workers in declining industries.","synonyms":["career retraining"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Labour Market & Future of Work","word":"upskilling programme","meaning":"training that develops more advanced skills within or beyond a current role","translation":"chương trình nâng cao kỹ năng","example":"Firms use upskilling programmes to prepare staff for digital tools.","synonyms":["advanced training"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Labour Market & Future of Work","word":"skills gap","meaning":"the difference between skills employers need and those workers possess","translation":"khoảng cách kỹ năng","example":"A persistent skills gap can restrict productivity growth.","synonyms":["skill shortage"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Labour Market & Future of Work","word":"skills shortage","meaning":"a lack of workers with particular qualifications or capabilities","translation":"thiếu hụt kỹ năng","example":"Healthcare faces a serious skills shortage in many countries.","synonyms":["shortage of qualified workers"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Labour Market & Future of Work","word":"labour-market flexibility","meaning":"the ease with which workers, wages and jobs can adjust to economic change","translation":"tính linh hoạt thị trường lao động","example":"Labour-market flexibility can support adjustment but may weaken security.","synonyms":["employment flexibility"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Labour Market & Future of Work","word":"employment protection","meaning":"laws and institutions that limit unfair dismissal or insecure treatment","translation":"bảo vệ việc làm","example":"Strong employment protection can reduce arbitrary dismissal.","synonyms":["job protection"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Labour Market & Future of Work","word":"employment precarity","meaning":"insecurity caused by unstable, temporary or weakly protected work","translation":"tính bấp bênh việc làm","example":"Young workers experience high levels of employment precarity.","synonyms":["job insecurity"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Labour Market & Future of Work","word":"platform work","meaning":"paid work organised through digital platforms","translation":"lao động nền tảng","example":"Platform work offers flexibility but raises questions about worker rights.","synonyms":["app-based work"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Labour Market & Future of Work","word":"gig worker","meaning":"a person earning income from short-term tasks or platform jobs","translation":"lao động gig","example":"Gig workers may lack paid leave and pension contributions.","synonyms":["platform worker"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Labour Market & Future of Work","word":"independent contractor","meaning":"a self-employed person hired to provide services without standard employee status","translation":"nhà thầu độc lập","example":"Some companies classify drivers as independent contractors.","synonyms":["freelance contractor"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Labour Market & Future of Work","word":"labour rights","meaning":"legal and social rights protecting workers","translation":"quyền lao động","example":"Labour rights include safe conditions and freedom from discrimination.","synonyms":["workers' rights"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Labour Market & Future of Work","word":"collective representation","meaning":"the representation of workers' interests through unions or similar bodies","translation":"đại diện tập thể","example":"Collective representation can strengthen workers' bargaining position.","synonyms":["worker representation"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Labour Market & Future of Work","word":"union membership","meaning":"the status or rate of workers belonging to trade unions","translation":"tư cách thành viên công đoàn","example":"Union membership has declined in several service sectors.","synonyms":["trade-union membership"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Labour Market & Future of Work","word":"wage bargaining","meaning":"negotiation between workers and employers over pay","translation":"thương lượng tiền lương","example":"Sector-wide wage bargaining can reduce pay differences.","synonyms":["pay negotiation"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Labour Market & Future of Work","word":"career mobility across sectors","meaning":"the ability of workers to move between occupations or industries","translation":"khả năng dịch chuyển nghề nghiệp giữa các ngành","example":"Transferable skills improve career mobility across sectors.","synonyms":["cross-sector mobility"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Labour Market & Future of Work","word":"geographic labour mobility","meaning":"the movement of workers between places for employment","translation":"di chuyển lao động theo địa lý","example":"Housing costs can reduce geographic labour mobility.","synonyms":["worker mobility"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Labour Market & Future of Work","word":"remote-first workplace","meaning":"an organisation designed around remote rather than office-based work","translation":"nơi làm việc ưu tiên từ xa","example":"Remote-first workplaces can recruit across wider geographic areas.","synonyms":["remote-centred workplace"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Labour Market & Future of Work","word":"hybrid working model","meaning":"an arrangement combining remote and workplace-based employment","translation":"mô hình làm việc kết hợp","example":"A hybrid working model can reduce commuting time.","synonyms":["hybrid work arrangement"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Labour Market & Future of Work","word":"workplace flexibility","meaning":"the ability to vary working location, schedule or hours","translation":"tính linh hoạt nơi làm việc","example":"Workplace flexibility can support employees with caring duties.","synonyms":["flexible employment"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Labour Market & Future of Work","word":"employee autonomy","meaning":"the freedom workers have to control how they perform their jobs","translation":"quyền tự chủ của nhân viên","example":"Employee autonomy is often associated with higher job satisfaction.","synonyms":["work autonomy"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Labour Market & Future of Work","word":"occupational health","meaning":"the protection of workers' physical and mental health at work","translation":"sức khỏe nghề nghiệp","example":"Occupational-health standards matter in both factories and offices.","synonyms":["workplace health"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Labour Market & Future of Work","word":"workforce resilience","meaning":"the ability of workers and organisations to adapt to shocks and change","translation":"khả năng chống chịu của lực lượng lao động","example":"Continuous training strengthens workforce resilience.","synonyms":["labour resilience"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Labour Market & Future of Work","word":"digital labour platform","meaning":"an online system that matches workers with paid tasks or clients","translation":"nền tảng lao động số","example":"Digital labour platforms have expanded rapidly in delivery services.","synonyms":["work platform"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Labour Market & Future of Work","word":"future-ready skills","meaning":"skills expected to remain valuable as technology and work evolve","translation":"kỹ năng sẵn sàng cho tương lai","example":"Problem-solving and adaptability are often described as future-ready skills.","synonyms":["future skills"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Healthcare Systems & Bioethics","word":"primary care","meaning":"first-contact healthcare for common conditions, prevention and referrals","translation":"chăm sóc ban đầu","example":"Strong primary care can reduce unnecessary hospital admissions.","synonyms":["frontline healthcare"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Healthcare Systems & Bioethics","word":"secondary care","meaning":"specialist healthcare usually accessed after referral","translation":"chăm sóc chuyên khoa tuyến hai","example":"Secondary care includes many hospital-based specialist services.","synonyms":["specialist care"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Healthcare Systems & Bioethics","word":"tertiary care","meaning":"highly specialised medical treatment for complex conditions","translation":"chăm sóc chuyên sâu","example":"Major teaching hospitals provide tertiary care.","synonyms":["advanced specialist care"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Healthcare Systems & Bioethics","word":"health-system capacity","meaning":"the ability of a healthcare system to provide services to its population","translation":"năng lực hệ thống y tế","example":"Pandemics can expose weaknesses in health-system capacity.","synonyms":["healthcare capacity"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Healthcare Systems & Bioethics","word":"clinical workforce","meaning":"doctors, nurses and other professionals providing direct patient care","translation":"lực lượng lao động lâm sàng","example":"An ageing clinical workforce may worsen staff shortages.","synonyms":["medical workforce"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Healthcare Systems & Bioethics","word":"healthcare financing","meaning":"the methods used to raise and allocate money for healthcare","translation":"tài chính y tế","example":"Healthcare financing shapes access and service quality.","synonyms":["health funding"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Healthcare Systems & Bioethics","word":"out-of-pocket payment","meaning":"money patients pay directly for healthcare rather than through insurance","translation":"chi trả y tế trực tiếp","example":"High out-of-pocket payments can deter low-income patients from seeking care.","synonyms":["direct medical payment"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Healthcare Systems & Bioethics","word":"universal coverage","meaning":"a system in which all people can obtain needed health services without severe financial hardship","translation":"bao phủ y tế toàn dân","example":"Universal coverage remains a central health-policy objective.","synonyms":["universal health coverage"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Healthcare Systems & Bioethics","word":"waiting time","meaning":"the period patients wait before receiving consultation or treatment","translation":"thời gian chờ y tế","example":"Long waiting times can delay diagnosis and treatment.","synonyms":["treatment delay"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Healthcare Systems & Bioethics","word":"healthcare access gap","meaning":"an unequal difference in the ability to obtain medical services","translation":"khoảng cách tiếp cận y tế","example":"Rural areas often face a healthcare-access gap.","synonyms":["medical access disparity"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Healthcare Systems & Bioethics","word":"clinical guideline","meaning":"an evidence-based recommendation for medical diagnosis or treatment","translation":"hướng dẫn lâm sàng","example":"Clinical guidelines help standardise high-quality care.","synonyms":["medical guideline"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Healthcare Systems & Bioethics","word":"patient safety","meaning":"the prevention of avoidable harm during healthcare","translation":"an toàn người bệnh","example":"Better reporting systems can improve patient safety.","synonyms":["clinical safety"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Healthcare Systems & Bioethics","word":"quality-adjusted life year","meaning":"a measure combining length and quality of life used in health economics","translation":"năm sống điều chỉnh theo chất lượng","example":"Some agencies use quality-adjusted life years when evaluating treatments.","synonyms":["QALY"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Healthcare Systems & Bioethics","word":"cost-effectiveness","meaning":"the degree to which benefits justify financial costs","translation":"hiệu quả chi phí","example":"Health authorities assess the cost-effectiveness of expensive medicines.","synonyms":["value for money"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Healthcare Systems & Bioethics","word":"resource allocation","meaning":"the distribution of limited staff, money or equipment across needs","translation":"phân bổ nguồn lực","example":"Resource allocation becomes difficult when demand exceeds capacity.","synonyms":["allocation of resources"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Healthcare Systems & Bioethics","word":"triage","meaning":"the prioritisation of patients according to urgency and need","translation":"phân loại cấp cứu","example":"Emergency departments use triage to treat the most urgent cases first.","synonyms":["patient prioritisation"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Healthcare Systems & Bioethics","word":"clinical ethics","meaning":"ethical principles applied to patient care and medical decisions","translation":"đạo đức lâm sàng","example":"Clinical ethics is especially important when treatment choices are uncertain.","synonyms":["medical ethics"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Healthcare Systems & Bioethics","word":"end-of-life care","meaning":"medical and supportive care provided near the end of a person's life","translation":"chăm sóc cuối đời","example":"End-of-life care should respect patient preferences and comfort.","synonyms":["palliative care"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Healthcare Systems & Bioethics","word":"advance directive","meaning":"a document stating a person's future healthcare wishes if they cannot decide later","translation":"chỉ thị y tế trước","example":"An advance directive can guide difficult end-of-life decisions.","synonyms":["living will"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Healthcare Systems & Bioethics","word":"genetic counselling","meaning":"professional guidance about inherited conditions and genetic testing","translation":"tư vấn di truyền","example":"Genetic counselling helps families understand test results and risks.","synonyms":["genetic advice"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Healthcare Systems & Bioethics","word":"reproductive ethics","meaning":"ethical questions concerning fertility treatment, reproduction and related technologies","translation":"đạo đức sinh sản","example":"Reproductive ethics involves debates about access and consent.","synonyms":["bioethics of reproduction"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Healthcare Systems & Bioethics","word":"medical confidentiality","meaning":"the duty to keep patient information private","translation":"bảo mật y tế","example":"Medical confidentiality is fundamental to patient trust.","synonyms":["patient confidentiality"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Healthcare Systems & Bioethics","word":"clinical consent","meaning":"a patient's informed agreement to a medical procedure or treatment","translation":"đồng thuận lâm sàng","example":"Valid clinical consent requires clear information and voluntary choice.","synonyms":["informed medical consent"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Healthcare Systems & Bioethics","word":"organ allocation","meaning":"the process of deciding which patients receive donated organs","translation":"phân bổ nội tạng","example":"Organ allocation systems must balance urgency and fairness.","synonyms":["transplant allocation"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Healthcare Systems & Bioethics","word":"health-data privacy","meaning":"the protection of personal medical information","translation":"quyền riêng tư dữ liệu sức khỏe","example":"Digital records have increased concern about health-data privacy.","synonyms":["medical data privacy"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Healthcare Systems & Bioethics","word":"public-health ethics","meaning":"ethical principles governing population-level health interventions","translation":"đạo đức y tế công cộng","example":"Public-health ethics considers the balance between liberty and collective safety.","synonyms":["population-health ethics"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Healthcare Systems & Bioethics","word":"medical overtreatment","meaning":"the provision of more medical intervention than is beneficial or necessary","translation":"điều trị y tế quá mức","example":"Screening programmes should avoid unnecessary medical overtreatment.","synonyms":["overmedicalisation"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Healthcare Systems & Bioethics","word":"health technology assessment","meaning":"systematic evaluation of medical technologies for effectiveness, cost and impact","translation":"đánh giá công nghệ y tế","example":"Health-technology assessment informs reimbursement decisions.","synonyms":["HTA"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Healthcare Systems & Bioethics","word":"care continuity","meaning":"the coordination and consistency of healthcare across time and providers","translation":"tính liên tục chăm sóc","example":"Electronic records can improve care continuity for chronic patients.","synonyms":["continuity of care"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Healthcare Systems & Bioethics","word":"patient-centred care","meaning":"healthcare organised around patients' needs, values and preferences","translation":"chăm sóc lấy bệnh nhân làm trung tâm","example":"Patient-centred care can improve communication and satisfaction.","synonyms":["person-centred care"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Criminal Justice & Rehabilitation","word":"sentencing guideline","meaning":"a formal framework helping courts determine appropriate penalties","translation":"hướng dẫn tuyên án","example":"Sentencing guidelines aim to improve consistency between similar cases.","synonyms":["sentencing framework"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Criminal Justice & Rehabilitation","word":"mandatory sentence","meaning":"a punishment that law requires for a specified offence","translation":"án bắt buộc","example":"Critics argue that mandatory sentences reduce judicial discretion.","synonyms":["compulsory sentence"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Criminal Justice & Rehabilitation","word":"judicial discretion","meaning":"the freedom judges have to make decisions within legal boundaries","translation":"quyền tự quyết tư pháp","example":"Judicial discretion allows courts to consider individual circumstances.","synonyms":["judicial flexibility"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Criminal Justice & Rehabilitation","word":"proportionality principle","meaning":"the principle that punishment should match the seriousness of an offence","translation":"nguyên tắc tương xứng","example":"The proportionality principle is central to fair sentencing.","synonyms":["proportionate justice"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Criminal Justice & Rehabilitation","word":"probation","meaning":"a sentence allowing an offender to live in the community under supervision","translation":"án treo, quản chế","example":"Probation can combine supervision with rehabilitation services.","synonyms":["community supervision"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Criminal Justice & Rehabilitation","word":"parole","meaning":"conditional release from prison before a sentence is fully completed","translation":"tạm tha có điều kiện","example":"Parole may depend on behaviour and assessed risk.","synonyms":["conditional release"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Criminal Justice & Rehabilitation","word":"pre-trial detention","meaning":"detention of an accused person before trial","translation":"tạm giam trước xét xử","example":"Excessive pre-trial detention can contribute to prison overcrowding.","synonyms":["remand detention"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Criminal Justice & Rehabilitation","word":"prison reform","meaning":"changes intended to improve prisons, rights or rehabilitation outcomes","translation":"cải cách nhà tù","example":"Prison reform often focuses on safety, education and reintegration.","synonyms":["correctional reform"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Criminal Justice & Rehabilitation","word":"correctional education","meaning":"education and training provided within prisons","translation":"giáo dục cải huấn","example":"Correctional education can reduce barriers to employment after release.","synonyms":["prison education"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Criminal Justice & Rehabilitation","word":"vocational rehabilitation","meaning":"skills training designed to help offenders gain lawful employment","translation":"phục hồi nghề nghiệp","example":"Vocational rehabilitation can support successful reintegration.","synonyms":["job-training rehabilitation"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Criminal Justice & Rehabilitation","word":"post-release support","meaning":"services provided to people after leaving prison","translation":"hỗ trợ sau khi ra tù","example":"Stable housing is a key part of post-release support.","synonyms":["reentry support"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Criminal Justice & Rehabilitation","word":"reentry programme","meaning":"a programme helping former prisoners return to community life","translation":"chương trình tái hòa nhập","example":"Reentry programmes often combine housing, counselling and employment services.","synonyms":["reintegration programme"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Criminal Justice & Rehabilitation","word":"restorative process","meaning":"a justice process focused on repairing harm through dialogue and accountability","translation":"quy trình công lý phục hồi","example":"A restorative process may allow victims to explain the impact of an offence.","synonyms":["restorative justice process"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Criminal Justice & Rehabilitation","word":"victim-offender mediation","meaning":"structured dialogue between a victim and offender with professional support","translation":"hòa giải nạn nhân-người phạm tội","example":"Victim-offender mediation is voluntary and not suitable for every case.","synonyms":["restorative mediation"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Criminal Justice & Rehabilitation","word":"criminogenic need","meaning":"a changeable factor linked to a person's risk of committing crime","translation":"nhu cầu nguy cơ tội phạm","example":"Treatment programmes often target criminogenic needs such as substance abuse.","synonyms":["crime-related risk factor"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Criminal Justice & Rehabilitation","word":"risk assessment tool","meaning":"a structured method for estimating the likelihood of future offending or harm","translation":"công cụ đánh giá rủi ro","example":"Risk-assessment tools should be tested for bias and accuracy.","synonyms":["risk instrument"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Criminal Justice & Rehabilitation","word":"reoffending rate","meaning":"the proportion of offenders who commit another crime","translation":"tỷ lệ tái phạm","example":"Employment support may reduce the reoffending rate.","synonyms":["recidivism rate"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Criminal Justice & Rehabilitation","word":"desistance from crime","meaning":"the long-term process of stopping criminal behaviour","translation":"quá trình chấm dứt phạm tội","example":"Stable relationships and work can support desistance from crime.","synonyms":["criminal desistance"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Criminal Justice & Rehabilitation","word":"community supervision","meaning":"monitoring and support of offenders serving sentences outside prison","translation":"giám sát cộng đồng","example":"Community supervision can include regular reporting and treatment.","synonyms":["probation supervision"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Criminal Justice & Rehabilitation","word":"alternatives to incarceration","meaning":"punishments or interventions used instead of imprisonment","translation":"các biện pháp thay thế giam giữ","example":"Alternatives to incarceration may reduce prison overcrowding.","synonyms":["non-prison sanctions"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Criminal Justice & Rehabilitation","word":"criminalisation","meaning":"the process of making a behaviour illegal","translation":"hình sự hóa","example":"Policy makers debate whether criminalisation is appropriate for some drug offences.","synonyms":["making illegal"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Criminal Justice & Rehabilitation","word":"decriminalisation","meaning":"the removal or reduction of criminal penalties for an activity","translation":"phi hình sự hóa","example":"Decriminalisation does not necessarily mean an activity is unregulated.","synonyms":["removal of criminal penalties"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Criminal Justice & Rehabilitation","word":"procedural fairness","meaning":"the perception and practice of fair processes in legal decision-making","translation":"công bằng thủ tục","example":"Procedural fairness can increase public trust in police and courts.","synonyms":["procedural justice"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Criminal Justice & Rehabilitation","word":"access to justice","meaning":"the ability of people to obtain fair legal help and remedies","translation":"khả năng tiếp cận công lý","example":"High legal costs can restrict access to justice.","synonyms":["legal access"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Criminal Justice & Rehabilitation","word":"legal representation","meaning":"professional legal assistance provided to a person in a case","translation":"đại diện pháp lý","example":"Defendants should have access to competent legal representation.","synonyms":["legal counsel"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Criminal Justice & Rehabilitation","word":"case backlog","meaning":"a large number of unresolved legal cases waiting to be processed","translation":"tồn đọng vụ án","example":"A severe case backlog can delay trials for years.","synonyms":["court backlog"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Criminal Justice & Rehabilitation","word":"prison conditions","meaning":"the physical and social conditions experienced by prisoners","translation":"điều kiện nhà tù","example":"Poor prison conditions can undermine rehabilitation.","synonyms":["detention conditions"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Criminal Justice & Rehabilitation","word":"rehabilitative approach","meaning":"a justice philosophy focused on changing behaviour and reducing future offending","translation":"cách tiếp cận phục hồi","example":"A rehabilitative approach emphasises education and treatment.","synonyms":["rehabilitation-focused model"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Criminal Justice & Rehabilitation","word":"punitive approach","meaning":"a justice philosophy emphasising punishment and deterrence","translation":"cách tiếp cận trừng phạt","example":"A purely punitive approach may do little to address causes of crime.","synonyms":["punishment-focused model"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Criminal Justice & Rehabilitation","word":"community reintegration","meaning":"the process by which former offenders rebuild lawful lives in society","translation":"tái hòa nhập cộng đồng","example":"Community reintegration depends on housing, work and social acceptance.","synonyms":["social reintegration"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Urban Planning & Sustainable Cities","word":"urban resilience","meaning":"the capacity of a city to withstand and recover from shocks","translation":"khả năng chống chịu đô thị","example":"Urban resilience planning must address heat, floods and infrastructure failure.","synonyms":["city resilience"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Urban Planning & Sustainable Cities","word":"climate-resilient city","meaning":"a city designed to cope with present and future climate risks","translation":"thành phố chống chịu khí hậu","example":"Green infrastructure is central to a climate-resilient city.","synonyms":["resilient urban area"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Urban Planning & Sustainable Cities","word":"green infrastructure","meaning":"a network of natural and semi-natural spaces providing environmental benefits","translation":"hạ tầng xanh","example":"Green infrastructure can reduce flooding and urban heat.","synonyms":["nature-based infrastructure"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Urban Planning & Sustainable Cities","word":"blue-green infrastructure","meaning":"integrated water and vegetation systems used in urban design","translation":"hạ tầng xanh-lam","example":"Blue-green infrastructure can manage stormwater while improving public space.","synonyms":["water-and-green infrastructure"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Urban Planning & Sustainable Cities","word":"urban heat island","meaning":"the tendency for built-up areas to be warmer than surrounding rural areas","translation":"đảo nhiệt đô thị","example":"Trees and reflective roofs can reduce the urban heat-island effect.","synonyms":["urban heat effect"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Urban Planning & Sustainable Cities","word":"stormwater management","meaning":"the control and treatment of rainwater runoff in developed areas","translation":"quản lý nước mưa","example":"Permeable surfaces improve urban stormwater management.","synonyms":["rainwater management"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Urban Planning & Sustainable Cities","word":"permeable surface","meaning":"a surface that allows water to pass into the ground","translation":"bề mặt thấm nước","example":"Permeable surfaces can reduce flash flooding.","synonyms":["porous surface"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Urban Planning & Sustainable Cities","word":"green roof","meaning":"a roof partly covered with vegetation","translation":"mái xanh","example":"Green roofs improve insulation and absorb rainwater.","synonyms":["vegetated roof"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Urban Planning & Sustainable Cities","word":"urban canopy","meaning":"the layer of tree cover across a city","translation":"tán cây đô thị","example":"Expanding the urban canopy can lower summer temperatures.","synonyms":["tree canopy"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Urban Planning & Sustainable Cities","word":"public-realm design","meaning":"the planning and design of streets, squares and shared urban spaces","translation":"thiết kế không gian công cộng","example":"Good public-realm design encourages walking and social interaction.","synonyms":["public-space design"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Urban Planning & Sustainable Cities","word":"urban morphology","meaning":"the physical form and structure of a city","translation":"hình thái đô thị","example":"Urban morphology influences travel behaviour and energy use.","synonyms":["city form"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Urban Planning & Sustainable Cities","word":"land-use planning","meaning":"the process of deciding how land should be developed or protected","translation":"quy hoạch sử dụng đất","example":"Land-use planning can limit development in flood-prone zones.","synonyms":["spatial planning"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Urban Planning & Sustainable Cities","word":"zoning reform","meaning":"changes to rules controlling what can be built in different areas","translation":"cải cách phân vùng","example":"Zoning reform may allow more housing near transport hubs.","synonyms":["planning reform"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Urban Planning & Sustainable Cities","word":"density bonus","meaning":"permission for extra development in exchange for public benefits","translation":"ưu đãi mật độ xây dựng","example":"A density bonus can encourage developers to provide affordable housing.","synonyms":["development incentive"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Urban Planning & Sustainable Cities","word":"mixed-income housing","meaning":"housing designed for residents with different income levels","translation":"nhà ở đa thu nhập","example":"Mixed-income housing can reduce residential segregation.","synonyms":["socially mixed housing"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Urban Planning & Sustainable Cities","word":"urban segregation","meaning":"the spatial separation of social or economic groups within a city","translation":"phân tách đô thị","example":"High housing costs can intensify urban segregation.","synonyms":["residential segregation"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Urban Planning & Sustainable Cities","word":"spatial inequality","meaning":"unequal access to opportunities and services across different areas","translation":"bất bình đẳng không gian","example":"Poor transport links can reinforce spatial inequality.","synonyms":["geographic inequality"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Urban Planning & Sustainable Cities","word":"transit accessibility","meaning":"the ease of reaching destinations using public transport","translation":"khả năng tiếp cận giao thông công cộng","example":"Transit accessibility strongly affects access to employment.","synonyms":["public-transport accessibility"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Urban Planning & Sustainable Cities","word":"first-mile connection","meaning":"the initial part of a journey connecting a person to main public transport","translation":"kết nối chặng đầu","example":"Safe cycling can improve first-mile connections to rail stations.","synonyms":["first-leg connection"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Urban Planning & Sustainable Cities","word":"last-mile connection","meaning":"the final part of a journey from a transport hub to the destination","translation":"kết nối chặng cuối","example":"Shared bikes can solve last-mile connection problems.","synonyms":["final-leg connection"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Urban Planning & Sustainable Cities","word":"complete street","meaning":"a street designed safely for pedestrians, cyclists, transit and cars","translation":"đường phố hoàn chỉnh đa phương thức","example":"Complete-street policies can improve mobility for non-drivers.","synonyms":["multimodal street"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Urban Planning & Sustainable Cities","word":"active travel","meaning":"walking, cycling or other travel involving physical activity","translation":"di chuyển chủ động","example":"Cities can promote active travel through safer streets.","synonyms":["active transport"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Urban Planning & Sustainable Cities","word":"car dependency","meaning":"a situation in which daily life strongly depends on private cars","translation":"sự phụ thuộc vào ô tô","example":"Low-density development often increases car dependency.","synonyms":["automobile dependence"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Urban Planning & Sustainable Cities","word":"urban mobility","meaning":"the movement of people and goods within cities","translation":"di chuyển đô thị","example":"Digital ticketing can improve urban mobility.","synonyms":["city transport movement"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Urban Planning & Sustainable Cities","word":"housing densification","meaning":"the process of increasing the number of homes in existing urban areas","translation":"tăng mật độ nhà ở","example":"Housing densification can reduce pressure to build on farmland.","synonyms":["residential intensification"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Urban Planning & Sustainable Cities","word":"brownfield redevelopment","meaning":"the reuse of previously developed or contaminated urban land","translation":"tái phát triển đất đã sử dụng","example":"Brownfield redevelopment can provide housing without expanding city boundaries.","synonyms":["land recycling"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Urban Planning & Sustainable Cities","word":"urban regeneration scheme","meaning":"a coordinated project to renew a declining urban area","translation":"chương trình tái thiết đô thị","example":"An urban-regeneration scheme should avoid displacing long-term residents.","synonyms":["renewal programme"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Urban Planning & Sustainable Cities","word":"gentrification pressure","meaning":"economic and social pressure that raises costs and displaces lower-income residents","translation":"áp lực gentrification","example":"New transport links can create gentrification pressure in nearby districts.","synonyms":["displacement pressure"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Urban Planning & Sustainable Cities","word":"place-making","meaning":"the process of creating attractive, meaningful and usable public places","translation":"kiến tạo không gian","example":"Community-led place-making can strengthen local identity.","synonyms":["public-space creation"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Urban Planning & Sustainable Cities","word":"urban sustainability","meaning":"the ability of cities to meet needs while limiting environmental and social harm","translation":"tính bền vững đô thị","example":"Urban sustainability depends on housing, transport, energy and equity.","synonyms":["sustainable urbanism"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Globalisation & International Relations","word":"global economic integration","meaning":"the growing connection of national economies through trade, finance and production","translation":"hội nhập kinh tế toàn cầu","example":"Global economic integration has created complex cross-border supply chains.","synonyms":["economic globalisation"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Globalisation & International Relations","word":"trade liberalisation","meaning":"the reduction of barriers such as tariffs and quotas on international trade","translation":"tự do hóa thương mại","example":"Trade liberalisation can lower prices but also increase competitive pressure.","synonyms":["opening trade"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Globalisation & International Relations","word":"trade barrier","meaning":"a policy or rule that restricts international trade","translation":"rào cản thương mại","example":"Tariffs are a common form of trade barrier.","synonyms":["trade restriction"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Globalisation & International Relations","word":"tariff","meaning":"a tax imposed on imported goods","translation":"thuế quan","example":"Higher tariffs can make imported products more expensive.","synonyms":["import duty"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Globalisation & International Relations","word":"non-tariff barrier","meaning":"a regulation or requirement that restricts trade without using a tariff","translation":"rào cản phi thuế quan","example":"Product standards can function as non-tariff barriers.","synonyms":["regulatory trade barrier"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Globalisation & International Relations","word":"supply-chain diversification","meaning":"the strategy of using multiple suppliers or regions to reduce disruption risk","translation":"đa dạng hóa chuỗi cung ứng","example":"Firms are pursuing supply-chain diversification after recent disruptions.","synonyms":["supplier diversification"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Globalisation & International Relations","word":"supply-chain dependency","meaning":"reliance on particular suppliers, countries or routes","translation":"sự phụ thuộc chuỗi cung ứng","example":"Heavy supply-chain dependency can create strategic risk.","synonyms":["supplier dependence"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Globalisation & International Relations","word":"nearshoring","meaning":"moving production or services to a nearby country","translation":"chuyển sản xuất về nước lân cận","example":"Nearshoring can shorten supply chains and reduce transport risk.","synonyms":["regional relocation"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Globalisation & International Relations","word":"friend-shoring","meaning":"moving supply chains towards politically allied or trusted countries","translation":"chuyển chuỗi cung ứng sang nước đồng minh","example":"Friend-shoring may improve security but reduce efficiency.","synonyms":["trusted-country sourcing"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Globalisation & International Relations","word":"trade diversification","meaning":"expanding trade across more products or partner countries","translation":"đa dạng hóa thương mại","example":"Trade diversification can reduce dependence on a single export market.","synonyms":["market diversification"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Globalisation & International Relations","word":"economic diplomacy","meaning":"the use of diplomatic relationships to pursue economic interests","translation":"ngoại giao kinh tế","example":"Economic diplomacy can support trade and investment agreements.","synonyms":["commercial diplomacy"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Globalisation & International Relations","word":"bilateral relation","meaning":"a relationship between two countries","translation":"quan hệ song phương","example":"Bilateral relations improved after the new trade agreement.","synonyms":["two-country relationship"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Globalisation & International Relations","word":"multilateral institution","meaning":"an organisation through which several countries cooperate","translation":"thể chế đa phương","example":"Multilateral institutions help coordinate responses to global crises.","synonyms":["international institution"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Globalisation & International Relations","word":"rules-based order","meaning":"an international system in which states are expected to follow agreed rules and institutions","translation":"trật tự dựa trên luật lệ","example":"Smaller states often support a predictable rules-based order.","synonyms":["rule-governed system"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Globalisation & International Relations","word":"strategic alliance","meaning":"a formal or informal partnership created to pursue shared strategic goals","translation":"liên minh chiến lược","example":"Strategic alliances influence security and economic policy.","synonyms":["strategic partnership"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Globalisation & International Relations","word":"regional bloc","meaning":"a group of neighbouring countries cooperating economically or politically","translation":"khối khu vực","example":"Regional blocs can negotiate trade agreements collectively.","synonyms":["regional grouping"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Globalisation & International Relations","word":"cross-border investment","meaning":"investment made by individuals or firms in another country","translation":"đầu tư xuyên biên giới","example":"Stable institutions attract cross-border investment.","synonyms":["international investment"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Globalisation & International Relations","word":"capital flow","meaning":"the movement of money for investment between countries or markets","translation":"dòng vốn","example":"Sudden capital outflows can create financial instability.","synonyms":["financial flow"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Globalisation & International Relations","word":"currency volatility","meaning":"rapid or unpredictable changes in exchange rates","translation":"biến động tiền tệ","example":"Currency volatility creates uncertainty for exporters.","synonyms":["exchange-rate volatility"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Globalisation & International Relations","word":"geoeconomic competition","meaning":"competition between states using economic tools for strategic influence","translation":"cạnh tranh địa kinh tế","example":"Technology restrictions have become part of geoeconomic competition.","synonyms":["strategic economic rivalry"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Globalisation & International Relations","word":"economic coercion","meaning":"the use of trade, finance or sanctions to pressure another state","translation":"cưỡng ép kinh tế","example":"Economic coercion can damage both target and sender economies.","synonyms":["financial pressure"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Globalisation & International Relations","word":"sanctions regime","meaning":"a structured set of economic or political restrictions imposed on a target","translation":"chế độ trừng phạt","example":"Sanctions regimes often include financial and trade restrictions.","synonyms":["sanctions framework"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Globalisation & International Relations","word":"humanitarian exemption","meaning":"an exception allowing essential humanitarian activity despite restrictions","translation":"miễn trừ nhân đạo","example":"Humanitarian exemptions can reduce the impact of sanctions on civilians.","synonyms":["aid exemption"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Globalisation & International Relations","word":"diplomatic engagement","meaning":"formal communication and negotiation between governments","translation":"can dự ngoại giao","example":"Diplomatic engagement can prevent disputes from escalating.","synonyms":["diplomatic dialogue"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Globalisation & International Relations","word":"conflict de-escalation","meaning":"actions that reduce tension or the risk of violence","translation":"hạ nhiệt xung đột","example":"Regional organisations can support conflict de-escalation.","synonyms":["tension reduction"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Globalisation & International Relations","word":"international norm","meaning":"a widely accepted expectation about state or international behaviour","translation":"chuẩn mực quốc tế","example":"International norms influence how governments respond to crises.","synonyms":["global norm"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Globalisation & International Relations","word":"cross-border cooperation","meaning":"joint action by institutions or governments in different countries","translation":"hợp tác xuyên biên giới","example":"Cross-border cooperation is essential for managing shared rivers.","synonyms":["international cooperation"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Globalisation & International Relations","word":"transnational challenge","meaning":"a problem that crosses national boundaries and requires cooperation","translation":"thách thức xuyên quốc gia","example":"Climate change is a major transnational challenge.","synonyms":["cross-border problem"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Globalisation & International Relations","word":"global public good","meaning":"a benefit whose advantages extend across countries and cannot easily exclude users","translation":"hàng hóa công toàn cầu","example":"Climate stability is often described as a global public good.","synonyms":["international public good"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Globalisation & International Relations","word":"global interdependence","meaning":"mutual dependence between countries, economies or societies","translation":"sự phụ thuộc lẫn nhau toàn cầu","example":"Global interdependence makes distant shocks more economically significant.","synonyms":["international interdependence"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Education Policy & Lifelong Learning","word":"education access","meaning":"the ability of people to enter and participate in education","translation":"khả năng tiếp cận giáo dục","example":"Rural transport can affect education access.","synonyms":["access to schooling"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Education Policy & Lifelong Learning","word":"educational disadvantage","meaning":"barriers that make educational success less likely for some learners","translation":"bất lợi giáo dục","example":"Poverty is a major source of educational disadvantage.","synonyms":["learning disadvantage"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Education Policy & Lifelong Learning","word":"achievement gap","meaning":"a persistent difference in educational outcomes between groups","translation":"khoảng cách thành tích","example":"Early support can reduce the achievement gap.","synonyms":["attainment gap"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Education Policy & Lifelong Learning","word":"learning gap","meaning":"a difference between expected and actual knowledge or skills","translation":"khoảng cách học tập","example":"School closures widened learning gaps for some pupils.","synonyms":["educational gap"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Education Policy & Lifelong Learning","word":"school readiness","meaning":"the skills and development children need to begin formal education successfully","translation":"mức độ sẵn sàng đi học","example":"High-quality preschool can improve school readiness.","synonyms":["readiness for school"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Education Policy & Lifelong Learning","word":"early intervention","meaning":"support provided at an early stage to prevent problems becoming more severe","translation":"can thiệp sớm","example":"Early intervention can help children with learning difficulties.","synonyms":["early support"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Education Policy & Lifelong Learning","word":"education inequality","meaning":"unequal access, resources or outcomes within education","translation":"bất bình đẳng giáo dục","example":"Funding differences can reinforce education inequality.","synonyms":["educational disparity"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Education Policy & Lifelong Learning","word":"school funding formula","meaning":"a rule for allocating public money among schools","translation":"công thức phân bổ ngân sách trường học","example":"A school-funding formula can direct more resources to disadvantaged areas.","synonyms":["funding allocation rule"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Education Policy & Lifelong Learning","word":"per-pupil funding","meaning":"public education spending allocated according to the number of students","translation":"tài trợ theo đầu học sinh","example":"Per-pupil funding often differs between regions.","synonyms":["funding per student"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Education Policy & Lifelong Learning","word":"teacher quality","meaning":"the effectiveness, knowledge and skills of teachers","translation":"chất lượng giáo viên","example":"Teacher quality is one of several factors affecting learning outcomes.","synonyms":["instructional quality"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Education Policy & Lifelong Learning","word":"teacher development","meaning":"ongoing professional learning for educators","translation":"phát triển giáo viên","example":"Teacher development should include classroom practice and feedback.","synonyms":["professional development for teachers"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Education Policy & Lifelong Learning","word":"teacher workload","meaning":"the total amount of teaching, planning and administrative work teachers perform","translation":"khối lượng công việc giáo viên","example":"Excessive teacher workload can worsen staff retention.","synonyms":["educator workload"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Education Policy & Lifelong Learning","word":"teacher shortage","meaning":"a lack of qualified teachers relative to demand","translation":"thiếu giáo viên","example":"Rural schools often face persistent teacher shortages.","synonyms":["educator shortage"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Education Policy & Lifelong Learning","word":"school accountability","meaning":"the requirement for schools to explain and improve their performance","translation":"trách nhiệm giải trình trường học","example":"School accountability should consider more than exam scores.","synonyms":["institutional accountability"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Education Policy & Lifelong Learning","word":"high-stakes testing","meaning":"testing whose results have significant consequences for students or institutions","translation":"thi cử hệ quả cao","example":"High-stakes testing can narrow classroom teaching.","synonyms":["consequential testing"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Education Policy & Lifelong Learning","word":"assessment literacy","meaning":"understanding how to design, interpret and use educational assessment","translation":"năng lực đánh giá giáo dục","example":"Teachers need assessment literacy to use test results effectively.","synonyms":["testing literacy"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Education Policy & Lifelong Learning","word":"formative assessment","meaning":"assessment used during learning to guide improvement","translation":"đánh giá thường xuyên","example":"Formative assessment provides feedback before final grading.","synonyms":["assessment for learning"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Education Policy & Lifelong Learning","word":"summative assessment","meaning":"assessment used to judge achievement at the end of a course or period","translation":"đánh giá tổng kết","example":"Final examinations are a common form of summative assessment.","synonyms":["assessment of learning"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Education Policy & Lifelong Learning","word":"curriculum alignment","meaning":"the degree to which teaching, assessment and learning goals are consistent","translation":"sự liên kết chương trình","example":"Curriculum alignment helps ensure tests reflect what students were taught.","synonyms":["instructional alignment"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Education Policy & Lifelong Learning","word":"curriculum breadth","meaning":"the range of subjects and experiences included in a curriculum","translation":"độ rộng chương trình","example":"Schools must balance curriculum breadth with depth.","synonyms":["breadth of curriculum"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Education Policy & Lifelong Learning","word":"vocational pathway","meaning":"an education route focused on occupational and technical skills","translation":"lộ trình nghề nghiệp","example":"A strong vocational pathway can provide alternatives to university.","synonyms":["technical pathway"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Education Policy & Lifelong Learning","word":"academic pathway","meaning":"an education route focused on general or university-preparatory study","translation":"lộ trình học thuật","example":"Students should be able to move between academic and vocational pathways.","synonyms":["university-preparation route"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Education Policy & Lifelong Learning","word":"credential inflation","meaning":"a rise in qualification requirements for jobs without equivalent changes in tasks","translation":"lạm phát bằng cấp","example":"Credential inflation can make entry-level jobs harder to access.","synonyms":["degree inflation"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Education Policy & Lifelong Learning","word":"micro-credential","meaning":"a short certified course demonstrating a specific skill or competency","translation":"chứng chỉ vi mô","example":"Micro-credentials are increasingly used for professional upskilling.","synonyms":["short-form credential"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Education Policy & Lifelong Learning","word":"adult education","meaning":"organised learning for adults outside traditional initial schooling","translation":"giáo dục người lớn","example":"Adult education can support career changes later in life.","synonyms":["continuing education"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Education Policy & Lifelong Learning","word":"continuing professional education","meaning":"ongoing structured learning undertaken after entering a profession","translation":"đào tạo chuyên môn liên tục","example":"Healthcare workers require continuing professional education.","synonyms":["professional continuing education"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Education Policy & Lifelong Learning","word":"recognition of prior learning","meaning":"formal acknowledgement of skills gained through previous work or study","translation":"công nhận học tập trước đó","example":"Recognition of prior learning can shorten retraining programmes.","synonyms":["RPL"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Education Policy & Lifelong Learning","word":"learning ecosystem","meaning":"the network of institutions, tools and people supporting learning","translation":"hệ sinh thái học tập","example":"Digital platforms have expanded the modern learning ecosystem.","synonyms":["education ecosystem"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Education Policy & Lifelong Learning","word":"education-to-work transition","meaning":"the movement from formal study into employment","translation":"chuyển tiếp từ học sang làm","example":"Internships can ease the education-to-work transition.","synonyms":["school-to-work transition"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Education Policy & Lifelong Learning","word":"lifelong-learning culture","meaning":"a social environment in which continued learning across adulthood is normal","translation":"văn hóa học tập suốt đời","example":"A lifelong-learning culture helps workers adapt to technological change.","synonyms":["continuous-learning culture"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Media Literacy & Misinformation","word":"information ecosystem","meaning":"the interconnected system through which information is created, distributed and consumed","translation":"hệ sinh thái thông tin","example":"Social platforms have transformed the information ecosystem.","synonyms":["media ecosystem"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Media Literacy & Misinformation","word":"information disorder","meaning":"the broad problem of false, misleading or harmful information circulating publicly","translation":"rối loạn thông tin","example":"Information disorder includes misinformation and deliberate manipulation.","synonyms":["information pollution"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Media Literacy & Misinformation","word":"false narrative","meaning":"an inaccurate story or interpretation repeatedly presented as true","translation":"tường thuật sai lệch","example":"False narratives can spread rapidly during crises.","synonyms":["misleading narrative"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Media Literacy & Misinformation","word":"manipulated content","meaning":"media that has been altered to create a misleading impression","translation":"nội dung bị thao túng","example":"Manipulated content is increasingly difficult to identify visually.","synonyms":["altered media"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Media Literacy & Misinformation","word":"deepfake","meaning":"synthetic audio or video that realistically imitates a real person","translation":"deepfake","example":"Deepfakes create new challenges for election integrity and fraud prevention.","synonyms":["synthetic media"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Media Literacy & Misinformation","word":"synthetic media","meaning":"audio, images or video generated or altered using artificial intelligence","translation":"truyền thông tổng hợp","example":"Synthetic media can be creative but also deceptive.","synonyms":["AI-generated media"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Media Literacy & Misinformation","word":"source verification","meaning":"the process of checking the origin and reliability of information","translation":"xác minh nguồn","example":"Source verification should be routine before sharing breaking news.","synonyms":["checking sources"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Media Literacy & Misinformation","word":"cross-check a claim","meaning":"to compare a claim against independent sources or evidence","translation":"đối chiếu tuyên bố","example":"Readers should cross-check a claim before accepting it as fact.","synonyms":["verify a claim"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Media Literacy & Misinformation","word":"primary source","meaning":"original evidence or information produced directly by participants or institutions","translation":"nguồn sơ cấp","example":"A government dataset can serve as a primary source.","synonyms":["original source"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Media Literacy & Misinformation","word":"secondary source","meaning":"analysis or reporting based on primary information","translation":"nguồn thứ cấp","example":"A newspaper article is usually a secondary source.","synonyms":["interpreted source"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Media Literacy & Misinformation","word":"source provenance","meaning":"the documented origin and history of information or data","translation":"nguồn gốc thông tin","example":"Digital tools may help users check source provenance.","synonyms":["information origin"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Media Literacy & Misinformation","word":"editorial standard","meaning":"a professional rule guiding accuracy, fairness and publication","translation":"tiêu chuẩn biên tập","example":"Strong editorial standards reduce avoidable reporting errors.","synonyms":["journalistic standard"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Media Literacy & Misinformation","word":"editorial oversight","meaning":"review and supervision of content before or after publication","translation":"giám sát biên tập","example":"Editorial oversight is weaker on many user-generated platforms.","synonyms":["editorial review"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Media Literacy & Misinformation","word":"news literacy","meaning":"the ability to understand, evaluate and responsibly use news media","translation":"năng lực hiểu tin tức","example":"News literacy helps students distinguish reporting from opinion.","synonyms":["media literacy for news"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Media Literacy & Misinformation","word":"critical media consumption","meaning":"careful evaluation of media rather than passive acceptance","translation":"tiếp nhận truyền thông có phê phán","example":"Critical media consumption is essential in a fragmented information environment.","synonyms":["critical media use"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Media Literacy & Misinformation","word":"confirmation bias","meaning":"the tendency to favour information that supports existing beliefs","translation":"thiên kiến xác nhận","example":"Confirmation bias can make users more vulnerable to misleading content.","synonyms":["belief-confirming bias"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Media Literacy & Misinformation","word":"motivated reasoning","meaning":"the tendency to interpret evidence in ways that support desired conclusions","translation":"suy luận có động cơ","example":"Motivated reasoning can shape political information processing.","synonyms":["biased reasoning"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Media Literacy & Misinformation","word":"selective exposure","meaning":"the tendency to choose information that matches existing preferences","translation":"tiếp xúc có chọn lọc","example":"Recommendation systems may strengthen selective exposure.","synonyms":["preference-based exposure"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Media Literacy & Misinformation","word":"algorithmic amplification","meaning":"the increased visibility of content because platform algorithms promote it","translation":"khuếch đại thuật toán","example":"Algorithmic amplification can reward emotionally provocative content.","synonyms":["platform amplification"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Media Literacy & Misinformation","word":"engagement-based ranking","meaning":"ordering content according to predicted likes, clicks or interactions","translation":"xếp hạng dựa trên tương tác","example":"Engagement-based ranking may prioritise sensational material.","synonyms":["interaction-driven ranking"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Media Literacy & Misinformation","word":"content moderation policy","meaning":"rules determining what user-generated content is restricted or removed","translation":"chính sách kiểm duyệt nội dung","example":"Content-moderation policies must balance safety and expression.","synonyms":["platform moderation rules"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Media Literacy & Misinformation","word":"platform accountability","meaning":"responsibility of digital platforms for their systems and social effects","translation":"trách nhiệm giải trình nền tảng","example":"Lawmakers are debating stronger platform accountability.","synonyms":["digital-platform responsibility"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Media Literacy & Misinformation","word":"information integrity","meaning":"the reliability and trustworthiness of information systems and content","translation":"tính toàn vẹn thông tin","example":"Election authorities increasingly focus on information integrity.","synonyms":["trustworthy information environment"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Media Literacy & Misinformation","word":"credible journalism","meaning":"journalism based on verification, professional standards and transparent sourcing","translation":"báo chí đáng tin cậy","example":"Credible journalism remains important during fast-moving emergencies.","synonyms":["reliable reporting"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Media Literacy & Misinformation","word":"misinformation correction","meaning":"an intervention that corrects false or misleading claims","translation":"đính chính thông tin sai","example":"Misinformation corrections are most effective when they are clear and timely.","synonyms":["fact correction"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Media Literacy & Misinformation","word":"prebunking","meaning":"warning people about manipulation techniques before they encounter false information","translation":"phòng ngừa tin giả trước","example":"Prebunking may improve resistance to common misinformation tactics.","synonyms":["inoculation against misinformation"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Media Literacy & Misinformation","word":"digital verification","meaning":"the use of digital tools and methods to authenticate online content","translation":"xác minh kỹ thuật số","example":"Journalists use digital verification to assess images from social media.","synonyms":["online verification"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Media Literacy & Misinformation","word":"media pluralism","meaning":"the presence of diverse independent media voices and ownership","translation":"đa nguyên truyền thông","example":"Media pluralism reduces dependence on a single information source.","synonyms":["media diversity"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Media Literacy & Misinformation","word":"information asymmetry","meaning":"a situation in which one side has substantially more or better information than another","translation":"bất cân xứng thông tin","example":"Information asymmetry can make consumers vulnerable to misleading claims.","synonyms":["unequal information"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Media Literacy & Misinformation","word":"attention economy","meaning":"an economic system in which platforms compete for users' limited attention","translation":"nền kinh tế chú ý","example":"The attention economy rewards content that keeps users engaged.","synonyms":["attention-based market"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Identity & Cultural Change","word":"cultural identity","meaning":"a sense of belonging based on shared culture, language or traditions","translation":"bản sắc văn hóa","example":"Migration and media can reshape cultural identity over time.","synonyms":["cultural belonging"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Identity & Cultural Change","word":"hybrid identity","meaning":"an identity combining elements from more than one culture or social group","translation":"bản sắc lai ghép","example":"Children of migrants may develop a hybrid identity.","synonyms":["mixed identity"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Identity & Cultural Change","word":"diasporic identity","meaning":"a sense of identity shaped by living outside an ancestral homeland","translation":"bản sắc cộng đồng hải ngoại","example":"Diasporic identity can connect people to both local and ancestral cultures.","synonyms":["diaspora identity"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Identity & Cultural Change","word":"cultural belonging","meaning":"the feeling of being accepted as part of a cultural community","translation":"cảm giác thuộc về văn hóa","example":"Language often plays a central role in cultural belonging.","synonyms":["sense of belonging"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Identity & Cultural Change","word":"collective memory","meaning":"shared understandings and memories of the past within a group","translation":"ký ức tập thể","example":"Museums contribute to collective memory by preserving historical narratives.","synonyms":["shared memory"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Identity & Cultural Change","word":"cultural memory","meaning":"the way societies remember and transmit significant past experiences","translation":"ký ức văn hóa","example":"Festivals can serve as a form of cultural memory.","synonyms":["social memory"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Identity & Cultural Change","word":"cultural transmission","meaning":"the passing of beliefs, practices and knowledge between generations","translation":"truyền tải văn hóa","example":"Family life remains important for cultural transmission.","synonyms":["intergenerational transmission"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Identity & Cultural Change","word":"intergenerational transmission","meaning":"the passing of language, values or practices from older to younger generations","translation":"truyền giao liên thế hệ","example":"Migration can weaken intergenerational transmission of minority languages.","synonyms":["generational transmission"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Identity & Cultural Change","word":"language shift","meaning":"the gradual replacement of one language by another within a community","translation":"chuyển dịch ngôn ngữ","example":"Urbanisation may accelerate language shift among younger speakers.","synonyms":["linguistic shift"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Identity & Cultural Change","word":"language maintenance","meaning":"efforts or patterns that keep a language actively used across generations","translation":"duy trì ngôn ngữ","example":"Community schools can support language maintenance.","synonyms":["linguistic preservation"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Identity & Cultural Change","word":"minority language","meaning":"a language spoken by a smaller group within a society","translation":"ngôn ngữ thiểu số","example":"Minority languages often require institutional support to survive.","synonyms":["regional language"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Identity & Cultural Change","word":"cultural mainstream","meaning":"the dominant cultural patterns and institutions within a society","translation":"dòng văn hóa chủ đạo","example":"Minority artists can challenge assumptions within the cultural mainstream.","synonyms":["dominant culture"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Identity & Cultural Change","word":"cultural marginalisation","meaning":"the process of pushing a culture or group to the edges of social life","translation":"sự gạt ra bên lề văn hóa","example":"Cultural marginalisation can reduce participation and visibility.","synonyms":["social exclusion of culture"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Identity & Cultural Change","word":"cultural representation","meaning":"the portrayal or presence of cultural groups in media and institutions","translation":"đại diện văn hóa","example":"More accurate cultural representation can reduce stereotypes.","synonyms":["representation of culture"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Identity & Cultural Change","word":"cultural stereotype","meaning":"a simplified and fixed belief about a cultural group","translation":"định kiến văn hóa","example":"Travel can challenge some cultural stereotypes.","synonyms":["cultural generalisation"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Identity & Cultural Change","word":"cultural sensitivity","meaning":"awareness and respect for differences in cultural norms and practices","translation":"sự nhạy cảm văn hóa","example":"Healthcare staff need cultural sensitivity when working with diverse patients.","synonyms":["intercultural awareness"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Identity & Cultural Change","word":"cultural competence","meaning":"the ability to interact effectively across cultural differences","translation":"năng lực liên văn hóa","example":"Cultural competence is increasingly valued in global workplaces.","synonyms":["intercultural competence"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Identity & Cultural Change","word":"cultural adaptation strategy","meaning":"a deliberate approach to adjusting while maintaining parts of one's identity","translation":"chiến lược thích nghi văn hóa","example":"Different migrants adopt different cultural-adaptation strategies.","synonyms":["acculturation strategy"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Identity & Cultural Change","word":"acculturation","meaning":"the process of cultural change that occurs through sustained contact between groups","translation":"tiếp biến văn hóa","example":"Acculturation does not necessarily require complete assimilation.","synonyms":["cultural adjustment"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Identity & Cultural Change","word":"cultural assimilation pressure","meaning":"social pressure on minorities to adopt dominant cultural norms","translation":"áp lực đồng hóa văn hóa","example":"Assimilation pressure can create conflict over identity.","synonyms":["pressure to assimilate"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Identity & Cultural Change","word":"social belonging","meaning":"the feeling of being accepted and connected within a community","translation":"cảm giác thuộc về xã hội","example":"Social belonging is important for mental well-being.","synonyms":["community belonging"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Identity & Cultural Change","word":"identity negotiation","meaning":"the process of adapting or expressing identity across different social contexts","translation":"thương lượng bản sắc","example":"Bilingual speakers may engage in identity negotiation across settings.","synonyms":["negotiation of identity"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Identity & Cultural Change","word":"identity politics","meaning":"political activity organised around shared social identities or group experiences","translation":"chính trị bản sắc","example":"Identity politics can increase representation but also intensify division.","synonyms":["group-based politics"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Identity & Cultural Change","word":"cultural pluralism","meaning":"a model in which multiple cultural groups coexist while retaining distinct identities","translation":"đa nguyên văn hóa","example":"Cultural pluralism differs from full assimilation.","synonyms":["multicultural pluralism"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Identity & Cultural Change","word":"cultural homogenisation pressure","meaning":"forces that make cultures increasingly similar","translation":"áp lực đồng nhất văn hóa","example":"Global brands are often criticised for cultural homogenisation pressure.","synonyms":["pressure towards sameness"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Identity & Cultural Change","word":"cultural revival","meaning":"a renewed interest in previously declining cultural practices or languages","translation":"phục hưng văn hóa","example":"Digital media has supported a cultural revival among some indigenous groups.","synonyms":["cultural resurgence"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Identity & Cultural Change","word":"tradition reinvention","meaning":"the adaptation or recreation of traditions for contemporary contexts","translation":"tái tạo truyền thống","example":"Tourism can encourage both preservation and reinvention of tradition.","synonyms":["modernised tradition"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Identity & Cultural Change","word":"heritage continuity across generations","meaning":"the sustained transmission of cultural practices and identity between generations","translation":"sự tiếp nối di sản qua các thế hệ","example":"Community institutions help maintain heritage continuity across generations.","synonyms":["intergenerational continuity"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Identity & Cultural Change","word":"identity formation","meaning":"the process through which individuals or groups develop a sense of who they are","translation":"hình thành bản sắc","example":"Education and peer groups both influence identity formation.","synonyms":["development of identity"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Demography & Migration Policy","word":"population projection","meaning":"an estimate of future population size or structure","translation":"dự báo dân số","example":"Population projections help governments plan schools and pensions.","synonyms":["demographic forecast"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Demography & Migration Policy","word":"age structure","meaning":"the distribution of a population across age groups","translation":"cơ cấu tuổi","example":"Migration can substantially change a country's age structure.","synonyms":["population age profile"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Demography & Migration Policy","word":"population pyramid","meaning":"a chart showing population by age and sex","translation":"tháp dân số","example":"A narrow base in a population pyramid indicates low fertility.","synonyms":["age-sex pyramid"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Demography & Migration Policy","word":"replacement fertility","meaning":"the fertility level needed for a population to replace itself over time","translation":"mức sinh thay thế","example":"Several countries now remain below replacement fertility.","synonyms":["replacement-level fertility"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Demography & Migration Policy","word":"natural population change","meaning":"population change caused by births and deaths rather than migration","translation":"biến động dân số tự nhiên","example":"Natural population change has turned negative in some ageing societies.","synonyms":["natural change"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Demography & Migration Policy","word":"net migration","meaning":"the difference between people entering and leaving a country","translation":"di cư ròng","example":"Positive net migration can offset population decline.","synonyms":["migration balance"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Demography & Migration Policy","word":"migration quota","meaning":"a limit on the number of migrants admitted under a policy","translation":"hạn ngạch di cư","example":"Migration quotas are often adjusted according to labour needs.","synonyms":["admission quota"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Demography & Migration Policy","word":"points-based migration","meaning":"a system selecting migrants according to criteria such as skills, age or language","translation":"di cư theo hệ thống điểm","example":"Points-based migration systems aim to attract workers with needed skills.","synonyms":["merit-based migration"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Demography & Migration Policy","word":"family reunification","meaning":"migration that allows people to join close relatives already living in a country","translation":"đoàn tụ gia đình","example":"Family reunification is a major route of legal migration.","synonyms":["family migration"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Demography & Migration Policy","word":"humanitarian migration","meaning":"migration permitted for people fleeing serious danger or persecution","translation":"di cư nhân đạo","example":"Humanitarian migration requires reception and integration services.","synonyms":["protection migration"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Demography & Migration Policy","word":"refugee resettlement","meaning":"the organised transfer of refugees to a country offering long-term protection","translation":"tái định cư người tị nạn","example":"Refugee resettlement programmes usually involve strict screening.","synonyms":["refugee relocation"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Demography & Migration Policy","word":"asylum system","meaning":"the institutions and procedures used to assess claims for international protection","translation":"hệ thống tị nạn","example":"A fair asylum system must make decisions efficiently and accurately.","synonyms":["refugee protection system"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Demography & Migration Policy","word":"irregular migration","meaning":"migration occurring outside the legal rules of entry or residence","translation":"di cư bất thường","example":"Irregular migration is often linked to dangerous travel routes.","synonyms":["unauthorised migration"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Demography & Migration Policy","word":"migration enforcement","meaning":"government actions used to implement immigration rules","translation":"thực thi chính sách di cư","example":"Migration enforcement can be controversial when families are affected.","synonyms":["immigration enforcement"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Demography & Migration Policy","word":"border management","meaning":"the administration and control of people and goods crossing national borders","translation":"quản lý biên giới","example":"Technology plays an increasing role in border management.","synonyms":["border control"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Demography & Migration Policy","word":"integration programme","meaning":"a programme helping migrants participate in social, economic and civic life","translation":"chương trình hội nhập","example":"Language classes are common within integration programmes.","synonyms":["settlement programme"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Demography & Migration Policy","word":"language requirement","meaning":"a rule requiring migrants or applicants to demonstrate language ability","translation":"yêu cầu ngôn ngữ","example":"Some citizenship processes include a language requirement.","synonyms":["linguistic requirement"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Demography & Migration Policy","word":"citizenship pathway","meaning":"the legal process through which a resident may become a citizen","translation":"lộ trình nhập quốc tịch","example":"Clear citizenship pathways can support long-term integration.","synonyms":["naturalisation route"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Demography & Migration Policy","word":"permanent residency","meaning":"legal permission to live indefinitely in a country without full citizenship","translation":"thường trú","example":"Skilled migrants may become eligible for permanent residency.","synonyms":["permanent residence"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Demography & Migration Policy","word":"temporary migration","meaning":"migration for a limited period, often for work or study","translation":"di cư tạm thời","example":"Temporary migration programmes can respond to seasonal labour shortages.","synonyms":["short-term migration"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Demography & Migration Policy","word":"circular migration","meaning":"repeated movement between a home country and a destination country","translation":"di cư luân chuyển","example":"Circular migration can support skills and income flows between countries.","synonyms":["repeat migration"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Demography & Migration Policy","word":"brain circulation","meaning":"the movement of skilled people between countries in ways that spread knowledge","translation":"luân chuyển chất xám","example":"Brain circulation can benefit both origin and destination countries.","synonyms":["skills circulation"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Demography & Migration Policy","word":"diaspora engagement","meaning":"policies or activities that connect a country with citizens and descendants abroad","translation":"gắn kết kiều bào","example":"Diaspora engagement can support investment and knowledge transfer.","synonyms":["diaspora policy"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Demography & Migration Policy","word":"remittance flow","meaning":"money sent by migrants to households or communities in their country of origin","translation":"dòng kiều hối","example":"Remittance flows provide important income in many developing economies.","synonyms":["money transfers"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Demography & Migration Policy","word":"migration governance","meaning":"the institutions and rules used to manage international migration","translation":"quản trị di cư","example":"Migration governance requires coordination across government agencies.","synonyms":["migration management"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Demography & Migration Policy","word":"integration outcome","meaning":"a measurable result of migrant participation in employment, education or society","translation":"kết quả hội nhập","example":"Employment rates are one indicator of integration outcomes.","synonyms":["settlement outcome"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Demography & Migration Policy","word":"migration selectivity","meaning":"the way migration policies or processes favour certain groups of people","translation":"tính chọn lọc di cư","example":"Skills-based systems create strong migration selectivity.","synonyms":["selective migration"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Demography & Migration Policy","word":"demographic dividend","meaning":"economic potential created when a population has a high share of working-age adults","translation":"lợi tức dân số","example":"Education and job creation are needed to realise a demographic dividend.","synonyms":["population dividend"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Demography & Migration Policy","word":"demographic ageing","meaning":"the long-term increase in the proportion of older people in a population","translation":"già hóa dân số","example":"Demographic ageing affects healthcare, pensions and labour supply.","synonyms":["population ageing"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Science Ethics & Research","word":"research reproducibility","meaning":"the ability to obtain consistent results when a study is repeated or reanalysed","translation":"khả năng tái lập nghiên cứu","example":"Concerns about research reproducibility have led to changes in scientific practice.","synonyms":["reproducibility"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Science Ethics & Research","word":"replication study","meaning":"a study designed to test whether earlier findings can be reproduced","translation":"nghiên cứu lặp lại","example":"Replication studies are important for assessing scientific reliability.","synonyms":["reproduction study"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Science Ethics & Research","word":"open science","meaning":"practices that make research methods, data and outputs more accessible","translation":"khoa học mở","example":"Open science can improve transparency and collaboration.","synonyms":["open research"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Science Ethics & Research","word":"open data","meaning":"research data made available for others to access and reuse","translation":"dữ liệu mở","example":"Open data allows independent researchers to test published claims.","synonyms":["public research data"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Science Ethics & Research","word":"pre-registration","meaning":"the public documentation of hypotheses and methods before data analysis","translation":"đăng ký trước nghiên cứu","example":"Pre-registration can reduce selective reporting.","synonyms":["study preregistration"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Science Ethics & Research","word":"publication bias","meaning":"the tendency for positive or significant findings to be published more often","translation":"thiên lệch công bố","example":"Publication bias can distort the scientific evidence base.","synonyms":["reporting bias"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Science Ethics & Research","word":"selective reporting","meaning":"the practice of reporting some results while omitting others","translation":"báo cáo chọn lọc","example":"Selective reporting can exaggerate apparent treatment effects.","synonyms":["outcome reporting bias"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Science Ethics & Research","word":"conflict-of-interest disclosure","meaning":"a statement revealing financial or personal interests relevant to research","translation":"công bố xung đột lợi ích","example":"Journals require conflict-of-interest disclosures from authors.","synonyms":["interest declaration"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Science Ethics & Research","word":"research funding bias","meaning":"distortion in research priorities or outcomes linked to funding sources","translation":"thiên lệch tài trợ nghiên cứu","example":"Strong safeguards are needed to limit research-funding bias.","synonyms":["sponsor bias"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Science Ethics & Research","word":"scientific integrity","meaning":"commitment to honesty, rigour and responsible conduct in science","translation":"liêm chính khoa học","example":"Scientific integrity is damaged by data fabrication.","synonyms":["research integrity"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Science Ethics & Research","word":"data fabrication","meaning":"the creation of research data that were never actually observed","translation":"bịa đặt dữ liệu","example":"Data fabrication is a serious form of research misconduct.","synonyms":["fabricated data"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Science Ethics & Research","word":"data falsification","meaning":"the improper alteration or manipulation of research data","translation":"làm sai lệch dữ liệu","example":"Data falsification can lead to retraction of published studies.","synonyms":["manipulated data"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Science Ethics & Research","word":"plagiarism","meaning":"the use of another person's work or ideas without proper acknowledgement","translation":"đạo văn","example":"Universities treat plagiarism as a serious breach of academic integrity.","synonyms":["unattributed copying"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Science Ethics & Research","word":"research retraction","meaning":"the formal withdrawal of a published study because it is unreliable or unethical","translation":"rút bài nghiên cứu","example":"The journal issued a research retraction after evidence of misconduct.","synonyms":["paper withdrawal"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Science Ethics & Research","word":"ethical review board","meaning":"an independent committee that evaluates the ethics of proposed research","translation":"hội đồng đạo đức nghiên cứu","example":"Human-subject studies require approval from an ethical review board.","synonyms":["ethics committee"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Science Ethics & Research","word":"human-subject research","meaning":"research involving people as participants or sources of identifiable data","translation":"nghiên cứu trên người","example":"Human-subject research must protect consent and privacy.","synonyms":["research with participants"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Science Ethics & Research","word":"participant consent","meaning":"voluntary agreement by a person to take part in research after receiving information","translation":"đồng thuận của người tham gia","example":"Participant consent should be informed and freely given.","synonyms":["research consent"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Science Ethics & Research","word":"research risk","meaning":"the potential for harm or disadvantage arising from participation in a study","translation":"rủi ro nghiên cứu","example":"Researchers must minimise unnecessary research risks.","synonyms":["study risk"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Science Ethics & Research","word":"research benefit","meaning":"a potential positive outcome of a study for participants or society","translation":"lợi ích nghiên cứu","example":"Ethics committees weigh research benefits against possible harms.","synonyms":["study benefit"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Science Ethics & Research","word":"dual-use research","meaning":"research that can be used for both beneficial and harmful purposes","translation":"nghiên cứu lưỡng dụng","example":"Dual-use research in biotechnology requires careful oversight.","synonyms":["dual-use science"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Science Ethics & Research","word":"precautionary principle","meaning":"the idea that serious potential harm may justify preventive action despite uncertainty","translation":"nguyên tắc phòng ngừa","example":"The precautionary principle is often invoked in environmental and biotechnology debates.","synonyms":["precaution principle"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Science Ethics & Research","word":"scientific freedom","meaning":"the freedom to pursue research and communicate findings without improper interference","translation":"tự do khoa học","example":"Scientific freedom must coexist with ethical responsibility.","synonyms":["research freedom"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Science Ethics & Research","word":"research accountability","meaning":"the responsibility of researchers and institutions for methods, conduct and impacts","translation":"trách nhiệm giải trình nghiên cứu","example":"Research accountability includes transparent correction of errors.","synonyms":["scientific accountability"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Science Ethics & Research","word":"peer-review integrity","meaning":"fairness, competence and confidentiality within the peer-review process","translation":"tính liêm chính phản biện đồng cấp","example":"Peer-review integrity is essential for trustworthy publication.","synonyms":["review integrity"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Science Ethics & Research","word":"transparent research practice","meaning":"research conducted with openness about methods, data, limitations and interests","translation":"thực hành nghiên cứu minh bạch","example":"Transparent research practice makes scientific claims easier to evaluate.","synonyms":["open research practice"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Science Ethics & Research","word":"methodological rigour","meaning":"the careful and appropriate design and execution of research methods","translation":"tính chặt chẽ phương pháp","example":"Methodological rigour is more important than impressive claims.","synonyms":["research rigour"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Science Ethics & Research","word":"statistical power","meaning":"the probability that a study can detect a real effect of a given size","translation":"sức mạnh thống kê","example":"Small samples often result in low statistical power.","synonyms":["study power"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Science Ethics & Research","word":"evidence hierarchy","meaning":"a ranking of research designs according to their typical strength for answering questions","translation":"thứ bậc bằng chứng","example":"Clinical guidelines often consider an evidence hierarchy.","synonyms":["hierarchy of evidence"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Science Ethics & Research","word":"responsible research","meaning":"research conducted with ethical, transparent and socially responsible practices","translation":"nghiên cứu có trách nhiệm","example":"Responsible research requires attention to both scientific quality and societal impact.","synonyms":["ethical research"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Cybersecurity & Data Privacy","word":"cyber threat","meaning":"a potential digital event or actor capable of causing harm","translation":"mối đe dọa mạng","example":"Organisations continuously monitor emerging cyber threats.","synonyms":["digital threat"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Cybersecurity & Data Privacy","word":"cyber attack","meaning":"an intentional attempt to disrupt, damage or access computer systems","translation":"tấn công mạng","example":"Hospitals are increasingly targeted by cyber attacks.","synonyms":["digital attack"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Cybersecurity & Data Privacy","word":"ransomware","meaning":"malware that blocks access to data or systems until payment is demanded","translation":"mã độc tống tiền","example":"Ransomware can interrupt essential public services.","synonyms":["extortion malware"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Cybersecurity & Data Privacy","word":"phishing","meaning":"fraudulent communication designed to steal passwords or sensitive information","translation":"lừa đảo phishing","example":"Staff training can reduce successful phishing attacks.","synonyms":["credential scam"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Cybersecurity & Data Privacy","word":"malware","meaning":"software intentionally designed to damage, disrupt or exploit systems","translation":"phần mềm độc hại","example":"Malware can spread through unsafe attachments and downloads.","synonyms":["malicious software"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Cybersecurity & Data Privacy","word":"security patch","meaning":"a software update that fixes known security weaknesses","translation":"bản vá bảo mật","example":"Devices should receive security patches promptly.","synonyms":["security update"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Cybersecurity & Data Privacy","word":"software vulnerability","meaning":"a weakness in software that can be exploited by attackers","translation":"lỗ hổng phần mềm","example":"Unpatched software vulnerabilities create major cyber risks.","synonyms":["security flaw"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Cybersecurity & Data Privacy","word":"zero-day vulnerability","meaning":"a security flaw unknown or not yet fixed by the software provider","translation":"lỗ hổng zero-day","example":"Zero-day vulnerabilities are highly valuable to attackers.","synonyms":["unknown security flaw"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Cybersecurity & Data Privacy","word":"multi-factor authentication","meaning":"a login process requiring more than one type of proof of identity","translation":"xác thực đa yếu tố","example":"Multi-factor authentication reduces the risk from stolen passwords.","synonyms":["MFA"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Cybersecurity & Data Privacy","word":"access control","meaning":"rules and technologies determining who can use systems or data","translation":"kiểm soát truy cập","example":"Strong access controls limit exposure of sensitive records.","synonyms":["authorisation control"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Cybersecurity & Data Privacy","word":"privilege management","meaning":"the control of elevated system permissions and administrator access","translation":"quản lý đặc quyền","example":"Poor privilege management can turn a small breach into a major incident.","synonyms":["permission management"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Cybersecurity & Data Privacy","word":"security incident","meaning":"an event that threatens the confidentiality, integrity or availability of systems","translation":"sự cố an ninh mạng","example":"Every security incident should be documented and investigated.","synonyms":["cyber incident"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Cybersecurity & Data Privacy","word":"incident response","meaning":"the organised process of detecting, containing and recovering from security incidents","translation":"ứng phó sự cố","example":"A tested incident-response plan reduces downtime after a breach.","synonyms":["cyber response"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Cybersecurity & Data Privacy","word":"data minimisation","meaning":"the principle of collecting only the personal data necessary for a purpose","translation":"tối thiểu hóa dữ liệu","example":"Data minimisation reduces privacy risk.","synonyms":["minimal data collection"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Cybersecurity & Data Privacy","word":"purpose limitation","meaning":"the privacy principle that data should be used only for stated legitimate purposes","translation":"giới hạn mục đích sử dụng","example":"Purpose limitation prevents organisations from reusing data without justification.","synonyms":["restricted data use"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Cybersecurity & Data Privacy","word":"data retention","meaning":"the period and policy for keeping stored information","translation":"lưu giữ dữ liệu","example":"Clear data-retention rules reduce unnecessary exposure.","synonyms":["information retention"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Cybersecurity & Data Privacy","word":"data deletion","meaning":"the secure removal of stored data when it is no longer needed","translation":"xóa dữ liệu","example":"Users should be able to request data deletion in appropriate cases.","synonyms":["information erasure"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Cybersecurity & Data Privacy","word":"privacy by design","meaning":"the practice of building privacy safeguards into systems from the beginning","translation":"quyền riêng tư ngay từ thiết kế","example":"Privacy by design is more effective than adding controls later.","synonyms":["built-in privacy"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Cybersecurity & Data Privacy","word":"data controller","meaning":"an organisation that determines why and how personal data are processed","translation":"bên kiểm soát dữ liệu","example":"A data controller is responsible for lawful processing.","synonyms":["information controller"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Cybersecurity & Data Privacy","word":"data processor","meaning":"an organisation that processes personal data on behalf of another organisation","translation":"bên xử lý dữ liệu","example":"Cloud providers may act as data processors.","synonyms":["information processor"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Cybersecurity & Data Privacy","word":"informed digital consent","meaning":"clear and meaningful agreement to online data collection or use","translation":"đồng thuận số có hiểu biết","example":"Long legal notices do not guarantee informed digital consent.","synonyms":["meaningful consent"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Cybersecurity & Data Privacy","word":"privacy notice","meaning":"a statement explaining how an organisation collects and uses personal data","translation":"thông báo quyền riêng tư","example":"A privacy notice should be understandable to ordinary users.","synonyms":["data-use notice"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Cybersecurity & Data Privacy","word":"cross-border data transfer","meaning":"the movement of personal or business data between countries","translation":"chuyển dữ liệu xuyên biên giới","example":"Cross-border data transfers raise questions about legal protection.","synonyms":["international data transfer"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Cybersecurity & Data Privacy","word":"data localisation","meaning":"a requirement that certain data be stored or processed within a country","translation":"bản địa hóa dữ liệu","example":"Data-localisation rules can increase compliance costs.","synonyms":["local data storage"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Cybersecurity & Data Privacy","word":"encryption at rest","meaning":"encryption applied to data while it is stored","translation":"mã hóa dữ liệu lưu trữ","example":"Encryption at rest protects stolen storage devices.","synonyms":["stored-data encryption"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Cybersecurity & Data Privacy","word":"encryption in transit","meaning":"encryption protecting data while it moves between systems","translation":"mã hóa dữ liệu truyền tải","example":"Encryption in transit is essential for secure online payments.","synonyms":["transport encryption"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Cybersecurity & Data Privacy","word":"anonymisation","meaning":"the process of removing or altering identifiers so people cannot reasonably be identified","translation":"ẩn danh hóa","example":"Strong anonymisation can reduce privacy risks in research datasets.","synonyms":["de-identification"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Cybersecurity & Data Privacy","word":"pseudonymisation","meaning":"replacing direct identifiers with artificial labels while retaining controlled linkage","translation":"giả danh hóa","example":"Pseudonymisation provides protection while allowing some data analysis.","synonyms":["coded identifiers"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Cybersecurity & Data Privacy","word":"cyber resilience","meaning":"the ability of an organisation to continue and recover from cyber disruption","translation":"khả năng chống chịu mạng","example":"Backups and rehearsed recovery plans strengthen cyber resilience.","synonyms":["digital resilience"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Food Security & Sustainable Agriculture","word":"agroecology","meaning":"an approach to farming that applies ecological principles to food production","translation":"nông nghiệp sinh thái","example":"Agroecology aims to improve resilience while reducing environmental harm.","synonyms":["ecological agriculture"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Food Security & Sustainable Agriculture","word":"regenerative farming","meaning":"farming practices intended to restore soil, biodiversity and ecosystem health","translation":"nông nghiệp tái sinh","example":"Regenerative farming often emphasises soil cover and crop diversity.","synonyms":["regenerative agriculture"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Food Security & Sustainable Agriculture","word":"conservation agriculture","meaning":"farming based on minimal soil disturbance, cover and crop rotation","translation":"nông nghiệp bảo tồn","example":"Conservation agriculture can reduce erosion and improve soil moisture.","synonyms":["soil-conserving farming"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Food Security & Sustainable Agriculture","word":"crop rotation","meaning":"the planned sequence of different crops grown on the same land","translation":"luân canh cây trồng","example":"Crop rotation can improve soil health and reduce pest pressure.","synonyms":["rotational cropping"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Food Security & Sustainable Agriculture","word":"cover crop","meaning":"a crop grown mainly to protect and improve soil rather than for sale","translation":"cây che phủ","example":"Cover crops reduce erosion during periods between harvests.","synonyms":["soil-cover crop"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Food Security & Sustainable Agriculture","word":"soil organic matter","meaning":"decomposed plant and animal material that improves soil properties","translation":"chất hữu cơ trong đất","example":"Higher soil organic matter can improve water retention.","synonyms":["soil carbon material"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Food Security & Sustainable Agriculture","word":"soil fertility","meaning":"the ability of soil to support healthy plant growth","translation":"độ phì nhiêu của đất","example":"Balanced nutrient management is essential for soil fertility.","synonyms":["productive soil"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Food Security & Sustainable Agriculture","word":"soil erosion","meaning":"the removal of topsoil by wind, water or human activity","translation":"xói mòn đất","example":"Deforestation and poor farming can accelerate soil erosion.","synonyms":["loss of topsoil"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Food Security & Sustainable Agriculture","word":"land degradation","meaning":"decline in the quality and productive capacity of land","translation":"suy thoái đất","example":"Overgrazing can contribute to severe land degradation.","synonyms":["degraded land"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Food Security & Sustainable Agriculture","word":"drought-tolerant crop","meaning":"a crop variety able to grow with limited water","translation":"cây chịu hạn","example":"Drought-tolerant crops can help farmers adapt to changing rainfall.","synonyms":["drought-resistant crop"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Food Security & Sustainable Agriculture","word":"climate-smart agriculture","meaning":"farming designed to improve productivity, resilience and climate performance","translation":"nông nghiệp thông minh với khí hậu","example":"Climate-smart agriculture combines adaptation and emissions reduction.","synonyms":["climate-resilient farming"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Food Security & Sustainable Agriculture","word":"precision agriculture","meaning":"the use of data and technology to manage farms more precisely","translation":"nông nghiệp chính xác","example":"Precision agriculture can reduce unnecessary fertiliser use.","synonyms":["precision farming"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Food Security & Sustainable Agriculture","word":"agricultural biotechnology","meaning":"the use of biological science and technology to improve crops or livestock","translation":"công nghệ sinh học nông nghiệp","example":"Agricultural biotechnology can improve disease resistance.","synonyms":["agri-biotechnology"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Food Security & Sustainable Agriculture","word":"genetically modified crop","meaning":"a crop whose genetic material has been deliberately altered using biotechnology","translation":"cây trồng biến đổi gen","example":"Genetically modified crops remain controversial in some markets.","synonyms":["GM crop"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Food Security & Sustainable Agriculture","word":"seed diversity","meaning":"the variety of crop seeds and genetic resources available to farmers","translation":"đa dạng giống cây trồng","example":"Seed diversity can increase resilience to pests and climate shocks.","synonyms":["crop genetic diversity"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Food Security & Sustainable Agriculture","word":"smallholder farmer","meaning":"a farmer operating a relatively small area of land","translation":"nông hộ nhỏ","example":"Smallholder farmers produce a large share of food in many countries.","synonyms":["small-scale farmer"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Food Security & Sustainable Agriculture","word":"agricultural extension","meaning":"services that provide farmers with technical advice and training","translation":"khuyến nông","example":"Agricultural extension can spread improved farming practices.","synonyms":["farm advisory service"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Food Security & Sustainable Agriculture","word":"farm-to-market access","meaning":"the ability of farmers to transport and sell products to buyers","translation":"khả năng tiếp cận thị trường của nông dân","example":"Better roads improve farm-to-market access.","synonyms":["market access for farmers"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Food Security & Sustainable Agriculture","word":"post-harvest loss","meaning":"food lost after harvest during storage, transport or processing","translation":"tổn thất sau thu hoạch","example":"Cold storage can reduce post-harvest losses.","synonyms":["post-harvest waste"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Food Security & Sustainable Agriculture","word":"cold chain","meaning":"temperature-controlled storage and transport for perishable products","translation":"chuỗi lạnh","example":"A reliable cold chain reduces spoilage of fruit, fish and vaccines.","synonyms":["refrigerated supply chain"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Food Security & Sustainable Agriculture","word":"food-system resilience","meaning":"the ability of a food system to withstand and recover from shocks","translation":"khả năng chống chịu hệ thống thực phẩm","example":"Diverse supply sources improve food-system resilience.","synonyms":["food resilience"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Food Security & Sustainable Agriculture","word":"nutrition security","meaning":"reliable access not only to enough food but also to nutritious diets","translation":"an ninh dinh dưỡng","example":"Nutrition security requires affordability and dietary quality.","synonyms":["nutritional security"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Food Security & Sustainable Agriculture","word":"food-access inequality","meaning":"unequal ability to obtain sufficient healthy food","translation":"bất bình đẳng tiếp cận thực phẩm","example":"Food-access inequality is often greater in low-income neighbourhoods.","synonyms":["food disparity"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Food Security & Sustainable Agriculture","word":"affordable food access","meaning":"the ability of households to obtain adequate food at prices they can reasonably pay","translation":"khả năng tiếp cận thực phẩm với giá phải chăng","example":"Inflation can weaken affordable food access for low-income families.","synonyms":["affordable nutrition access"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Food Security & Sustainable Agriculture","word":"strategic food reserve","meaning":"a government-held stock of food intended for emergencies or shortages","translation":"dự trữ lương thực chiến lược","example":"A strategic food reserve can stabilise supply during disasters.","synonyms":["emergency food stock"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Food Security & Sustainable Agriculture","word":"agricultural emissions","meaning":"greenhouse-gas emissions produced by farming and food production","translation":"phát thải nông nghiệp","example":"Livestock and fertiliser are major sources of agricultural emissions.","synonyms":["farm emissions"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Food Security & Sustainable Agriculture","word":"methane emissions","meaning":"releases of methane, a powerful greenhouse gas","translation":"phát thải methane","example":"Livestock is an important source of methane emissions.","synonyms":["CH4 emissions"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Food Security & Sustainable Agriculture","word":"sustainable intensification","meaning":"increasing farm output while limiting environmental harm","translation":"thâm canh bền vững","example":"Sustainable intensification seeks higher yields without expanding farmland.","synonyms":["efficient sustainable farming"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Food Security & Sustainable Agriculture","word":"food-policy coherence","meaning":"the alignment of policies on agriculture, health, trade and the environment","translation":"tính nhất quán chính sách thực phẩm","example":"Food-policy coherence is needed to address both nutrition and sustainability.","synonyms":["coherent food policy"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Water Security","word":"water stress","meaning":"a condition in which water demand is high relative to available supply","translation":"căng thẳng nguồn nước","example":"Rapid urban growth can increase water stress.","synonyms":["water pressure"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Water Security","word":"water deficit","meaning":"a shortage between water required and water available","translation":"thâm hụt nước","example":"Prolonged drought can create a severe water deficit.","synonyms":["water shortfall"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Water Security","word":"water demand management","meaning":"policies and practices used to reduce or shift water consumption","translation":"quản lý nhu cầu nước","example":"Pricing and efficient appliances are tools for water-demand management.","synonyms":["demand-side water management"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Water Security","word":"integrated water management","meaning":"coordinated management of water across users, sectors and ecosystems","translation":"quản lý nước tích hợp","example":"Integrated water management can reduce conflict between cities and agriculture.","synonyms":["coordinated water management"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Water Security","word":"river-basin management","meaning":"the coordinated management of water resources across an entire river basin","translation":"quản lý lưu vực sông","example":"River-basin management requires cooperation between upstream and downstream users.","synonyms":["watershed management"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Water Security","word":"watershed","meaning":"an area of land from which water drains into the same river or body of water","translation":"lưu vực","example":"Forest protection in a watershed can improve water quality.","synonyms":["drainage basin"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Water Security","word":"groundwater depletion","meaning":"the long-term decline of underground water reserves due to excessive extraction","translation":"suy giảm nước ngầm","example":"Groundwater depletion threatens farming in dry regions.","synonyms":["aquifer depletion"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Water Security","word":"aquifer","meaning":"an underground layer of rock or sediment that stores and transmits water","translation":"tầng chứa nước","example":"Agricultural pumping can lower the level of an aquifer.","synonyms":["groundwater reservoir"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Water Security","word":"groundwater recharge","meaning":"the process by which water moves from the surface into underground aquifers","translation":"bổ cập nước ngầm","example":"Urban paving can reduce natural groundwater recharge.","synonyms":["aquifer recharge"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Water Security","word":"water table","meaning":"the upper level of underground water in soil or rock","translation":"mực nước ngầm","example":"The water table has fallen because of intensive pumping.","synonyms":["groundwater level"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Water Security","word":"water quality monitoring","meaning":"the regular measurement of water conditions and contamination","translation":"giám sát chất lượng nước","example":"Water-quality monitoring can identify pollution before it spreads.","synonyms":["water testing"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Water Security","word":"wastewater treatment","meaning":"the process of cleaning used water before release or reuse","translation":"xử lý nước thải","example":"Modern wastewater treatment protects rivers and public health.","synonyms":["sewage treatment"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Water Security","word":"wastewater reuse","meaning":"the use of treated wastewater for agriculture, industry or other purposes","translation":"tái sử dụng nước thải","example":"Wastewater reuse can reduce pressure on freshwater supplies.","synonyms":["water recycling"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Water Security","word":"water recycling","meaning":"the treatment and reuse of water rather than discarding it","translation":"tái chế nước","example":"Water recycling is increasingly common in water-scarce cities.","synonyms":["water reuse"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Water Security","word":"potable water","meaning":"water that is safe to drink","translation":"nước uống được","example":"Reliable access to potable water remains uneven globally.","synonyms":["drinking water"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Water Security","word":"non-potable water","meaning":"water suitable for uses such as irrigation but not drinking","translation":"nước không dùng để uống","example":"Buildings can use non-potable water for landscaping.","synonyms":["utility water"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Water Security","word":"water purification","meaning":"the removal of contaminants to make water safer or cleaner","translation":"lọc nước","example":"Water purification is essential where source water is polluted.","synonyms":["water cleaning"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Water Security","word":"reverse osmosis","meaning":"a filtration process often used to remove salts and contaminants from water","translation":"thẩm thấu ngược","example":"Reverse osmosis is widely used in desalination plants.","synonyms":["membrane filtration"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Water Security","word":"desalination plant","meaning":"a facility that removes salt from seawater or brackish water","translation":"nhà máy khử mặn","example":"Desalination plants provide drinking water but require substantial energy.","synonyms":["salt-removal plant"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Water Security","word":"water-use efficiency","meaning":"the amount of useful output obtained from a given amount of water","translation":"hiệu quả sử dụng nước","example":"Drip irrigation can improve water-use efficiency in agriculture.","synonyms":["water efficiency"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Water Security","word":"water leakage","meaning":"the loss of treated water from pipes or infrastructure","translation":"rò rỉ nước","example":"Repairing water leakage can save large volumes in old networks.","synonyms":["pipe leakage"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Water Security","word":"non-revenue water","meaning":"treated water lost before it reaches paying customers","translation":"nước thất thoát không doanh thu","example":"Reducing non-revenue water is a priority for many utilities.","synonyms":["distribution loss"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Water Security","word":"water utility","meaning":"an organisation responsible for supplying and managing water services","translation":"đơn vị cấp nước","example":"Water utilities must maintain pipes and treatment plants.","synonyms":["water provider"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Water Security","word":"water tariff","meaning":"a price charged for supplied water","translation":"biểu giá nước","example":"Well-designed water tariffs can encourage conservation while protecting poor households.","synonyms":["water price"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Water Security","word":"water allocation policy","meaning":"rules determining how limited water is distributed among users","translation":"chính sách phân bổ nước","example":"Water-allocation policy becomes contentious during drought.","synonyms":["distribution policy"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Water Security","word":"transboundary water","meaning":"water resources such as rivers or aquifers shared by more than one country","translation":"nguồn nước xuyên biên giới","example":"Transboundary water requires international cooperation.","synonyms":["shared water resource"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Water Security","word":"water conflict","meaning":"disagreement or tension over access to water resources","translation":"xung đột nguồn nước","example":"Scarcity can increase the risk of local water conflict.","synonyms":["water dispute"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Water Security","word":"water resilience","meaning":"the ability of water systems and communities to cope with shocks and shortages","translation":"khả năng chống chịu nguồn nước","example":"Diversified supply strengthens urban water resilience.","synonyms":["water-system resilience"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Water Security","word":"water governance","meaning":"the institutions, rules and processes used to manage water resources","translation":"quản trị nước","example":"Effective water governance requires transparency and participation.","synonyms":["governance of water"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"International Development","word":"development finance","meaning":"funding used to support economic and social development","translation":"tài chính phát triển","example":"Development finance can fund infrastructure and health systems.","synonyms":["development funding"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"International Development","word":"concessional loan","meaning":"a loan offered on more favourable terms than commercial finance","translation":"khoản vay ưu đãi","example":"Low-income countries may receive concessional loans for public projects.","synonyms":["soft loan"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"International Development","word":"grant aid","meaning":"financial assistance provided without requiring repayment","translation":"viện trợ không hoàn lại","example":"Grant aid is often used for humanitarian and health programmes.","synonyms":["development grant"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"International Development","word":"bilateral aid","meaning":"development assistance provided directly from one government to another","translation":"viện trợ song phương","example":"Bilateral aid often reflects both humanitarian and strategic priorities.","synonyms":["government-to-government aid"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"International Development","word":"multilateral aid","meaning":"development assistance provided through international organisations","translation":"viện trợ đa phương","example":"Multilateral aid can pool resources from many countries.","synonyms":["international institutional aid"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"International Development","word":"aid effectiveness","meaning":"the degree to which development assistance achieves sustainable results","translation":"hiệu quả viện trợ","example":"Local ownership is widely considered important for aid effectiveness.","synonyms":["development effectiveness"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"International Development","word":"local ownership","meaning":"meaningful control of development priorities by local governments and communities","translation":"quyền làm chủ địa phương","example":"Projects are more sustainable when they have strong local ownership.","synonyms":["domestic ownership"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"International Development","word":"capacity development","meaning":"the long-term strengthening of skills, institutions and systems","translation":"phát triển năng lực","example":"Capacity development can be more durable than short-term technical assistance.","synonyms":["institutional strengthening"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"International Development","word":"institution building","meaning":"the creation or strengthening of effective organisations and governance systems","translation":"xây dựng thể chế","example":"Institution building is central to long-term development.","synonyms":["institutional development"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"International Development","word":"technical assistance","meaning":"expert advice and practical support provided to institutions or governments","translation":"hỗ trợ kỹ thuật","example":"Technical assistance can help ministries improve data systems.","synonyms":["expert support"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"International Development","word":"infrastructure gap","meaning":"the difference between infrastructure needed and infrastructure available","translation":"khoảng cách hạ tầng","example":"Many fast-growing cities face a substantial infrastructure gap.","synonyms":["infrastructure deficit"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"International Development","word":"financing gap","meaning":"the difference between funding required and funding available","translation":"khoảng thiếu hụt tài chính","example":"Climate adaptation faces a large financing gap.","synonyms":["funding gap"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"International Development","word":"poverty alleviation","meaning":"efforts to reduce the severity and extent of poverty","translation":"giảm nghèo","example":"Job creation is a central part of poverty alleviation.","synonyms":["poverty reduction"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"International Development","word":"multidimensional poverty","meaning":"poverty measured across several deprivations such as health, education and living standards","translation":"nghèo đa chiều","example":"Multidimensional poverty can persist even when income improves.","synonyms":["multiple deprivation"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"International Development","word":"social protection system","meaning":"policies and programmes that protect people from poverty and economic shocks","translation":"hệ thống bảo trợ xã hội","example":"A strong social-protection system can reduce vulnerability during crises.","synonyms":["social safety system"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"International Development","word":"cash transfer","meaning":"money provided directly to eligible households through a public programme","translation":"chuyển tiền trợ cấp","example":"Targeted cash transfers can support food security.","synonyms":["direct income support"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"International Development","word":"conditional cash transfer","meaning":"a payment provided to households if they meet conditions such as school attendance","translation":"chuyển tiền có điều kiện","example":"Conditional cash transfers have been used to improve school participation.","synonyms":["conditional benefit"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"International Development","word":"financial inclusion","meaning":"access to useful and affordable financial services","translation":"tài chính toàn diện","example":"Mobile banking has expanded financial inclusion in remote areas.","synonyms":["access to finance"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"International Development","word":"economic empowerment","meaning":"increased ability of people to participate in and benefit from economic activity","translation":"trao quyền kinh tế","example":"Women's economic empowerment can raise household welfare.","synonyms":["financial empowerment"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"International Development","word":"community-led development","meaning":"development in which local communities influence priorities and implementation","translation":"phát triển do cộng đồng dẫn dắt","example":"Community-led development can improve accountability.","synonyms":["participatory development"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"International Development","word":"bottom-up development","meaning":"development shaped by local needs and participation rather than only central planning","translation":"phát triển từ dưới lên","example":"Bottom-up development can produce solutions better suited to local conditions.","synonyms":["grassroots development"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"International Development","word":"development outcome","meaning":"a measurable social, economic or institutional result of development efforts","translation":"kết quả phát triển","example":"Improved school attendance is one development outcome.","synonyms":["development result"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"International Development","word":"impact evaluation","meaning":"a study estimating whether an intervention caused particular outcomes","translation":"đánh giá tác động","example":"Impact evaluations help identify which programmes work.","synonyms":["programme evaluation"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"International Development","word":"randomised controlled trial","meaning":"an experiment that randomly assigns participants to intervention and comparison groups","translation":"thử nghiệm đối chứng ngẫu nhiên","example":"Randomised controlled trials are increasingly used in development economics.","synonyms":["RCT"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"International Development","word":"sustainable livelihood","meaning":"a way of earning a living that can withstand shocks without degrading resources","translation":"sinh kế bền vững","example":"Diversified income can support a sustainable livelihood.","synonyms":["resilient livelihood"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"International Development","word":"human-capital investment","meaning":"investment in education, health and skills that increases people's productive capacity","translation":"đầu tư vốn con người","example":"Human-capital investment supports long-term economic development.","synonyms":["investment in people"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"International Development","word":"development resilience","meaning":"the ability of communities and systems to continue progressing despite shocks","translation":"khả năng chống chịu phát triển","example":"Social protection can strengthen development resilience.","synonyms":["resilient development"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"International Development","word":"inclusive development","meaning":"development that expands opportunities and benefits across social groups","translation":"phát triển bao trùm","example":"Inclusive development requires attention to marginalised communities.","synonyms":["broad-based development"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"International Development","word":"development governance","meaning":"the institutions and decision processes shaping development policy and implementation","translation":"quản trị phát triển","example":"Strong development governance improves the use of public resources.","synonyms":["governance for development"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Animal Ethics","word":"sentience","meaning":"the capacity to experience sensations such as pain or pleasure","translation":"khả năng cảm nhận","example":"Animal ethics often depends on evidence about sentience.","synonyms":["capacity to feel"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Animal Ethics","word":"animal sentience","meaning":"the capacity of non-human animals to feel and experience states","translation":"khả năng cảm nhận của động vật","example":"Recognition of animal sentience has influenced welfare law.","synonyms":["sentience in animals"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Animal Ethics","word":"speciesism","meaning":"discrimination or unequal moral consideration based solely on species membership","translation":"chủ nghĩa phân biệt loài","example":"Critics of intensive farming often invoke the concept of speciesism.","synonyms":["species-based discrimination"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Animal Ethics","word":"moral status","meaning":"the degree of moral consideration an entity is believed to deserve","translation":"địa vị đạo đức","example":"Debates about animal moral status affect research and farming policy.","synonyms":["ethical status"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Animal Ethics","word":"animal suffering","meaning":"physical or psychological pain experienced by animals","translation":"đau khổ của động vật","example":"Welfare standards aim to minimise avoidable animal suffering.","synonyms":["animal distress"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Animal Ethics","word":"welfare standard","meaning":"a formal rule setting minimum conditions for animal treatment","translation":"tiêu chuẩn phúc lợi động vật","example":"Higher welfare standards can increase production costs.","synonyms":["animal-care standard"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Animal Ethics","word":"welfare certification","meaning":"a label or scheme indicating compliance with animal-welfare criteria","translation":"chứng nhận phúc lợi động vật","example":"Consumers may pay more for welfare-certified products.","synonyms":["ethical certification"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Animal Ethics","word":"free-range farming","meaning":"a system allowing farm animals some access to outdoor space","translation":"chăn nuôi thả tự do","example":"Free-range farming is often promoted as a welfare improvement.","synonyms":["outdoor farming"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Animal Ethics","word":"intensive livestock farming","meaning":"high-density animal production designed to maximise output","translation":"chăn nuôi thâm canh","example":"Intensive livestock farming raises concerns about welfare and emissions.","synonyms":["factory livestock farming"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Animal Ethics","word":"battery cage","meaning":"a small cage historically used to confine egg-laying hens","translation":"lồng pin","example":"Many jurisdictions have restricted conventional battery cages.","synonyms":["confinement cage"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Animal Ethics","word":"animal confinement","meaning":"the restriction of animals to limited spaces","translation":"giam giữ động vật","example":"Prolonged animal confinement can prevent natural behaviour.","synonyms":["restricted housing"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Animal Ethics","word":"natural behaviour","meaning":"behaviour animals are strongly motivated to perform in suitable environments","translation":"hành vi tự nhiên","example":"Welfare systems increasingly consider animals' ability to express natural behaviour.","synonyms":["species-typical behaviour"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Animal Ethics","word":"humane slaughter","meaning":"the killing of animals using methods intended to minimise pain and distress","translation":"giết mổ nhân đạo","example":"Humane-slaughter rules require effective stunning in many countries.","synonyms":["welfare-oriented slaughter"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Animal Ethics","word":"stunning","meaning":"a process intended to make an animal unconscious before slaughter","translation":"gây choáng","example":"Effective stunning can reduce suffering during slaughter.","synonyms":["pre-slaughter stunning"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Animal Ethics","word":"animal research ethics","meaning":"ethical principles governing the use of animals in scientific research","translation":"đạo đức nghiên cứu động vật","example":"Animal-research ethics emphasises necessity and minimising harm.","synonyms":["laboratory animal ethics"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Animal Ethics","word":"three Rs","meaning":"the principles of replacement, reduction and refinement in animal research","translation":"nguyên tắc 3R","example":"The three Rs guide ethical laboratory-animal research.","synonyms":["replacement reduction refinement"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Animal Ethics","word":"replacement method","meaning":"a research method that avoids or substitutes live-animal use","translation":"phương pháp thay thế động vật","example":"Cell cultures can serve as a replacement method for some experiments.","synonyms":["alternative method"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Animal Ethics","word":"refinement","meaning":"changes to procedures that reduce animal pain or distress","translation":"cải tiến giảm đau khổ động vật","example":"Better housing and anaesthesia are forms of refinement.","synonyms":["welfare refinement"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Animal Ethics","word":"animal sanctuary","meaning":"a place providing long-term care for animals without commercial exploitation","translation":"khu bảo tồn cứu hộ động vật","example":"Rescued animals may live permanently in a sanctuary.","synonyms":["rescue sanctuary"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Animal Ethics","word":"captive breeding","meaning":"breeding animals in controlled environments, often for conservation","translation":"nhân giống trong điều kiện nuôi nhốt","example":"Captive breeding can support endangered species but has limitations.","synonyms":["conservation breeding"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Animal Ethics","word":"wildlife trade","meaning":"the legal or illegal buying and selling of wild animals and plants","translation":"buôn bán động vật hoang dã","example":"Unregulated wildlife trade threatens biodiversity and public health.","synonyms":["trade in wildlife"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Animal Ethics","word":"illegal wildlife trade","meaning":"the prohibited trade in protected wild species or products","translation":"buôn bán động vật hoang dã trái phép","example":"International cooperation is needed to combat illegal wildlife trade.","synonyms":["wildlife trafficking"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Animal Ethics","word":"poaching","meaning":"illegal hunting or capturing of wild animals","translation":"săn trộm","example":"Poaching remains a major threat to some endangered mammals.","synonyms":["illegal hunting"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Animal Ethics","word":"trophy hunting","meaning":"hunting wild animals, often for recreation and display of body parts","translation":"săn chiến tích","example":"Trophy hunting is highly controversial in conservation debates.","synonyms":["sport hunting"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Animal Ethics","word":"ethical consumer choice","meaning":"a purchasing decision influenced by moral concerns about production","translation":"lựa chọn tiêu dùng có đạo đức","example":"Labels can help people make ethical consumer choices about animal products.","synonyms":["ethical purchasing"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Animal Ethics","word":"plant-based diet","meaning":"a diet composed mainly or entirely of foods from plants","translation":"chế độ ăn dựa trên thực vật","example":"Some people adopt a plant-based diet for welfare and environmental reasons.","synonyms":["plant-focused diet"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Animal Ethics","word":"cultivated meat","meaning":"meat produced from animal cells rather than by raising and slaughtering animals","translation":"thịt nuôi cấy","example":"Cultivated meat could reduce some forms of animal exploitation.","synonyms":["cell-cultured meat"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Animal Ethics","word":"animal-welfare legislation","meaning":"laws regulating the treatment and protection of animals","translation":"luật phúc lợi động vật","example":"Animal-welfare legislation differs greatly between countries.","synonyms":["animal-protection law"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Animal Ethics","word":"ethical treatment of animals","meaning":"treatment of animals according to principles of welfare and moral consideration","translation":"đối xử có đạo đức với động vật","example":"Public attitudes towards the ethical treatment of animals have changed over time.","synonyms":["humane treatment"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Space Exploration","word":"low Earth orbit","meaning":"the region of space relatively close to Earth where many satellites operate","translation":"quỹ đạo Trái Đất thấp","example":"Low Earth orbit has become increasingly crowded with satellites.","synonyms":["LEO"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Space Exploration","word":"geostationary orbit","meaning":"an orbit in which a satellite remains above the same point on Earth","translation":"quỹ đạo địa tĩnh","example":"Communication satellites commonly use geostationary orbit.","synonyms":["GEO"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Space Exploration","word":"launch vehicle","meaning":"a rocket system used to carry payloads into space","translation":"phương tiện phóng","example":"Reusable launch vehicles may reduce the cost of access to space.","synonyms":["rocket"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Space Exploration","word":"payload","meaning":"equipment, satellites or cargo carried by a spacecraft or launch vehicle","translation":"tải trọng","example":"The rocket successfully delivered its payload into orbit.","synonyms":["space cargo"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Space Exploration","word":"satellite constellation","meaning":"a coordinated group of satellites providing a shared service","translation":"chòm vệ tinh","example":"Large satellite constellations can expand global internet coverage.","synonyms":["satellite network"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Space Exploration","word":"Earth observation","meaning":"the collection of information about Earth using satellites and remote sensing","translation":"quan sát Trái Đất","example":"Earth-observation satellites monitor forests, weather and agriculture.","synonyms":["remote sensing"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Space Exploration","word":"remote sensing","meaning":"the collection of information about an object or area without direct physical contact","translation":"viễn thám","example":"Remote sensing provides valuable environmental data.","synonyms":["satellite sensing"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Space Exploration","word":"space-based infrastructure","meaning":"satellites and systems in space that support services on Earth","translation":"hạ tầng không gian","example":"Modern navigation depends on space-based infrastructure.","synonyms":["orbital infrastructure"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Space Exploration","word":"satellite navigation","meaning":"the use of satellites to determine location and support navigation","translation":"định vị vệ tinh","example":"Satellite navigation is essential for transport and logistics.","synonyms":["GNSS navigation"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Space Exploration","word":"space debris","meaning":"non-functioning human-made objects left in orbit","translation":"rác vũ trụ","example":"Space debris increases collision risk for active satellites.","synonyms":["orbital debris"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Space Exploration","word":"orbital congestion","meaning":"crowding of useful orbital regions by satellites and debris","translation":"ùn tắc quỹ đạo","example":"Orbital congestion has become an issue for space governance.","synonyms":["crowded orbit"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Space Exploration","word":"collision avoidance","meaning":"measures used to prevent spacecraft or satellites from colliding","translation":"tránh va chạm","example":"Satellite operators increasingly perform collision-avoidance manoeuvres.","synonyms":["collision prevention"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Space Exploration","word":"space situational awareness","meaning":"monitoring objects and conditions in space to support safe operations","translation":"nhận thức tình huống không gian","example":"Space-situational awareness helps operators track dangerous debris.","synonyms":["space monitoring"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Space Exploration","word":"space traffic management","meaning":"rules and systems used to coordinate safe movement in orbit","translation":"quản lý giao thông không gian","example":"Space-traffic management is becoming more urgent as launches increase.","synonyms":["orbital traffic management"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Space Exploration","word":"planetary exploration","meaning":"scientific investigation of planets, moons and other celestial bodies","translation":"thám hiểm hành tinh","example":"Robotic missions dominate current planetary exploration.","synonyms":["planetary science missions"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Space Exploration","word":"lunar mission","meaning":"a mission designed to explore or operate around the Moon","translation":"sứ mệnh Mặt Trăng","example":"Several countries are planning new lunar missions.","synonyms":["Moon mission"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Space Exploration","word":"Mars mission","meaning":"a mission intended to study or reach Mars","translation":"sứ mệnh Sao Hỏa","example":"Mars missions face major communication and engineering challenges.","synonyms":["mission to Mars"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Space Exploration","word":"sample-return mission","meaning":"a mission that brings material from another celestial body back to Earth","translation":"sứ mệnh mang mẫu vật về","example":"Sample-return missions can allow detailed laboratory analysis.","synonyms":["sample return"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Space Exploration","word":"space telescope","meaning":"a telescope placed beyond Earth's atmosphere","translation":"kính thiên văn không gian","example":"Space telescopes can observe wavelengths blocked by the atmosphere.","synonyms":["orbital telescope"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Space Exploration","word":"astronomical observation","meaning":"systematic observation of objects and phenomena in space","translation":"quan sát thiên văn","example":"Astronomical observations have revealed thousands of exoplanets.","synonyms":["space observation"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Space Exploration","word":"exoplanet","meaning":"a planet orbiting a star outside the Solar System","translation":"ngoại hành tinh","example":"New instruments are analysing the atmospheres of distant exoplanets.","synonyms":["extrasolar planet"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Space Exploration","word":"astrobiology","meaning":"the study of the origin, evolution and possibility of life in the universe","translation":"sinh học vũ trụ","example":"Astrobiology combines astronomy, chemistry and biology.","synonyms":["space biology"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Space Exploration","word":"space-resource utilisation","meaning":"the use of materials found on the Moon, asteroids or other bodies","translation":"khai thác tài nguyên không gian","example":"Space-resource utilisation could reduce the need to launch all materials from Earth.","synonyms":["in-situ resource use"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Space Exploration","word":"in-situ resource utilisation","meaning":"the use of local space materials for fuel, construction or life support","translation":"sử dụng tài nguyên tại chỗ","example":"Lunar missions are testing in-situ resource-utilisation concepts.","synonyms":["ISRU"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Space Exploration","word":"commercial spaceflight","meaning":"spaceflight operated by private companies for commercial purposes","translation":"bay vũ trụ thương mại","example":"Commercial spaceflight has lowered some launch costs.","synonyms":["private spaceflight"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Space Exploration","word":"space economy","meaning":"economic activity related to satellites, launches, services and space technology","translation":"kinh tế không gian","example":"The space economy includes communications, navigation and Earth observation.","synonyms":["space sector"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Space Exploration","word":"space governance","meaning":"international and national rules and institutions governing space activities","translation":"quản trị không gian","example":"Space governance must address debris, resources and military risks.","synonyms":["governance of outer space"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Space Exploration","word":"space sustainability","meaning":"the long-term safe and responsible use of the space environment","translation":"tính bền vững không gian","example":"Debris mitigation is central to space sustainability.","synonyms":["sustainable space use"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Space Exploration","word":"planetary protection","meaning":"measures to avoid biological contamination between Earth and other celestial bodies","translation":"bảo vệ hành tinh","example":"Planetary-protection rules shape missions that may encounter habitable environments.","synonyms":["contamination prevention"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Corporate Responsibility & ESG","word":"ESG disclosure","meaning":"public reporting of environmental, social and governance information","translation":"công bố ESG","example":"Investors increasingly expect consistent ESG disclosure.","synonyms":["sustainability disclosure"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Corporate Responsibility & ESG","word":"sustainability reporting","meaning":"corporate reporting on environmental and social impacts and performance","translation":"báo cáo bền vững","example":"Sustainability reporting is becoming more standardised.","synonyms":["non-financial reporting"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Corporate Responsibility & ESG","word":"materiality assessment","meaning":"a process for identifying sustainability issues most important to a company and stakeholders","translation":"đánh giá tính trọng yếu","example":"A materiality assessment helps firms prioritise ESG reporting.","synonyms":["materiality analysis"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Corporate Responsibility & ESG","word":"double materiality","meaning":"the idea that firms should assess both financial effects and their impacts on society and environment","translation":"tính trọng yếu kép","example":"Double materiality is increasingly used in sustainability regulation.","synonyms":["dual materiality"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Corporate Responsibility & ESG","word":"climate disclosure","meaning":"reporting of climate risks, emissions and strategies by organisations","translation":"công bố thông tin khí hậu","example":"Climate disclosure helps investors compare corporate transition plans.","synonyms":["climate reporting"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Corporate Responsibility & ESG","word":"scope 1 emissions","meaning":"direct greenhouse-gas emissions from sources controlled by a company","translation":"phát thải phạm vi 1","example":"A factory's fuel combustion contributes to scope 1 emissions.","synonyms":["direct emissions"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Corporate Responsibility & ESG","word":"scope 2 emissions","meaning":"indirect emissions associated with purchased electricity or energy","translation":"phát thải phạm vi 2","example":"Buying renewable electricity can reduce market-based scope 2 emissions.","synonyms":["purchased-energy emissions"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Corporate Responsibility & ESG","word":"scope 3 emissions","meaning":"indirect emissions across a company's value chain","translation":"phát thải phạm vi 3","example":"For many companies, scope 3 emissions are larger than direct emissions.","synonyms":["value-chain emissions"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Corporate Responsibility & ESG","word":"carbon accounting","meaning":"the measurement and reporting of greenhouse-gas emissions","translation":"hạch toán carbon","example":"Reliable carbon accounting is necessary for credible climate targets.","synonyms":["emissions accounting"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Corporate Responsibility & ESG","word":"transition plan","meaning":"a strategy explaining how an organisation will move towards a lower-carbon model","translation":"kế hoạch chuyển đổi","example":"Investors are scrutinising the credibility of corporate transition plans.","synonyms":["decarbonisation plan"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Corporate Responsibility & ESG","word":"science-based target","meaning":"an emissions target aligned with climate science and temperature goals","translation":"mục tiêu dựa trên khoa học","example":"Science-based targets can guide corporate decarbonisation.","synonyms":["science-aligned target"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Corporate Responsibility & ESG","word":"net-zero strategy","meaning":"a plan to reduce emissions and balance residual emissions with removals","translation":"chiến lược net-zero","example":"A net-zero strategy should prioritise actual emission reductions.","synonyms":["carbon-neutral strategy"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Corporate Responsibility & ESG","word":"carbon offset","meaning":"a claimed emissions reduction or removal used to compensate for emissions elsewhere","translation":"tín chỉ bù trừ carbon","example":"Heavy reliance on carbon offsets can weaken a transition strategy.","synonyms":["emissions offset"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Corporate Responsibility & ESG","word":"supply-chain due diligence","meaning":"the process of identifying and addressing risks in suppliers and business partners","translation":"thẩm định chuỗi cung ứng","example":"Supply-chain due diligence can reveal labour and environmental risks.","synonyms":["supplier due diligence"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Corporate Responsibility & ESG","word":"human-rights due diligence","meaning":"a process for identifying and addressing corporate impacts on human rights","translation":"thẩm định quyền con người","example":"Large firms face growing expectations for human-rights due diligence.","synonyms":["rights assessment"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Corporate Responsibility & ESG","word":"responsible sourcing","meaning":"the purchase of materials and products according to ethical and sustainability standards","translation":"thu mua có trách nhiệm","example":"Responsible sourcing is important in minerals, agriculture and textiles.","synonyms":["ethical sourcing"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Corporate Responsibility & ESG","word":"supplier code of conduct","meaning":"a set of standards suppliers are expected to follow","translation":"bộ quy tắc ứng xử nhà cung cấp","example":"A supplier code of conduct should be backed by monitoring and remediation.","synonyms":["supplier standard"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Corporate Responsibility & ESG","word":"supply-chain transparency","meaning":"visibility into where products and materials come from and how they are produced","translation":"minh bạch chuỗi cung ứng","example":"Digital traceability can improve supply-chain transparency.","synonyms":["supplier transparency"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Corporate Responsibility & ESG","word":"corporate due diligence","meaning":"systematic assessment and management of business risks and impacts","translation":"thẩm định doanh nghiệp","example":"Corporate due diligence is moving from voluntary practice towards legal obligation.","synonyms":["business due diligence"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Corporate Responsibility & ESG","word":"stakeholder engagement","meaning":"structured communication with people or groups affected by corporate decisions","translation":"gắn kết các bên liên quan","example":"Stakeholder engagement can identify risks that financial data miss.","synonyms":["stakeholder consultation"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Corporate Responsibility & ESG","word":"shareholder primacy","meaning":"the view that a company's main purpose is to maximise returns to shareholders","translation":"ưu tiên cổ đông","example":"Critics argue that shareholder primacy overlooks wider social impacts.","synonyms":["shareholder-first model"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Corporate Responsibility & ESG","word":"stakeholder governance","meaning":"corporate governance that considers employees, communities and other affected groups","translation":"quản trị theo các bên liên quan","example":"Stakeholder governance broadens the responsibilities of corporate boards.","synonyms":["stakeholder model"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Corporate Responsibility & ESG","word":"board oversight","meaning":"the supervision of company strategy and risk by its board of directors","translation":"giám sát của hội đồng quản trị","example":"Effective board oversight is essential for climate-risk management.","synonyms":["board supervision"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Corporate Responsibility & ESG","word":"executive accountability","meaning":"the responsibility of senior managers for organisational decisions and outcomes","translation":"trách nhiệm giải trình của lãnh đạo","example":"Executive accountability should include sustainability commitments.","synonyms":["management accountability"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Corporate Responsibility & ESG","word":"whistleblower protection","meaning":"legal and organisational safeguards for people reporting wrongdoing","translation":"bảo vệ người tố giác","example":"Strong whistleblower protection can expose misconduct earlier.","synonyms":["reporter protection"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Corporate Responsibility & ESG","word":"corporate misconduct","meaning":"illegal, unethical or seriously irresponsible behaviour by a company","translation":"sai phạm doanh nghiệp","example":"Weak governance can allow corporate misconduct to continue unnoticed.","synonyms":["business wrongdoing"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Corporate Responsibility & ESG","word":"green bond","meaning":"a bond issued to finance projects with environmental benefits","translation":"trái phiếu xanh","example":"Green bonds have become an important source of climate finance.","synonyms":["environmental bond"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Corporate Responsibility & ESG","word":"sustainability-linked loan","meaning":"a loan whose financial terms depend partly on sustainability performance","translation":"khoản vay liên kết bền vững","example":"A sustainability-linked loan can reward progress against agreed targets.","synonyms":["ESG-linked loan"]},{"groupKey":"g3","groupName":"Nhóm 3 - Nâng cao Band 6.5+","topicName":"Corporate Responsibility & ESG","word":"impact investing","meaning":"investment intended to produce measurable social or environmental benefit alongside financial return","translation":"đầu tư tác động","example":"Impact investing channels capital towards projects with explicit social goals.","synonyms":["social-impact investment"]}]$json$::jsonb) AS x(
    "groupKey" TEXT, "groupName" TEXT, "topicName" TEXT, "word" TEXT, "meaning" TEXT, "translation" TEXT, "example" TEXT, "synonyms" JSONB
  )
)
INSERT INTO "VocabularyWord" ("id", "topicId", "word", "meaning", "example", "translation", "synonyms", "createdAt", "updatedAt")
SELECT
  'vw_' || md5(wd."groupKey" || '|' || wd."topicName" || '|' || lower(wd."word")),
  t."id", wd."word", wd."meaning", wd."example", wd."translation",
  ARRAY(SELECT jsonb_array_elements_text(wd."synonyms")), NOW(), NOW()
FROM word_data wd
JOIN "VocabularyGroup" g ON g."name" = wd."groupName"
JOIN "VocabularyTopic" t ON t."groupId" = g."id" AND t."name" = wd."topicName"
ON CONFLICT ("topicId", "word") DO UPDATE SET
  "meaning" = EXCLUDED."meaning",
  "example" = EXCLUDED."example",
  "translation" = EXCLUDED."translation",
  "synonyms" = EXCLUDED."synonyms",
  "updatedAt" = NOW();
